INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '般而言，属于我国养老制度第一支柱的是（）。', '{"A": "社会基本养老保险", "B": "个人储备的退休养老基金", "C": "个人养老金", "D": "企业年金"}', '["A"]', '《国务院关于企业职工养者保险制度改革的决定》提出，要建立基本养老保险与企业补充养老保险和个人储蒂性养老保险相结合的制度，实行国 家、企业和个人三方共同负担的养老制度。国家、企业和个人的养老保障体系，对应着我国养老保障体系的三支柱。第一支柱是基本养老保险（A正 确），分为城镇职工基本养老保险和城乡居民基本养老保险。第二支柱包括面向政府和事业单位的职业年金，以及面向企业的企业年金。第三支柱 主要是个人自愿开展的各类养老储蓄，主要是居民个人通过购买商业养老保险、养老目标基金、养老理财等金融产品为自己积累养老金的一种制度 安排。故本题选A。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于保险受益人的表述中，不正确的是（）。', '{"A": "投保以死亡为给付条件的保险时，被保险人和受益人不得为同一人", "B": "受益人应当由被保险人或者投保人在投保时指定，并在保险合同中载明", "C": "投保人和受益人为同一人时，被保险人可以为另一人", "D": "被保险人和受益人为同一人时，投保人不可以为另一人"}', '["D"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '假设某债券面额100元，票面利率5%，按年付息，剩余期限一年，以101元的净价买入该债券，则持有到期的收益率为（）。（答案取近似数值）', '{"A": "3.96%", "B": "5.15%", "C": "3.66%", "D": "4.95%"}', '["A"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于保险基本原则的表述中，错误的是（）。', '{"A": "保险利益是保险人所补偿损失的最高限额，被保险人所主张的赔偿金额不得超过其保险利益的金额或价值", "B": "在保险活动中，之所以规定最大诚信原则，主要归因于保险信息的不对称性和保险合同的特殊性", "C": "物上代位是指保险标的遭受责任范围内的损失，保险人按保险金额全数赔付后，可以依法取得该项标的物的所有权", "D": "禁止反言是指保险合同一方既然已放弃他在合同中的某种权利，将来不得再向他方主张这种权利。在保险实践中，它主要用于约束担"}', '["D"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '家庭债务量化管理的重点不包括（）。', '{"A": "通过家庭收支管理保证还贷活动的持续性", "B": "定期分析资产负债结构，保证客户投资的连续性", "C": "债务重组", "D": "定期分析债务结构的合理性，并提供调整建议"}', '["B"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '若某客户年应纳税综合所得超过100万元，则该客户缴存12000元到个人养老金账户，当年可以节税（）元。', '{"A": "3600", "B": "6000", "C": "2400", "D": "5400"}', '["D"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '无风险收益率为5%，市场期望收益率为10%的条件下，A证券的期望收益率为12%，β系数为1.1，B证券的期望收益率为15%，β系数为1.2：那么报 资者的投资策略为（）。', '{"A": "买进A证券或B证券", "B": "买进A证券", "C": "买进B证券", "D": "买进A证券和B证券"}', '["D"]', '根据CAPM模型，A证券：5%+（10%-5%）×1.1=10.5%，因为12%>10.5%，所以A证券价格被低估，应买进：B证券：5%+（10%-5%） ×1.2=11%，因为15%>11%，所以B证券价格被低估，应买进。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '个人取得下列所得，应缴纳个人所得税的是（）。 考月', '{"A": "选项需要个人所得税。按照财产租赁所得缴纳。B选项：按照国家有关城镇房屋拆迁管理办法规定的标准取得的拆迁补偿款，不用缴纳个人所得", "B": "按照国家规定取得的拆迁补偿款50万元", "C": "个人购买福利彩票中奖1000元", "D": "职工领取的原提存的住房公积金20000元"}', '["A"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '特雷诺指数和夏普比率（）为基准。', '{"A": "均以证券市场线", "B": "均以资本市场线", "C": "分别以资本市场线和证券市场线", "D": "分别以证券市场线和资本市场线"}', '["D"]', '特雷诺指数给出了单位风险的平均超额收益率，其风险使用的是系统风险，故是以β为横轴的证券市场线为基准；夏普比率等于投资组合在选择期间 内的平均超额收益率与这期间收益率的标准差的比值，它衡量了投资组合的每单位波动性所获得回报，故是以标准差为横轴的资本市场线为基准。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '根据个人所得税相关法律法规，下列所得免征个人所得税的是（）。', '{"A": "畅销书作者将自己文字作品手稿原件拍卖所得6，000元", "B": "持有期6个月的上市公司派发的股息红利2，000元", "C": "一次中奖收入8，000元", "D": "个人出租房屋所得5，000元"}', '["C"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王女士计划一年后送她女儿去国外留学，她的教育投资中最不适合持有的产品是（）。', '{"A": "货币型基金", "B": "私募股权基金", "C": "银行储蓄存款", "D": "债券型基金"}', '["B"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于企业年金，下列表述错误的是（）。', '{"A": "企业年金的缴费或由企业承担，或由企业和职工共同承担", "B": "企业年金基金属于委托人的清算财产", "C": "企业年金是企业为职工提供一定程度退休收入保障的补充性养老金制度", "D": "企业年金由企业自愿建立，国家不强制建立"}', '["B"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于中小企业财务管理需求主要内容的是（）。', '{"A": "投资管理", "B": "日常财务管理", "C": "支付结算", "D": "现金管理"}', '["A"]', '日常财务管理、现金管理和支付结算是中小企业的主要理财需求。故本题选择A选项。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于不可保意外伤害的是（）。', '{"A": "犯罪遭受的意外伤害", "B": "赛车遭受的意外伤害", "C": "旅游遭受的意外伤害", "D": "出差遭受的意外伤害"}', '["A"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '刘小姐今年大学毕业，就职于某商业银行。计划工作三年后出国留学，预计花费为15万元。目前有3万元的积蓄，每月工作收入1万元，若年投资回报 率6%，那么下列选项中，恰能达成出国留学计划的月储蓄率为（）。（答案取近似值）', '{"A": "20%", "B": "30%", "C": "35%", "D": "25%"}', '["B"]', '根据题意，期限n=3，利率r=6%，目前有3万元的积蓄进行投资，所以现值PV=-3，终值FV=15，代入到理财计算器中，得到PMT=-3.59，月储蓄 率=3.59/（1×12）=30%。故本题答率选30%。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '般而言，下列关于教育支出和教育投资特点的表述，错误的是（）。', '{"A": "投资金额大", "B": "支出与时间相对刚性", "C": "投资周期长", "D": "不确定因素少"}', '["D"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '根据中小企业主的人群分类特征，一般而言，（）类型的中小企业主经常与资金方打交道，对投资感兴趣，并精通投资，且通常具有多年的企业资 运作经验，对银行依赖度很低。', '{"A": "紧密联系型", "B": "精明生意人", "C": "企业主导", "D": "业余投资爱好者"}', '["B"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '）万元。（答案取近似值）', '{"A": "219.11", "B": "210.68", "C": "180", "D": "227.88"}', '["A"]', '根据题目，求可积累养老金，是看在4%的投资收益率的情况下，能揽多少钱，不用考虑通货膨胀的影响。期限n=60-40=20，I=4%，FV（n=20， PV=-100，1=4%，期末模式）=219.11万元。故本题选择A选项。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '某银行2023年3月5日公布的欧元即时汇率：现汇卖出价736.91，现钞卖出价736.91，现钞买入价710.84，现汇买入价731.77，客户想购买10000欧 元现钞，则当时至少需要准备（）元人民币。', '{"A": "71084", "B": "73691", "C": "75850", "D": "73177"}', '["B"]', '如果选择携带现金出境需要购买现钞。如果选择汇出境外则需要选择现汇账户，否则将承担一定损失。客户想购买，相当于银行卖出，所以选择现 钞卖出价。10000/100*736.91=73691元/人民币。故本题选择B选项。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '古先生的住院医疗费用保险年度免赔偿额为1000元，并包含一个20%的比例分条款和10000元的封顶条款。如果古先生发生保险责任范围内的医疗 费用，申请理赔给付，下列叙述正确的是（）。', '{"A": "医疗费用120000元时可获得95200元的保险给付", "B": "医疗费用10000元时可获得7200元的保险给付", "C": "医疗费用60000元时可获得47200元的保险给付", "D": "选项：因为有比例分摊条款，保险给付为（1200-1000）×（1-20%）=160（元），D选项说法错误：B选项：保险给付为（10000-1000）×"}', '["B"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于税收的表述，错误的是（）。', '{"A": "我国税收特征可以概括为强制性、无偿性、固定性", "B": "特定目的税类包括城市维护建设税和城镇土地税", "C": "税率的基本形式包括比例税率、累进税率、定额税率", "D": "目前我国增值税是各项税收中占比最大的一类税种"}', '["B"]', '特定目的税类包括城市维护建设税、耕地占用税、土地增值税、烟叶税和环境保护税。资源税类包括资源税和城镇土地使用税。选项B错误，因城镇 土地使用税属于资源税类，而非特定目的税类。其他选项均符合我国税收制度的实际情况', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '企业经营理念的变化促进了客户关系管理理论的发展，以下关于企业经营理念发展阶段的排序，正确的是（）。①客户中心论②利润中心论①销售中 心论产值中心论', '{"A": "0000", "B": "0000", "C": "0000", "D": "0000"}', '["D"]', '社会生产经营一般都经历了由卖方市场到买方市场的过程，即社会商品由供不应求到供大于求。在这样的发展过程中，企业经营理念经过了以下发 展阶段。1.产值中心论：2.销售中心论；3.利润中心论：4.客户中心论：故本题选择D选项。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '李某和赵某是夫妻，二人共同拥有100万元存款。甲是李某之母，乙是赵草之姐。赵某和李某均无其他亲属，2022年李某病逝，不久赵某也因为过分 悲伤于同年病故。如果按照法定继承处理，100万元存款的分配结果应是（）。', '{"A": "甲继承75万元，乙继承25万元", "B": "甲继承50万元", "C": "甲、乙各继承50万元", "D": "甲继承25万元，乙继承75万元"}', '["D"]', '遇产按照下列顶序继承：第一顺序：配偶、子女、父母；第二顺序：兄弟姐妹、祖父母、外祖父母。继承开始后，由第一顺序继承人继承，第二顺 序继承人不继承；没有第一顺序继承人继承的，由第二顺序继承人继承。100万元是夫妻共同财产，李某病逝后，赵某可分得：100/2+50/2=75万 元，甲继承25万元，赵某病故后，7继承75万元，故本题选择D选项。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '般而言，下列关于人寿保险的表述中，正确的是）。', '{"A": "“可乐”保单的保险金额会随着时间的推移而减少", "B": "万能寿险的保额可灵活调整，但保费的缴纳金额是固定的", "C": "两全寿险的缴费期限越短，年缴保费就越少", "D": "终身寿险的现金价值随保费缴纳期限的延长而降低"}', '["D"]', '定期寿险按照保额是否可变可以分为保额恒定定期寿险、保额递增定期寿险和保额递减定期寿险。保额递增定期寿险的保额按约定金额或比例递 增，例如生活费用指数递增的COLA保单（“可乐”保单）所以“可乐”保单选项错误：', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在投资和资产配置方面，下列指标中可反映家庭财产中资产实际变现能力的是（）。', '{"A": "融资率", "B": "资产收益率", "C": "资产负债结构", "D": "可配置投资性资产比率"}', '["D"]', '可配置投资性资产比率将让客户清楚地看到资产的实际变现能力，以及可用于投资的资产情况。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '根据理财规划服务包含的内容范围，理财规划服务可以分为（）。', '{"A": "综合理财规划和单项理财规划", "B": "投资前规划和投资后跟踪检查", "C": "投资规划和保障规划", "D": "定性规划和定量规划"}', '["A"]', '根据理财规划服务包含的内容范围，理财规划服务可以分为综合理财规划和单项理财规划。投资规划和保障规划属于单项规划的内容，没有“投资', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于家庭财产保险可保财产范围的是（）。', '{"A": "室内装修、装饰及附属设施", "B": "摩托车、拖拉机、汽车等机动车辆", "C": "室内家庭财产", "D": "自有居住房屋"}', '["B"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '融资比率体现了家庭的理财积极程度，融资比率等于（）。', '{"A": "总资产/总负债", "B": "投资性负债/投资性资产", "C": "投资性负债/总资产", "D": "总负资/投资性资产"}', '["B"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '乔某作为医师刚开始执业，由于从事新的诊疗技术工作，受到客户质疑的可能性较大。因此其最需要的保险产品为（）。', '{"A": "职业责任保险", "B": "普通医疗保险", "C": "产品责任保险", "D": "长期重大疾病保险"}', '["A"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '某开放式基金T日的基金净值为1.1元/份，T+1日的基金净值为1.2元/份，赎回费率为1.5%，某客户在T日上午10点赎回20000份，可得资金（）元。', '{"A": "22000", "B": "23640", "C": "24000", "D": "21670"}', '["D"]', '赋回总额=赎回份额×赎回日基金份额净值=20000×1.1元/份=22000元，赎回费用=赎回总额×赎回费率=22000×1.5%=330元，回金额=赎回 总额-赎回费用=22000-330=21670元。故本题选择D选项。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '以下选项中，不属于退休规划原则的是（）。', '{"A": "尽早性原则", "B": "谨慎性原则", "C": "平衡原则", "D": "收益最大化原则"}', '["D"]', '由于退休养老在客户众多理财目标中的特殊性和艰巨性，理财师在做相关规划时应注意如下几点原则：', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于自用性资产主要特征的是（）。', '{"A": "必要时可以随时变卖套现", "B": "增值性资产星然有一定的资本增值但不产生收入", "C": "安全性高", "D": "非增值性资产主要用于家庭生活品质的维护"}', '["C"]', '自用性资产的主要特征包括：', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于财富传承规划工具的表述中，不恰当的是（）。', '{"A": "人寿保险的优势在于流动性较好，能够实现抚养子女和事业传承", "B": "慈善基金会的优势是可以依法享受税收优惠，但缺乏流动性和灵活性", "C": "赠与的优势在于一定限额内可免交赠与税，但在开征赠与税的国家，赠与的免税额对富人而言远远不够", "D": "遗瞩的优势在于简单且为大众熟悉认可，劣势在于容易失去家族事务的私密性和引发遗产纠纷"}', '["A"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于杜邦分析法的描述，正确的是（）。', '{"A": "难以反应企业过去的经营业绩", "C": "可以对无形资产作出评价", "D": "难以关注短期财务结果"}', '["B"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '甲的生母离婚后嫁给甲的继父，甲与其生母和继父共同生活长达十年，后在2013年，甲的生父和继父相继去世，依照我国法律规定，甲（）。', '{"A": "只能继承生父的遗产", "B": "对生父、继父的遗产都无权继承", "C": "对生父、继父的遗产都有权继承", "D": "只能继承继父的遗产"}', '["C"]', '继子女享有双重的继承权。既有权继承继父或者继母的遗产，也有权继承其生父母的遗产。甲与其继父共同生活并受其抚养长达十年，形成了抚养', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于忠诚客户特点的是（）。', '{"A": "介绍亲朋购买", "B": "重复购买商品或服务", "C": "在熟悉的商家购买商品或服务时具有更大的话语权", "D": "对商品或服务表示非常满意"}', '["C"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '般而言，关于家庭债务管理，下列表述准确的是（）。', '{"A": "选项：融资比率=投资性负债/投资性资产，<50%是合理的，A错误。B选项：负债比率<50%，如果只是短期消费负债的话应20%，B错误。C", "B": "当家庭的负债比率低于50%，且短期消费负债低于40%时，客户总体债务情况是合理的", "D": "合理的家庭债务负担率应低于50%，这样的情况下，家应其他支出所需才不会挤占同期的收入，不会对家庭生活品质产生负面影呵"}', '["C"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '家庭生活支出比率是支出结构分析中较为重要的指标。一股情况下，收入高者，其消费性支出也会较高，但根据经验法则，在没有贷款本息负担的情 况下，消费性支出占税后总收入的比例不超过（）为宜，在有贷款本息负担的情况下，以不超过（）为宜。', '{"A": "50%;70%", "B": "50%;30%", "C": "30%;50%", "D": "70%;50%"}', '["D"]', '家庭生活支出比率是支出结构分析中较为重要的指标。一般情况下收入高者，其消费性支出也会较高。但根据经验法则。在没有贷款本息负担的情 况下，消费性支出占税后总收入的比例以不超过70%为宜，在有贷款本息负担的情况下，以不超过50%为宜。故本题答案选“70%；50%”。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '研究表明，投资者倾向把已经盈利的股票卖出，同时倾向持有已经亏损的股票，这是因为（）。', '{"A": "反应过度和反应不足", "B": "损失厌恶", "C": "过度自信", "D": "处置效应"}', '["D"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '投资者马女士的资产组合中，股票A占60%，其预期收益率为7%，标准差10%；股票B占40%，其预期收益率为13%，标准差为20%，该资产组合的 预期收益率为（）。', '{"A": "8.2%", "B": "9.4%", "C": "7%", "D": "6.5%"}', '["B"]', '根据预期收益率的公式，计算得出：E（R）=60%×7%+40%×13%=9.40%。故本题答案选~9.40%”。 10', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '养老金个人账户积累总额54000元，过渡性养老金政第为工龄×5元。吴先生参加了企业养老金计划，供款15年，个人供款是个人当期收入的5%，企业 实行对等缴费，理财投资回报率为4%。吴先生退休后第一年生活成本5万元，退休后预期寿命为18年。 吴先生每月可以从国家基本养老保险制度领取基础养老金（）元。', '{"A": "1400", "B": "1800", "C": "1500", "D": "1600"}', '["A"]', '基础养老金支付的月标准为：（地方[省、自治区、直辖市或地(市)]上年度职工月平均工资+个人指数化月平均工资）/2×缴费年限×1%= (2000+6000）/2×1%×35=1400（元）。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2016年10月，吴先生年满60岁，从某国企退休。吴先生拥有35年的工龄，退休前每月收入为6000元，当地社会平均收入为2000元，退休时国家基 本养老金个人账户积累总额54000元，过渡性养老金政策为工龄×5元。吴先生参加了企业养老金计划，供款15年，个人供款是个人当期收入的 5%，企业实行对等缴费，理财投资回报率为4%。吴先生退休后第一年生活成本5万元，退休后预期寿命为18年。 吴先生个人账户月养老金为（）元。', '{"A": "400", "B": "388", "C": "356", "D": "278"}', '["B"]', '个人账户月支付标准为本人账户储蓄额/计发月数。吴先生个人账户的月养老金为54000+139=388(元)。计发月数表如下（考试会提供）：', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2016年10月，吴先生年满60岁，从某国企退休。吴先生拥有35年的工龄，退休前每月收入为6000元，当地社会平均收入为2000元，退休时国家基本 养金个人账户积累总额54000元，过渡性养老金政第为工龄×5元。吴先生参加了企业养老金计划，供款15年，个人供款是个人当期收入的5%，企业 实行对等缴费，理财投资回报率为4%。吴先生退休后第一年生活成本5万元，退休后预期寿命为18年。 吴先生每月的过渡性养老金为（）元。', '{"A": "185", "B": "180", "C": "175", "D": "200"}', '["C"]', '吴先生2016年10月退休，拥有35年的工龄，是"中人，过渡性养老金政策为工龄×5元，其过渡性养老金为35×5=175(元)。 11', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2016年10月，吴先生年满60岁，从某国企退休。吴先生拥有35年的工龄，退休前每月收入为6000元，当地社会平均收入为2000元，退休时国家基本 养老金个人账户积累总额54000元，过渡性养老金政策为工龄×5元。吴先生参加了企业养老金计划。供款15年，个人供款是个人当期收入的5%，企业 实行对等缴费，理财投资回报率为4%。吴先生退休后第一年生活成本5万元，退休后预期寿命为18年。 吴先生可以从国家基本养老保险计划领取月基本养老金（）元。', '{"A": "1963", "B": "1090", "C": "790", "D": "890"}', '["A"]', '基本养老金=基础养老金+个人账户养老金+过渡养老金=1400+388+175=1963(元)。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2016年10月，吴先生年满60岁，从某国企退休。吴先生拥有35年的工龄，退休前每月收入为6000元，当地社会平均收入为2000元，退休时国家基本 养老金个人账户积累总额54000元，过渡性养老金政策为工龄×5元。吴先生参加了企业养老金计划，供款15年，个人供款是个人当期收入的5%，企业 实行对等缴费，理财投资回报率为4%。吴先生退休后第一年生活成本5万元，退休后预期寿命为18年。 吴先生的基本养老金替代率是（）。（相比退休前当期收入）', '{"A": "14.5%", "B": "32.7%", "C": "12.9%", "D": "15.7%"}', '["B"]', '养老金替代率=个人基本养老金/个人退休前工资，所以，吴先生的基本养老金替代率为1963+6000=0.327，即32.7%。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2016年10月，吴先生年满60岁，从某国企退休。吴先生拥有35年的工龄，退休前每月收入为6000元，当地社会平均收入为2000元，退休时国家基本 养老金个人账户积累总额54000元，过渡性养老金政策为工龄×5元。吴先生参加了企业养老金计划。供款15年，个人供款是个人当期收入的5%，企业 实行对等缴费，理财投资回报率为4%。吴先生退休后第一年生活成本5万元，退休后预期寿命为18年。 吴先生的企业年金积累大约是（）元。（按昊先生的企业年金供款额一直不变计算）', '{"A": "154626", "B": "159924", "C": "149940", "D": "147654"}', '["D"]', '吴先生供款当期收入的5%，企业实行对等缴费，那么每月投入共计=6000×5%×2=600(元)，N=15×12=180，PMT=-600，『=4%/12，（期末付 款），求得FV=147649.47。故本题答案取近似值，选“147654°。 12', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生夫妻目前均40岁，预计退休年龄均为60岁，儿子12岁，目前读初一。家庭年税后收入为30万元，张先生20万元，妻子刘女士10万元。家庭目 前有房屋（市值）100万元，汽车（折旧)10万元，目前储蓄15万元，家庭无负债，家庭年生活费用开支为12万元。其中，张先生个人年生活支出为4万 元，张先生家庭的理财目标有：准备应急基金6万元，教育基金现值30万元，退休基金夫妻二人计120万元。 假定张先生目前去世的适，遗属退休前生活费用支出的现值为160万元，不考虑妻子收入的因素下，通过遗属需求法，张先生的寿险保障需求为（）。 (不考虑通胀及收入增加等问题）', '{"A": "141万元", "B": "191万元", "C": "311万元", "D": "301万元"}', '["B"]', '张先生的寿险保障需求=（应急基金+教育基金现值+退休基金+生活费现值）-现有资产（房屋+汽车+储蓄）=(6+30+120+160)- （100+10+15)=191(万元）。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生夫麦目前均40岁，预计退休年龄均为60岁，儿子12岁，目前读初一。家庭年税后收入为30万元，张先生20万元，麦子刘女士10万元。家庭 目前有房屋（市值)100万元，汽车(折旧日)10万元，目前储蓄15万元，家庭无负债，家庭年生活费用开支为12万元。其中，张先生个人年生活支出为4 万元，张先生家庭的理财目标有：准备应急基金6万元，教育基金现值30万元，退休基金夫妻二人计120万元。 使用生命价值法计算寿险保额时的步骤为（）。①以适当的贴现率计算预期净收入的现值②明确个人的在职期或服务期③用年收入减除税及消费等 总开支，计算净收入估算个人未来在职期的年收入现值', '{"A": "210.89", "B": "226.95", "C": "=12539-3000=9539，求得PV=227.13，故本题选择B选项。", "D": "210.56"}', '["B"]', '生命价值法又称净收入弥补法，是以家庭成员的生命价值为依据，来确定家庭寿险保额的基本方法。生命价值法主要分为以下几个步骤：①明确个 人的在职期或服务期。个人年龄越大，在职期则越短，反之，则在职期越长。②估算个人未来在职期的年收入现值。个人在职期越短，未来工作 收入的现值就越小，应有的保额也就越低。反之则越高。③计算净收入，用年收入减除税及消费等总开支。总支出占总收入的比例越大，净收入 假设张先生已经购买了某寿险产品，最近由于一些突发事件，除了家庭已有的紧急准备金外还需要一笔资金，那么以下最优的解决方案是（）， 张先生还不到退休年龄，无法从国家基本养老账户中提取属于其个人的部分；退保成本较高，不宜进行退保：逆按揭是指将自住物业抵押给银行， 每月从银行领取一定的生活开支，以保障退休生活的一种按揭形式，适合退休后生活无保障人群，不适合作为突发事件的应急资金使用。 13 对于张先生家庭，理财师小王给出了整体的保险规划方案，下列说法正确的是（）。 张先生的孩子还小，应优先考虑孩子的教育费用，而不是寿险需求；理财师应根据客户的理财目标和家庭的财务状况推荐合适的理财产品，不能为 了自已所属机构的利益推荐理财产品：并不是所有的寿险产品的价值都会收到经济形势的影响，通常分红性质的寿险产品如投连险、万能险等，其 价值会受到经济形势的影响。 假定李先生每月未可结余2000元，也准备用于养者金投资，如果按月复利计算，则李先生60岁退休时可积累（）万元退休金。（答案取近似数值） 根据题目，目前的长期投资回报率为6%/年，月利率=6%/12=0.5%，期限n=60-45=15，15*12=180，PV=200000，年金C=2000，期末模式， 代入计算器，FV=107.25万元。故本题选择B选项。 假定季先生长期投资回报率变为8%/年，并希望在60岁退休时累积100万元养老金，按月复利计息，则每月月末需至少定期定额投资（）元。（答案 取近似数值) 根据题目，长期投资回报率为8%/年，月利率=8%/12=0.66667%，期限=180，PV=-200000，FV=1000000，期末模式，代入到计算器，求得 年金C=979。故本题选择C选项。 根据李先生现有的消费水平及假设的通胀率，届时每月要支出（）元才可以保持现有的消费水平。（答案取近似数值） 目前每月支出8000元，期限n=60-45=15，15*12=180，每月支出为8000×（1+3%/12）^180=12539，故本题选择D选项。 14 为保持当前的生活水平，除了既定的退休金，季先生退休时还需要积累（）万元养老金。（答案取近似数值） 实际投资回报率=（1+名义投资回报率）/（1+通货膨胀率）-1=[(1+5%)/(1+3%)-1)=1.94%1.94%/12=0.16%，期数=（85-60）×12=300,', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '冯先生42岁，是一家公司的控股股东及董事长。该公司净资产8000万元，冯先生拥有60%股份，公司每年税后利润300万元。冯太太39岁，全职太 太，女儿13岁，初一学生。冯先生家庭年收入为200万元，年支出50万元，其中冯先生支出30万元，冯太太和女儿各支出10万元。家庭有一套市值 1000万元的住房（无贷款），银行存款100万元，汽车一辆价值80万元。得知上述情况后，理财师约了冯先生探讨家庭保障规划。 根据以上材料，回答下列问题。 （1）理财师对冯先生家庭进行风险管理的第一步是（）。', '{"A": "选项：正确。机动车辆损失保险（车损险）通常只覆盖车辆因事故、自然灾害等原因造成的自身损失，不包括对第三方造成的损失或责任。B选", "B": "交强险包含无责任赔偿", "D": "交强险是强制保险", "C": "商业三者险是交通事故的第一赔款人"}', '["C"]', '风险管理的基本程序分为风险识别、风险估测、风险评价、选择风险管理技术和评估风险管理效果五个环节。故本题选择B选项。 （2）冯先生作为控股股东的责任风险可以通过（）来转移。 （1）产品责任保险承保因产品缺陷致使用户或消费者遭到人身伤亡或财产损失时，依法应由该产品的制造、销售或修理商承担的经济赔偿责任。 （3）一般而言，关于冯先生家庭保障规划，下列说法错误的是（）。 女儿由于此时年龄较小，对于青少年来说，常见的风险包括意外伤害、疾病以及未来教育的费用支出。（1）意外险：青少年由于好奇心强、活动 量大，容易发生意外。因此，配置意外险是很有必要的，可以在孩子遭遇意外伤害时提供经济上的保障。（2）医疗险：医疗险可以覆盖医疗费 （5）关于冯先生家庭的机动车辆保险，理财师的下列叙述中，错误的是（）。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生有100万资金，投资组合包括股票X、股票Y、债券Z，其中股票X的预期收益率是15%，标准差是25%；股票Y的预期收益率是12%，标准差是 20%：债券Z的预期收益率是6%，标准差是8%；股票X和股票Y的相关系数为0.6，股票X和债券Z的相关系数为0.2，股票Y和债券Z是相关系数是0.1。 假设张先生同时投资股票X和股票Y，其中股票X的权重为40%，股票Y的权重为60%，则该投资组合的预期收益率是多少（）。', '{"A": "选择风险低的投资组合", "B": "选择预期收益高的投资组合", "C": "选择相关性高的投资组合", "D": "选择分散投资，在一定风险情况下预期收益高的投资组合"}', '["D"]', '根据预期收益率的公式，计算得出：E（R）=40%×15%+60%×12%=13.2%，故本题答案选择C选项。 上述投资组合中标准差为（）。 (答案取近似数值) 两资产组合的标准差公式为：p=Vw+w +2wxwypxyoxoy 16 根据第（1）问中的投资组合计入债券Z，标准差会怎么变化0）。 第一问的投资组合只有X和Y(标准差19.7%)，加入债券Z后，根据投资组合理论，当引入与原有组合相关性较低的资产时，组合标准差会降低(分散化 效应)。故本题答案选择D选项。 按照现有的投资组合原则，下列说法正确的是（）。 选项A错误：只选风险低的，可能收益也低，不是最优，投资要平衡风险和收益。选项B错误：只选预期收益高的，风险可能极大，不符合合理投资原 则。选项C错误：相关性高的资产组合，分散风险效果差，不能有效降低组合波动。选项D正确：分散投资，在控制一定风险前提下追求高预期收益， 符合现代投资组合理论(通过资产分散，降低非系统性风险，在有效前沿上找到风险-收益平衡的组合)。答案选D。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于缴费确认型与待遇确定型企业年金的说法，正确的是（）。 ■A.待遇确定型企业年金风险全部由雇主承担 ■B.缴费确认型企业年金养老金取决于个人账户余额', '{"C": "待遇确定型企业年金是一种完全积累类型的退休金计划", "D": "两者的雇主责任和发放方式都相同", "E": "两者的缴费模式相同"}', '["A", "B"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '教育投资规划的重要性，一般体现在（）。 ■C.受教育程度会直接影响收入水平', '{"A": "教育成本的不断升高", "B": "中国家庭对子女教育的重视", "D": "成年人对继续教育的需求不断增加", "E": "职场对学历和知识水平的要求越来越高"}', '["A", "B", "C", "D", "E"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '国民经济中，中小企业在下列（）方面起着重要的作用。', '{"A": "促进市场竞争", "B": "保持社会稳定", "C": "增加就业机会", "E": "拓宽融资渠道"}', '["A", "B", "C", "D"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '契税的课税对象包括（）。 □A.房屋赠予', '{"B": "房屋租赁", "C": "房屋交换", "D": "土地使用权转让", "E": "国有土地使用权出让"}', '["A", "C", "D", "E"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '相对于大型企业，中小企业具有以下（）的特点，同样也面临着经营风险高，资金周转需求旺盛，融资难，企业主个人和企业财务联系紧密的挑战', '{"A": "经营决策权高度集中", "B": "有效率", "C": "规模小", "D": "投资见效快", "E": "机制灵活"}', '["A", "B", "C", "D", "E"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关键人物的风险管理对策有（）。', '{"A": "提高员工福利、留住人才", "B": "根据具体情况量身定制保险计划，包括将员工的配偶和子女纳入保障计划中", "C": "以团体形式购买保险", "D": "为员工提供养老、健康、伤残、死亡等多方面的团体保障", "E": "关键人物保险"}', '["A", "B", "C", "D", "E"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '家族信托的优势有（）。 ■A.节税避税', '{"B": "财产安全隔离", "C": "信息透明", "D": "经过遗产认证", "E": "财富灵活传承"}', '["A", "B", "E"]', '家族信托的优势：①财富灵活传承；②财产安全隔离：③节税避税：④信息严格保密。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2024年9月，王某和李某的孩子小王年满4岁。下列关于王某和李某当年分配子女教育专项附加扣除比例的方法，正确的（）。', '{"A": "王50%，李50%", "B": "王20%，李80%", "C": "王100%，李0%", "D": "王0%，李100%", "E": "王80%，李20%"}', '["A", "C", "D"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于家庭结余，下列表述正确的有（）。', '{"A": "自由结余占总结余的比例过高，往往体现出较高的理财积极度", "B": "自由结余可以用于实现短期理财目标", "C": "理财结余是指税后工作收入减去相应的日常生活支出和专项支出后的盈余部分", "D": "生活结余是指税后工作收入减去家庭生活支出后的盈余部分", "E": "专项结余占总结余的比率通常也表现出客户的理财积极度"}', '["B", "D", "E"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '员工薪酬与退休规划有着紧密关系，主要表现在哪些方面（）。', '{"A": "退休规划会影响薪酬结构的选择，进而影响员工的职业选择", "B": "薪酬中的延期收入会给退休规划提供更多收入保障", "C": "薪酬中的当期收入会通过个人收入分配方式为退休规划提供财务来源", "D": "薪酬中的延期收入会通过个人收入分配方式为退休规划提供财务来源", "E": "薪酬中的当期收入会给退休规划提供更多收入保障"}', '["A", "B", "C"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '股而言，理财规划服务的对象是一个“核心”家庭及其主要的财务资源，这里针对的“核心”家庭成员包括（）。 □A.未成年子女', '{"B": "配偶", "C": "需要养的父母", "D": "客户本人", "E": "经济上已独立的子女"}', '["A", "B", "C", "D"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '退休养老规划通过提供（）等一系列专业化服务，为个人客户实现退休安排，维护自尊、自立、合理水准的退休生活。 □B.债务规划 □D.财务分析', '{"A": "财务规划", "C": "教育金规划", "E": "投资管理"}', '["A", "D", "E"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在银行客户关系管理中，提供优质服务应遵循（）。', '{"A": "无条件满足客户全部诉求", "B": "做好超常服务", "C": "做精分内工作", "D": "做足额外服务", "E": "不做本职无关工作"}', '["B", "C", "D"]', '如何做才能让客户满意尤其非常满意，通常从以下几点值得理财师遵循：做精分内服务、做足额外服务、做好超常服务。故本题答案选“做好超常 服务。做精分内工作。做足额外服务”', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于代书遗喝和录音遗嘱的说法，正确的有（。', '{"A": "代书遗喔中的代书人只是遗嘱的文字记录者", "B": "代书遗喔中签名的见证人不少于两人", "C": "代书遗瞩应当有两个以上的见证人在场见证", "D": "由于录音遗嘱易被人剪辑，因此不如口头遗嘱可靠", "E": "以录音形式立的遗嘱，应当有两个以上的见证人在场见证"}', '["A", "B", "C", "E"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '社会养老保险具有的特点包括（）。 ■A.企业单位必须投保', '{"B": "影响大、受众多", "C": "投资回报率高", "D": "强行实施", "E": "国家立法"}', '["A", "B", "D", "E"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在为中小企业主进行税务规划的过程中，以下有利于企业降低税务负担的有（）。 ■A.采购货物时尽量从小规模纳税人处进货', '{"B": "通过除销方式调整收入确认时间", "C": "利用政府针对行业、地区出台的税收倾斜政策选择公司注册地点", "D": "采购货物时从一般纳税人处进货并开具增值税发票", "E": "在偿债能力范围内优先考虑适度负债经营"}', '["B", "C", "D", "E"]', '', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）2024年，43岁的赵先生是一家知名企业的高管，月收入5万元，年终奖30万元。妻子李女士43岁，是一位资深律师，月收入 3万元，年终奖20万元。两人育有一个15岁的儿子和一个10岁的女儿，儿子正读高中，女儿正读小学，家庭每月生活开销5万元，其中孩子教育费用 每月1万元。赵先生家庭有一套市值1,000万元的自住房产，剩余房贷200万元，贷款年利率4%，剩余还款期限15年，等额本息还款，还有一套无房 贷的投资性房产，市值500万元，每月租金收入8000元，家庭有活期存款50万元，定期存款150万元，债券市值200万元，股票市值300万元，混合 型基金币值200万元。赵先生计划3年后送儿子出国留学，预计留学费用每年50万元，学制4年；同时需为女儿储备教育资金，计划10年后送女儿出 国留学，预计留学费用每年40万元，学制4年，此外，夫妻二人希望在20年后退休，退休后第一年的生活费用现值为30万元，预计退休后生活25 年，近期赵先生有购置一辆价值50万元汽车的打算，考虑通过消费贷款解决资金问题，夫妻双方均有社保，但商业保险配置不足，赵先生的年收入 适用个人所得税税率为30%，他希望能进行合理的税收规划。以上收入均为税前，假设投资回报率为4%，通货膨胀率为3%，学费每年年初支付， 不考虑学费增长率，根据以上材料，回答下列问题。 赵先生家庭的税前工作性年收入为（）万元。 为在儿子上大学时一次性,准备好留学费用，赵先生家庭从现在开始每月月未需要至少投入（）万元教育基金。（不考虑上大学期间教育金的投资回 报，答案取近似数值)', '{"A": "投连险：兼具保险和投资功能，但其保障功能较弱，投资风险较高，不符合“优先保障基本家庭责任”的需求。B分红险：侧重储蓄和分红，保", "B": "分红险", "C": "责任险", "D": "定期寿险"}', '["D"]', '首先确定目标资金总额：儿子计划3年后出国留学，学制4年，每年留学费用50万元，学费每年年初支付，且不考虑学费增长率和大学期间教育金 的投资回报。因此，3年后需一次性准备的总费用为4年学费总和：总费用=50万元/年×4年=200万元。利率=4%+12=0.3333%， n=3×12=36，FV=200，期末模式，求得年金C=5.24，故本题答案选择A选项。 赵先生家庭为准备儿子的教育留学基金，下列投资产品中最适合的是（）。 退休后第一年的生活费用需考虑通货膨胀的影响。30×（1+3%）^20=54.18万元，故本题答案选择A选项。 赵先生家庭若贷款50万元购置汽车，选择消费贷款，贷款期限5年，年利率3%，则每月等额本息还款额为（）元。（答案取近似数值） 本题求的是年金C，C（PV=50万，n=5×12=60，I=3%+12=0.25%，期末模式）=8984，故本题答案选择D选项。 为保障家庭生活稳定，赵先生考患为自己配置商业保险，他应优先配置的保险是（）。', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）2024年，43岁的赵先生是一家知名企业的高管，月收入5万元，年终奖30万元。麦子李女士43岁，是一位资深律师，月收入 3万元，年终奖20万元。两人育有一个15岁的儿子和一个10岁的女儿，儿子正读高中，女儿正读小学，家庭每月生活开销5万元，其中孩子教育费用 每月1万元。赵先生家庭有一套市值1,000万元的自住房产，剩余房贷200万元，贷款年利率4%，剩余还款期限15年，等额本息还款，还有一套无房 贷的投资性房产，市值500万元，每月租金收入8000元，家庭有活期存款50万元，定期存款150万元，债券市值200万元，股票市值300万元，混合 型基金币值200万元。赵先生计划3年后送儿子出国留学，预计留学费用每年50万元，学制4年；同时需为女儿储备教育资金，计划10年后送女儿出 国留学，预计留学费用每年40万元，学制4年，此外，夫妻二人希望在20年后退休，退休后第一年的生活费用现值为30万元，预计退休后生活25 年，近期赵先生有购置一辆价值50万元汽车的打算，考虑通过消费贷款解决资金问题，夫妻双方均有社保，但商业保险配置不足，赵先生的年收入 适用个人所得税税率为30%，他希望能进行合理的税收规划。以上收入均为税前，假设投资回报率为4%，通货膨胀率为3%，学费每年年初支付， 不考虑学费增长率，根据以上材料，回答下列问题。 赵先生希望进行财富传承规划，下列最能保证资产按自已意愿分配的方式为（）。 25 对赵先生而言，以下方式中无法降低个人所得税的是（）。 ■A.缴存个人养老金 ■B.购买高额商业保险', '{"A": "成熟期，加大股权、期权类资产投资", "B": "高峰期，逐步降低资产组合风险", "C": "维持期，大部分资金投资高流动固定收益资产", "D": "稳定期，将追求适当投资收益的组合投资作为其主要投资方式"}', '["D"]', '剩余房贷=PV=200万元，利率=4%+12=0.33%，n=15×12=180，期末模式，求得C=1.48，故本题答案选择D选项。 赵先生家庭年利率为1.85%的150万元五年期定期存款，提前3年支取，并将全部资金用于短期年化符合收益率6%的产品，则3年后上述投资的最终 收益为（）万元。（假设活期利率为0.3%)(答案取近似数值) 1.赵先生的150万元为五年期定期存款，年利率1.85%，但提前3年支取（即已存2年）。根据规则，定期存款提前支取全部按活期利率计息（活期 利率0.3%）。已存2年的活期利息=本金×活期利率×存期=150万×0.3%×2=0.9万元，提前支取时的总资金=本金+活期利息=150万+0.9万 =150.9万元。2.短期投资的收益计算将150.9万元用于年化复合收益率6%的短期产品，投资期限3年，按复利计算：150.9×（1+6%） 保险金信托是将人寿保险与信托相结合的金融工具，其核心优势在于通过专业信托机构实现资产的管理、传承与保护。A隐私性强：信托关系的设 立和执行通常不公开，受益人和分配细节可避免向公众披露，具有较强隐私性，属于其优点。B资产隔离保护：信托财产独立于委托人、受托人及 受益人的其他财产，可在一定程度上隔离债务风险或婚姻财产分割等问题，属于其优点。C可灵活指定受益人和分配方式：委托人可根据意愿灵活 设定受益人范围、分配条件（如年龄、学业成就等）和方式，实现个性化传承，属于其优点。D无需专业机构管理：保险金信托必须由具备资质 的信托公司作为受托人进行专业管理，委托人无法自行管理信托财产，故本题答案选择D选项。 根据《国务院办公厅关于推动个人养老金发展的意见》，赵先生家庭当年缴纳个人养老金额度的上限为（）万元。 根据《国务院办公厅关于推动个人养老金发展的意见》，参加人每年缴纳个人养老金的上限为12000元。赵先生家庭有赵先生和李女士两人符合 缴纳条件。所以家庭当年缴纳个人养老金额度的上限为1.2×2=2.4万元，答案选B. 赵先生工作所在地上年度在岗职工月平均工资为1万元，个人养者保险缴存比例为8%，则先生每月个人养老保险的缴存金额上限为（）元。 根据我国养老保险缴存规定，个人养老保险缴费基数通常有上下限限制，上限一般为当地上年度在岗职工月平均工资的300%。已知赵先生工作所 在地上年度在岗职工月平均工资为1万元，因此缴费基数上限为：10000×3=30000元，个人养老保险缴存比例为8%，则每月缴存金额上限为： 30000×8%=2400元。尽管赵先生月收入5万元高于缴费基数上限，但养老保险缴存金额按上限基数计算，故最终上限为2400元。 27 在计算个人所得税时，赵先生选择将子女教育专项附加扣除在自已这边全额扣除，则他全年的子女教育专项附加扣除合计金额是（）万元。 根据我国个人所得税专项附加扣除相关规定，子女教育专项附加扣除标准为每个子女每月2000元，父母可以选择由其中一方按扣除标准的100% 扣除，也可以选择由双方分别按扣除标准的50%扣除。赵先生家庭有两个子女（15岁儿子和10岁女儿），均符合子女教育专项附加扣除条件。每 个子女每月扣除2000元，两个子女全年合计扣除：4000×12=48000元。 赵先生参加了个人养老金计划，以下不符合个人养老金领取条件的是（）。 个人养老金资金账户实行封闭运行，未满足领取条件的，不得支取资金。参加人达到以下任一条件的，可以按月、分次或者一次性领取个人养老 金：(1)达到领取基本养老金年龄；(2)完全丧失劳动能力；(3)出国(境)定居；(4)国家规定的其他情形。故本题答案选择A选项。 赵先生退休时，关于个人养老金领取万式的说法，正确的是（）。 即期收益率为债券每年支付的利息与债券价格比值.即（4%x100）/98=4%.故本题洗B 28 赵先生个人处于生命周期的（），处于这一阶段的投资者应当（）。 赵先生43岁，处于35-44岁区间，子女分别为15岁（高中）和10岁（小学），属于家庭成长期。此时夫妻双方收入稳定且较高，核心需求是储备 子女教育金和退休金，符合稳定期的特征。稳定期的投资策略：稳定期需在积累资金的同时控制风险，既不能过于保守（错失收益），也不能过 度激进（影响教育、养老目标），因此追求适当投资收益的组合投资是主要方式。故本题答案选择D选项。 29', 1);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于退休规划主要目标的是（）。', '{"A": "退休后不需要再工作", "B": "确保子女有生活保障", "C": "退休后财务自由", "D": "过理想的生活"}', '["C"]', '一份退休规划不只是告诉客户他退休时需要多少钱、现在应该做哪些投资准备，而且能够告诉该客户：他和家人在退休后能享受什么样的生活品 质，其中应该包括根据客户现在已经拥有的资源(投资性资产)和未来的资源（未来来自社会福利、延迟权益、商业保险等方面的收入）他和家人能够支 付的每年的固定支出预算是多少，每年的家庭休闲旅游的预算可以是多少，可以支付的赠养费用是多少，对子女的支持程度如何等方面的具体内 容，并且还要评估客户的其他理财目标对退休后的生活品质的影响，比如客户希望退休后能去环球旅行，那么这项目标对其他的财务支出计划（比如 准备为女儿操办一次害华婚礼的影响如何。这样的理财规划书能让客户感受到自已到底规划的是什么，并且按照规划的内容去制定每年的各项支出 预算，在理财师的帮助下有计划地享受自己的退休生活，退休规划并不是要实现财务自由。故本题选择C选项。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列债券中，对市场利率最敏感的是（）。 考前', '{"A": "10年期，息票率8%", "B": "5年期，息票率8%", "C": "10年期，息票率10%", "D": "5年期，息票率10%"}', '["A"]', '影响债券价格波动性的因素包括：（1）债券的票面利率，债券的票面利率越低，波动性越大：（2）债券的期限，债券的期限越长，波动性越大； （3）债券的到期收益率，债券的到期收益率越小，波动性越大。债券的价格波动与市场利率有关，债券的期限越长，波动性越大，利率敏感度越 高。选项“10年期。息票率8%”是期限最长，利率最低，也就是波动性最大的，所以它对市场利率最敏感。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '资产配置中，战略性资产配置主要是指以（）为基础，构造一定风险水平上的资产比例，并长期保持不变。', '{"A": "不同资产类别的收益情况与投资者的风险偏好、实际需求", "B": "市场的短期变化", "C": "风险和收益特征", "D": "风险特征"}', '["A"]', '资产配置从时间跨度和风格类别上看，可分为战略性资产配置、战术性资产配置和资产混合配置等：战略性资产配置策略以不同资产类别的收益情 况与投资者的风险偏好、实际需求为基础，构造一定风险水平上的资产比例，并长期保持不变。战术性资产配置则是在战略资产配置的基础上根据 市场的短期变化，对具体的资产比例进行微调。故本题答案选择“不同资产类别的收益情况与投资者的风险偏好、实际需求”。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '投资规划是综合理财规划服务的重要组成部分，下列不属于投资规划方案主要环节的是（）。', '{"A": "设定预期报酬率", "B": "跟踪建议", "C": "产品配置", "D": "资产配置"}', '["B"]', '投资规划方案主要包括设定预期报酬率、资产配置、产品配置三个主要环节。不包括“"跟踪建议”，故本题答案选“跟踪建议”。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '某被保险人投保100万元的财产保险，在保险期限内，由于第三者的责任导致被保险人的财产损失50万元，被保险人从第三者那里获得赔款40万 元，同时被保险人又向保险人要求赔付50万元，对此保险人的处理方式是（）。', '{"A": "不予赔付", "B": "赔50万元", "C": "赔40万元", "D": "赔10万元"}', '["D"]', '保险的补偿原则是指当被保险人发生损失时，通过保险人的补偿使被保险人的经济利益恢复到原来水平，被保险人不能因损失而得到额外收益的 原则。保险补偿原则包含两个基本含义：', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，符合领取企业年金必要条件的是（）。', '{"A": "达到国家规定的退休年龄", "B": "企业年金缴纳达到15年（含）以上", "C": "丧失部分劳动能力", "D": "企业年缴费金额已经达到50万元（含）以上"}', '["A"]', '根据《企业年金办法》的规定，职工领取企业年金的条件是：在达到国家规定的退休年龄（A符合题意）或者完全丧失劳动能力时，可以从本人企业 年金个人账户中一次或定期领取企业年金，也可以将本人企业年金个人账户资金全部或者部分购买商业养老保险产品，依据保险合同领取待遇并享 受相应的继承权；出国（境）定居人员的企业年金个人账户资金，可以根据本人要求一次性支付给本人；职工或者退休人员死亡后，其企业年金个人账', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，关于个人所得税赠养老人专项附加扣除，说法错误的是（）。', '{"A": "纳税人赠养子女在世的年满60岁祖父母、外祖父母的赠养支出，可以税前扣除", "B": "赠养老人专项附加扣除采取定额标准扣除方式", "C": "纳税人赌养年满60岁父母可以税前扣除", "D": "父母中有一位年满60周岁的，纳税人就可以按照规定标准扣除"}', '["A"]', '国务院发布关于提高个人所得税有关专项附加扣除标准的通知：贿养老人专项附加扣除标准，由每月2000元提高到3000元。其中，独生子女按照每 月3000元的标准定额扣除；非独生子女与兄弟姐妹分摊每月3000元的扣除额度，每人分摊的额度不能超过每月1500元。在《个人所得税专项附加 扣除暂行办法》，被赚养人是指年满60岁的父母，以及子女均已去世的年满60岁的祖父母、外祖父母。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王某与其儿子一起开车出门时因遇到泥石流，王某当场死亡，其儿子送至医院后教治无效死亡，王某的妻子早已去世，家中只有王某的女儿和儿娘， 王某与其儿子各有遗产200万元且均未设立遇嘱，则王某的女儿和儿娘各应继承的遗产为（）。', '{"A": "女儿100万元，儿娘300万元", "B": "各100万元", "D": "各200万元"}', '["A"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '反映公司在一定时期内经营成果的财务报表是（）。', '{"A": "资产负债表", "B": "利润分配表", "C": "利润表", "D": "现金流量表"}', '["C"]', '反映公司在一定时期内经营成果的财务报表是利润表。资产负债表是反映企业在某一特定日期（如月末、季末、年末)全部资产、负债和所有者权益情', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '陈先生的孩子10年后高中毕业，陈先生希望在10年间筹集20万元作为孩子的高等教育费用，假设陈先生选择基金定投的方式筹备资金，且投资的年投 资报酬率为6%，陈先生每年未至少需要投资（）万元。（答案取近似数值） 考前', '{"A": "1.52", "B": "2.27", "C": "1.85", "D": "1.43"}', '["A"]', '根据题中条件可知，终值FV=20，利率r=6%，期数n=10，根据“每年未至少需要投资”可知，属于期末年金。将数值代入到理财计算器中，求得 年金PMT=1.517，取近似值为1.52，所以，陈先生每年至少需要投资1.52万元。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户忠诚度与满意度的关系，下列正确的是（）。', '{"A": "满意的客户不一定忠诚", "B": "满意度高的客户一定忠诚", "C": "客户忠诚是客户满意的基础", "D": "客户忠诚是客户满意的前提"}', '["A"]', '客户忠诚度与满意度的关系：（1)客户满意是客户忠诚的前提和基础；(2)只有非常满意的客户，才可能成为忠诚客户：(3)对优质客户或高端客户，必 须做到让客户非常满意，且持之以恒。前后一致。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在家庭收支表中，下列选项中属于工作收入的是（）。', '{"A": "财产租赁和转让所得", "B": "特许权使用费所得", "C": "财产继承所得", "D": "个人对企业承包经营所得"}', '["D"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '般而言，对于中小企业，其理财目标与普通大型企业的区别主要在于（）。', '{"A": "保证资金安全，规避资金风险", "B": "企业和个人风险是否有效隔离", "C": "使资金最大限度地升值", "D": "保证资金流的充足性"}', '["B"]', '般而言，企业理财的主要目标包括保证资金安全，规避资金风险（A选项），保证资金流的充足性（D选项），以应对内外部压力，使资金最大限 度地升值（C选项）。对于中小企业而言，理财的目标不仅包括资金安全性、流动性与收益性，还面临其他问题，其中包括企业经营必需的资金需 求、企业和个人风险的有效隔离等。故本题答案选B选项。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '现金比率是分析企业偿债能力的重要指标之一，下列关于现金比率的说法，正确的是（）。', '{"A": "比率越高说明流动性越强", "B": "这里的现金包括存货", "C": "一般应达到25%", "D": "现金比率=现金/流动存款"}', '["A"]', '现金比率=现金/流动负债，这里的现金包括现金等价物，如有价证券等，但不包括存货和应收账款。现金比率为最保守的概念，一般应达到20%。 比率越高说明流动性越强。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王某的儿子10年后上大学，届时需学费90万元。为实现该教育目标，王某计划每年初投资9万元于平均年投资报酬率6%的平衡型基金，则10年后王某 筹备的学费（）万元。（答案取近似数值）', '{"A": "富余28.63", "B": "富余35.74", "C": "缺口28.63", "D": "缺口35.74"}', '["B"]', '根据题意，期限n=10，每年初投资9万元，属于期初年金，C=-9，『=6%，求10年后能获得多少收益，求终值FV。将数值代入到理财计算器中，求 得FV=125.74万元，扣除90万的学费，富余35.74万元，故本题答案选B。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列因素中，不影响获得国家基本养老金水平的是（）。', '{"A": "退休前最后一个月的工资水平", "B": "本人指数化月平均缴费工资水平", "C": "缴费年限和退休年龄", "D": "当地上年度职工月平均工资水平"}', '["A"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于中小企业融资特点的是（）。', '{"A": "频率低", "B": "周期长", "C": "成本低", "D": "额度小"}', '["D"]', '中小企业融资需求一股具有“周期短、频率高、额度小”的特点。故本题选择D选顶。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '使投资者最满意的证券组合是（）。', '{"A": "无差异曲线与有效边界的切点", "B": "处于位置最高的无差异曲线上", "C": "处于有效边界的最高点", "D": "无差异曲线与有效边界的交点"}', '["A"]', '由于有效集是市场上可供选择的一系列组合，那么，投资者究竞会选择哪一个组合就需要根据投资者自己的无差异曲线来进行判断，从而得到投资 效用最大化的最优投资组合了。这个组合位于无差异曲线与有效集的相切点。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '韩女士持有一张面值为1000元的债券，该债券的息票率为3.8%，每年付息一次。目前该债券的市场价格为980元，则该债券的即期收益率为（）。 (答案取近似数值)', '{"A": "3.98%", "B": "3.76%", "C": "3.8%", "D": "3.88%"}', '["D"]', '即期收益率为债券每年支付的利息与债券价格比值，即（3.8%×1000）/980=3.878%，取近似值3.88%，故本题选D', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于节税的表述错误的是（）。', '{"A": "不属于逃税的行为", "B": "与通常所说的“避税”，两者一样，无区别", "C": "顺应立法精神是节税的一个重要原则", "D": "巧妙利用税法赋予纳税人的权利"}', '["B"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '理财师客户关系管理的目的是（）：理财师客户关系管理的前提和基础是（）。', '{"A": "提升银行服务的品质和水平：严格管理客户接触点", "B": "培养忠诚的客户，提升客户的忠诚度；收集、整理客户信息", "C": "增强银行品牌效应；培养忠诚客户", "D": "提升理财师的服务水平和专业性：深入分析客户需求"}', '["B"]', '理财师客户关系管理的目的是培养忠诚的客户、提升客户的忠诚度；收集，整理客户的详细信息，了解客户，这是理财师客户关系管理的第一步， 是前提和基础。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '假设某投资组合是有效的，其标准差为18%。市场组合的预期收益率为17%，标准差为20%，无风险收益率为5%，根据资本市场线方程，该投资组 合的预期收益率为（）。', '{"A": "12.93%", "B": "19%", "C": "15.8%", "D": "14%"}', '["C"]', '资本市场线描述了有效投资组合的预期收益率与风险（标准差）之间的线性关系，公式为：', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '使用现金模拟仿真的方法，列支客户未来各年的各项主要收入和支出。观察其投资性资产以及所需要的投资报酬率的变动情况。这种方法通常会模拟 客户不同阶段的现金流，也被叫做（）。', '{"A": "家庭财务状况分析", "B": "现金流量分析", "C": "投资性资产额度模拟分析", "D": "全生涯模拟仿真分析"}', '["D"]', '全生涅财务状况模拟仿真包含了现金流量分析和投资性资产额度模拟分析两个部分，是检验客户是否达成其理财目标的重要分析手段，也是能比较 全面地展示客户未来历年收入支出情况、现金流状况和投资净值的变化状况的一种分析工具。故本题选择D选项。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '安先生2022年度月平均工资为4000元，2023年9月工资收入为11000元，单位所在城市2022年度职工月平均工资为7000元，通常情况下，安先生 2023年9月份最低应缴纳的社会基本养者保险费为（）元。', '{"A": "320", "B": "880", "C": "400", "D": "336"}', '["D"]', '养老保险缴费基数最高为统筹地职工上年度月平均工资的300%，最低为统筹地职工上年度月平均工资的60%。缴费费率为8%。 7000×300%=21000，7000×60%=4200，4000<4200，应该以4200为基础，所以4200×8%=336。故本题选择D选项。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于中小企业主风险特征的表述，错误的是（）。 190', '{"A": "中小企业主所面临的风险主要来自家庭而不是企业", "B": "中小企业随着老企业主年龄增长，面临家族事业传承的问题", "C": "中小企业的商业伙伴比较集中，因此受信用风险影响较大", "D": "中小企业主的个人人身风险是企业潜在的风险隐患"}', '["A"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '某作家指控某杂志社侵犯其著作权，法院裁定作家胜诉，该作家取得杂志社的经济赔偿款30000元，该赔偿收入应缴纳个人所得税额（）元。', '{"A": "5200", "B": "4800", "C": "3390", "D": "O"}', '["B"]', '根据《中华人民共和国个人所得税法》，著作权归属特许权使用费，劳务报酬所得、稿酬所得、特许权使用费所得以收入减除20%的费用后的余额 为收入额（即3万×（1-20%））。适用20%税率。因此，应纳税额=30000×（1-20%）×20%=4800（元）。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '理财师小王观察到某客户上年度的自由结余占比为60%。针对这种情况，小王的最优建议是（）。', '{"A": "建议客户加大储蓄力度", "B": "结合客户理财需求，建议适当配置理财产品", "C": "由于客户资金充沛，建议客户提高财务融资杠杆", "D": "根据客户意愿行事"}', '["B"]', '关于家庭结余的支配项目包括专项结余和自由结余两大类。专项结余包括：定期定额投资（如基金定投，零存整取等），储蓄型保险保费，还贷本 金等。自由结余是总结余减去专项结余总额，这是未经处理的结余额度，自由结余占总结余的比率过高，往往体现出较低的理财积极度：同时自由', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '李某夫妻共有存款60万元，存在李某名下。除此之外家里有现金20万元，并无其他资产，李某还以自已为被保险人购买了一份人寿保险，保额50万 元，指定妻子为受益人，则当李某死亡时，其遗产是（）万元。', '{"A": "40", "B": "110", "C": "80", "D": "90"}', '["A"]', '李某夫毒共有存款60万元，家里有现金20万元，作为夫共同财产，奏子要分得一半，也就是40万，剩下的40万作为遗产。如果投保人和被保险人 是同一个人，万一出险（身故)后，那么按保险合同约定，保险理赔金会赔付给指定受益人或法定受益人，所以保额50万直接归妻子所有，不算做遗 产，故本题选择A选项。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在以下保险中：（1）定期死亡保险；（2）生存保险；（3）两全保险；（4）年金保险，只有在保险期限内才提供死亡给付的保险是（）。 (3) (2)', '{"A": "(2)", "B": "(1)", "C": "(1)", "D": "(4)"}', '["B"]', '定期寿险具有固定的保险期限，只有当被保险人在保险期限内死亡，且此时保险合同还有效时，保险公司才会向受益人支付保险金。生存保险是指 以被保险人的生存为给付保险金条件的人寿保险：两全保险是指以在保险期间内死亡或期满生存为给付保险金条件的人寿保险：年金保险是以被保 险人生存为给付条件的人寿保险。故本题答案选“定期死亡保险”。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在大连商品交易所玉米合约期货开仓和持仓保证金比率均为5%。某投资者于8月5日以1200元/吨的价格买入10张玉米合约（每张10吨），在该投资 者买入的第二天即8月6日，玉米结算价下跌至1150元/吨，那么8月6日该客户的持仓保证金应为（）元，客户必须在规定时间内追加的保证金至少 为（）元。（答案取近似值）', '{"A": "6000:5000", "B": "6000;4750", "C": "5750; 5000", "D": "5750;4750"}', '["D"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '杨家有三兄弟杨甲、杨乙和杨丙，杨丙幼年时送给陈某作养子，杨丙结婚时，陈某为其盖了二层的新房，因邻居失火，该房屋被烧毁。杨丙的生母就 将自己的住房腾出来，让杨丙夫妇及陈某层住，不久杨丙的生母病故。杨甲与杨乙要收回房子，杨丙认为自己有权继承母亲遗产。依照法律规定，死 者的遗产由（）继承。 O.C.杨甲、杨乙和杨丙', '{"A": "杨甲、杨乙、杨丙及陈桌", "B": "杨甲、杨乙、陈某", "D": "杨甲和杨乙"}', '["D"]', '养子女是指因收养关系的成立与养父母形成父母子女关系的子女。养子女与亲生子女享有同等的继承权。收养关系一旦成立，养子女与生父母间的 权利义务关系消除。本题中杨丙被送给陈某做养子，其与生父母之间的关系解除，无权继承生父母的财产。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '般而言，下列关于债务管理表述正确的是（）。', '{"A": "当家庭的负债比率低于50%，且短期消费负债低于40%时，客户总体债务情况是合理的", "B": "合理的家庭债务负担率应低于50%，这样的情况下，家庭其他支出所需，才不会挤占同期的收入，不会对家庭生活品质产生负面", "C": "如果家庭平均负债利率高于基准贷款利率的1.2倍，则需要关注偿还能力并要考虑债务重组的可能性", "D": "家庭融资比率低于60%是合理的"}', '["C"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '于女士现年30岁，收入较高，适用个人综合纳税税率为25%。她计划每年年未税前储蓄12000元直至55岁退休。假设于女士开通了个人养老 账户内长期投资年化回报率为5%,若于女士55岁时选择一次性领取个人养老金，她可获得（）元？', '{"A": "572725", "B": "555543", "C": "429244", "D": "374813"}', '["B"]', '于女士在开通个人养者金账户进行投资的情况下，每年可在12000元以内可以税前扣除，也就是说这12000元不用缴纳个人所得税：n=25 PMT=-12000元，因此FV=572725元，领取环节缴纳3%税收，最后领取572725元×(1-3%)=555543元。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，属于增值性的自用性资产的是（）。 前绝', '{"A": "优先股股票", "B": "投资性住宅", "C": "货币基金", "D": "名人字画"}', '["D"]', '自用性资产包括增值性的资产和非增值性的资产。其中，增值性资产包括自用住房、空置或者用于度假（不产生收入）的房产、艺术品收藏等。选 项“优先股股票、投资性住宅和货币基金”属于投资性资产，故本题答案选“名人字画”。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '信用期的制定一股按（）先后顺序制定。（1)计算放宽信用条件而需增加的资金占用额(2)计算延长信用期所增加的利润(3)比较有利的信用期', '{"A": "(2)(1)(3)", "B": "(1)(2)(3)", "C": "(2)(3)(1)", "D": "(1)(3)(2)"}', '["A"]', '信用期的制定可分为三步，首先，计算延长信用期所增加的利润：其次，计算放宽信用条件而需增加的资金占用额；最后，比较有利的信 用期的制定还需要考虑绘账企业的信用标准，一般通过5C"系统进行，即评估对方的品质(Character)、能力(Capacity)、资本(Capital) (Collateral)和条件(Condition)，以更全面地考察信用期的制定。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户王先生希望购买一款能够提供终身死亡保障的保险产品，并且这款产品还具有一定的抵御通货膨胀的功能，但他不愿意承担很大的投资风险。理 财师应该为其推荐购买（）。', '{"A": "终身寿险（分红型）", "B": "定期寿险", "C": "定期两全保险", "D": "投资连结险"}', '["A"]', '定期寿险，提供的是一定期限内的死亡风险保障，不能抵御通货膨胀，所以选项“定期寿险”不符合要求； 投资连结险需要客户具备一定的风险承受能力和对产品的理性理解能力。终身寿险是提供终身的死亡风险保障的险种，加上分红功能的终身寿险 （分红型）能够在一定程度上抵御通货膨胀。故本题答案选“终身寿险（分红型）“', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《中华人民共和国消费税暂行条例》，进口小轿车应纳消费税的计税价格为（）。', '{"A": "（关税完税价格+关税）×（1-消费税税率）", "B": "（到岸价格+关税）×（1-消费税税率）", "C": "（到库价格+关税）+（1-消费税税率）", "D": "（关税完税价格+关税）+（1-消费税税率）"}', '["D"]', '根据《中华人民共和国消费税暂行条例》规定，进口小轿车应纳的消费税在进口时一次性征收，以消费税组成计税价格为计税依据。消费税组成计 税价格=（关税完税价格+关税）+（1-消费税适用率）。故本题选择D选项。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年40岁，他目前的年支出额为10万元，假定通货膨胀率为3%，投资收益率为6%，假设王先生预期余寿为40年，若王先生选择在50岁退 休，现在需要准备的养老金为（）万元。（答案取最接近数值）', '{"A": "154", "B": "375", "C": "124", "D": "175"}', '["A"]', '退休年龄对退休规划的影响： （1）通货膨胀率为3%，投资收益率为6%，计算实际收益率=（1+名义收益率）／（1+通货膨胀率）-1=（1+6%）／（1+3%）-1=2.91%。 (2）选择在50岁时退休，计算到50岁时生活开销=10×（1+3%)^10=13.44（万元）。（^是次方的含义，在科学计算器中有，考试时候也会 提供科学计算器和理财计算器）。 10', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '刘先生的自行车轮胎磨损严重，随时可能发生风险，但刘先生依然抱着侥幸心理继续骑车，这种行为从风险管理的角度考虑是存在风险的，其中自行 车轮胎磨损属于（）。', '{"A": "风险因素", "B": "风险事故", "C": "风险载体", "D": "风险损失"}', '["A"]', '一般认为，风险是由风险因素、风险事故和损失三个因素组成的。风险因素是指促使某一特定风险事故发生或增加其发生的可能性或扩大其损失程 度的原因或条件，是风险事故发生的潜在原因，是造成损失的间接原因。风险事故是指造成人身伤害或财产损失的偶发事件，是造成损失的直接的 或外在的原因。风险只有通过风险事故的发生，才能导致损失。损失是指标的物因某种特定事件的发生导致经济单位或个人非故意的、非预期的、', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '（）是反映证券或组合的收益水平对市场平均收益水平变化的敏感性，是衡量证券承担系统风险水平的指数。', '{"A": "证券间的相关系数", "B": "系数", "C": "证券组合的期望收益率", "D": "证券各自的权重"}', '["B"]', '相关系数等于两种金融资产的协方差除以两种金融资产的标准差的乘积。B系数是特定资产(或资产组合)的系统性风险度量。换句话说，β系数就是 一种评估证券系统性风险的工具，用于度量一种证券或一个投资证券组合相对总体市场的波动性。故本题选择B选项。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年30岁，在一家大公司工作，该公司效益较好，于今年成立了企业年金理事会，开始企业年金计划，要分别委托一家公司作为投资管理 人，一家商业银行作为托管人和账户管理人，请回答以下问题。 关于企业年金的说法正确的是（）。', '{"A": "个人缴费和企业缴费均可全额在税前列支", "B": "只有国有企业才能建立企业年金计划", "C": "王先生若调动工作，新单位也有企业年金计划，王先生可将原年金账户资产转移至新账户", "D": "王先生若参加了年金计划，在随后的工作期间内，可以随时将账户中的钱取出"}', '["C"]', '《企业年金试行办法》第三条规定，符合下列条件的企业，可以建立企业年金： （1）依法参加基本养老保险并履行缴费义务； 11', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年30岁，在一家大公司工作，该公司效益较好，于今年成立了企业年金理事会，开始企业年金计划，要分别委托一家公司作为投资管理人 一家商业银行作为托管人和账户管理人，请回答以下问题。 我国目前的企业年金计划均实行确定缴费计划（DC计划），下列（）不属于退休时DC计划个人账户资产的组成部分。', '{"B": "社会收益", "C": "个人缴费", "D": "投资收益"}', '["B"]', '根据《企业年金试行办法》第十一条的规定，企业缴费应当按照企业年金方案规定比例计算的数额计入职工企业年金个人账户：职工个人缴费额计 入本人企业年金个人账户。企业年金基金投资运营收益，按净收益率计入企业年金个人账户。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年30岁，在一家大公司工作，该公司效益较好，于今年成立了企业年金理事会，开始企业年金计划，要分别委托一家公司作为投资管理人， 家商业银行作为托管人和账户管理人，请回答以下问题。 如果王先生每月缴费500元。公司和个人按照1:1的比例缴费，在6%的年平均收益率下，到60岁退休时，个人账户余额最接近（）万元（答案取近似 值)。', '{"A": "136", "B": "47", "C": "100", "D": "6"}', '["C"]', '本题根据已知条件，可以将题目简单转化为已知年金求终值。 “每月缴费500元属于年金，一般为期初缴纳，就是期初年金。PMT=500×2=-0.1 （公司和个人按照1:1的比例缴费），『r=6%/12=0.5%，n=30×12=360，将数值代入到理财计算器中，求得FV100万。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年30岁，在一家大公司工作，该公司效益较好，于今年成立了企业年金理事会，开始企业年金计划，要分别委托一家公司作为投资管理人， 家商业银行作为托管人和账户管理人，请回答以下问题。 接上题，如果王先生预计退休时个人账户资产应达到150万元，才能维持较好的生活水准，则每月月初应缴纳（）元。', '{"A": "1052", "B": "2050", "C": "1486", "D": "1200"}', '["C"]', '本题简单转化为已知终值求年金的计算，根据“本月月初缴纳可以得知是期初年金。FV=1500000，『=6%/12=0.5%，n=30×12=360，代入到 理财计算器中，求得PMT-1486，所以每月应缴纳1486元。 12', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年30岁，在一家大公司工作，该公司效益较好，于今年成立了企业年金理事会，开始企业年金计划，要分别委托一家公司作为投资管理人， 家商业银行作为托管人和账户管理人，请回答以下问题。 退休后，王先生决定将个人账户资产全部取出，在随后的资产配置中，下列）是不恰当的。', '{"A": "可以适当持有股票，以规避通货膨胀风险", "B": "应保持较好的流动性", "C": "找理财师，寻求合理建议", "D": "不应再持有股票，以债券和现金为主"}', '["D"]', '一般而言，用于退休养老金的投资要以稳健为主，有较大风险承受能力的人可以适当考虑将部分资金投资于股票、股票基金等风险收益相对较高的 产品。资产配置的原则应当是在安全的基础上保持适当的收益率。所以在退休后，王先生将个人账户资产全部取出，在随后的资产配置中也可以适 当的持有股票。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王女士夫妇今年均为35岁，两人打算55岁退休，预计生活至85岁，王女士夫妇预计在55岁时的年支出为10万元，现在家庭储蓄为10万元。假设通货 膨胀率保持3%不变，退休前，王女士家庭的投资收益率为8%，退休后，王女士家庭的投资收益率为3%。 综合考虑通货膨胀率与投资收益率，王女士夫妇56岁的年支出在55岁时的现值为（）元。', '{"A": "110000", "B": "100000", "C": "139271", "D": "135291"}', '["B"]', '根据题意，考虑通货膨胀率与投资收益率，而本题中通货膨胀率和投资收益率一致，也就是说55岁和56岁时候的现值是一样的，都是年支出10万。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王女士夫妇今年均为35岁，两人打算55岁退休，预计生活至85岁，王女士夫妇预计在55岁时的年支出为10万元，现在家庭储畜为10万元。假设通货 膨胀率保持3%不变，退休前，王女士家庭的投资收益率为8%，退休后，王女士家庭的投资收益率为3%。 王女士夫妇一共需要（）元养老金。', '{"A": "3977854", "B": "3398754", "C": "3598754", "D": "3000000"}', '["D"]', '预计生活至85岁，则应准备退休后30年的养老金，为100000×30=3000000元， 13', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王女士夫妇今年均为35岁，两人打算55岁退休，预计生活至85岁，王女土夫妇预计在55岁时的年支出为10万元，现在家庭储蓄为10万元。假设通货 膨胀率保持3%不变，退休前，王女士家庭的投资收益率为8%，退休后，王女士家庭的投资收益率为3%。 在王女士55岁时，其家庭储蓄恰好为（）元，', '{"A": "466095.71", "B": "524743.26", "C": "396968.45", "D": "386968.45"}', '["A"]', '复利终值的公式：FV=PV×(1+r)。10万元储蓄到退休时终值=1000000×(1+8%)20=466095.71元。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王女士夫妇今年均为35岁，两人打算55岁退休，预计生活至85岁，王女士夫妇预计在55岁时的年支出为10万元，现在家庭储蓄为10万元。假设通货 膨胀率保持3%不变，退休前，王女士家庭的投资收益率为8%，退休后，王女士家庭的投资收益率为3%。 王女士夫妇的退休金缺口为（）元。', '{"A": "2564011.42", "B": "2546011.24", "C": "2654011.24", "D": "2533904.29"}', '["D"]', '退休金缺口=3000000-466095.71=2533904.29元。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王女土夫妇今年均为35岁，两人打算55岁退休，预计生活至85岁，王女士夫妇预计在55岁时的年支出为10万元，现在家庭储蓄为10万元。假设通货 膨胀率保持3%不变，退休前，王女士家庭的投资收益率为8%，退休后，王女土家庭的投资收益率为3%。 如果王女士夫妇采取定期定额投资方式积累退休金，则每年还需要投资（）元。 老考前纸', '{"A": "54626.41", "B": "55371.41", "C": "54662.41", "D": "55656.41"}', '["B"]', '本题转化为已知终值求年金，FV=2533904.29，i=8%，n=20，PV=0，代入到理财计算器中，求得PMT=55371.41元。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户投资了一支债券基金和一支股债混合基金。近期该客户参加了债券基金经理的路演活动，基金经理认为近期经济不好，市场有降息预期，该基 金计划在符合监管要求的情况下按季分红。投资策略方面计划使用“骑乘策略”，基金经理介绍“骑乘策略”是指：买入收益率水平处于相对高位 的债券，持有一段时间后，债券的剩余期限将会缩短，债券的市场收益率水平将会较投资期初有所下降，对应的将是债券价格的走高。基金投资方 向为利率债、信用债、可转债等。该客户又参加了一场股债混合基金经理的路演活动，其基金经理表示主要依靠调研上市公司，研究行业分析报告 等挖掘具有价值投资潜力的股票获得超额收益。根据以上材料，回答下列问题。 当前“骑乘策略”的债券收益率曲线最可能是（）。', '{"A": "正向收益率曲线", "B": "水平收益率曲线", "C": "平缓的收益率曲线", "D": "反向收益率曲线"}', '["A"]', '正向收益率曲线，反映的是，期限长的收益率高，期限短的收益率低。骑乘策略操作的时候，就先买入长期的，因为收益率高，可以获得高利 息。持有一段之后，期限缩短了，就变成短期的了，而短期的收益率低，债券的价格就高，所以这时候，我就把之前买的长期债券卖掉，还可以', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户投资了一支债券基金和一支股债混合基金。近期该客户参加了债券基金经理的路演活动，基金经理认为近期经济不好，市场有降息预期，该基金 计划在符合监管要求的情况下按季分红。投资策略方面计划使用“骑乘策略”，基金经理介绍“骑乘策略”是指：买入收益率水平处于相对高位的债 券，持有一段时间后，债券的剩余期限将会缩短，债券的市场收益率水平将会较投资期初有所下降，对应的将是债券价格的走高。基金投资方向为利 率债、信用债、可转债等。该客户又参加了一场股债混合基金经理的路演活动，其基金经理表示主要依靠调研上市公司，研究行业分析报告等挖掘具 有价值投资潜力的股票获得超额收益。根据以上材料，回答下列问题。 客户买入债券基金并持有一段时间后，该债券基金价格明显下跌，最不可能的原因是（）。', '{"A": "股市大幅上涨", "B": "人民银行大福降息", "C": "受长假影响，市场流动性紧张", "D": "经济意外转好，CPI上涨超过市场预期"}', '["B"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户投资了一支债券基金和一支股债混合基金。近期该客户参加了债券基金经理的路演活动，基金经理认为近期经济不好，市场有降息预期，该基 金计划在符合监管要求的情况下按季分红。投资策略方面计划使用“骑乘策略”，基金经理介绍“骑乘策略”是指：买入收益率水平处于相对高位 的债券，持有一段时间后，债券的剩余期限将会缩短，债券的市场收益率水平将会较投资期初有所下降，对应的将是债券价格的走高。基金投资方 向为利率债、信用债、可转债等。该客户又参加了一场股债混合基金经理的路演活动，其基金经理表示主要依靠调研上市公司，研究行业分析报告 等挖掘具有价值投资潜力的股票获得超额收益。根据以上材料，回答下列问题。 2090 由于近一年经济不好，股票市场持续下跌幅度很大、时间较长，债券价格保持相对稳定，客户投资的股债混合基金净值一年来没有下跌，基金经理 最不可能使用的资产配置策略是（）。', '{"A": "买入并持有策略", "B": "恒定混合策略", "C": "固定比例投资组合保险策略", "D": "高频交易策略"}', '["D"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户投资了一支债券基金和一支股债混合基金。近期该客户参加了债券基金经理的路演活动，基金经理认为近期经济不好，市场有降息预期，该基 金计划在符合监管要求的情况下按季分红。投资策略方面计划使用“骑乘策略”，基金经理介绍“骑乘策略”是指：买入收益率水平处于相对高位 的债券，持有一段时间后，债券的剩余期限将会缩短，债券的市场收益率水平将会较投资期初有所下降，对应的将是债券价格的走高。基金投资方 向为利率债、信用债、可转债等。该客户又参加了一场股债混合基金经理的路演活动，其基金经理表示主要依靠调研上市公司，研究行业分析报告 等挖掘具有价值投资潜力的股票获得超额收益，根据以上材料，回答下列问题。090 根据该股债混合基金的投资策略，其基金经理认为当前市场符合（言J', '{"A": "强式有效市场假说", "B": "随机漫步理论", "C": "半强式有效市场假说", "D": "弱式有效市场假说"}', '["D"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '个体工商户刘某，2022年取得营业收入196万元，支出方面包括：营业成本112万元；税金及附加8万元(包含已经预缴的个人所得税3万元）：营业费用 12.5万元，其中业务宣传费5万元，其他营业费用7.5万元；管理费用22万元，其中业主刘某的工资薪金6万元，其他员工的工资薪金16万元。 2022年个税起征点为6万元。刘某个人专项扣除1.248万元。其中养老0.96万元。医疗0.288万元：专项附加扣除4.8万元，其中子女教育1.2万元，赠养 老人2.4万元，住房贷款利息1.2万元。 根据以上材料，回答下列问题。 （1）在计算刘某个体工商户应纳税所得额时，无法进行扣除的是（），', '{"A": "165791", "C": "284500", "D": "142250", "B": "331582"}', '["D"]', '个体工商户在计算应纳税所得额时不得扣除：个税税款、税收滞纳金、赞助支出、用于个人和家庭的支出、业主工资等，故本题选择B选项。 第57跑 个体工商户刘某，2022年取得营业收入196万元，支出方面包括：营业成本112万元；税金及附加8万元(包含已经预缴的个人所得税3万元)：营业费用 12.5万元，其中业务宣传费5万元，其他营业费用7.5万元；管理费用22万元，其中业主刘某的工资薪金6万元，其他员工的工资薪金16万元。 2022年个税起征点为6万元。刘某个人专项扣除1.248万元。其中养老0.96万元。医疗0.288万元；专项附加扣除4.8万元，其中子女教育1.2万元， 赠养老人2.4万元，住房贷款利息1.2万元。 根据以上材料，回答下列问题。 （2）刘某经营所得税前利润总额为（）万元。 专项附加扣除可以在综合所得中扣除，如果纳税人没有综合所得的，则计算经营所得个人所得税时，允许扣除基本减除费用6万元、专项扣除、专项 附加扣除以及依法确定的其他扣除。但对专项附加扣除平时不得减除,只能在办理汇算清缴时减除。故本题选择D选项。 （4）不考虑税收优惠政策及其他收入，刘某2023年应纳税所得额是（）万元。（答案取近似数值） 个体工商户在计算应纳税所得额时不得扣除：个税税款和业主工资，所以个税税款3万和业主工资的6万需要加上，应纳税所得额=税前利 （5）根据税务总局公告，对个体工商户2021年1月1日至2022年12月31日期间的年应纳税所得额不超过100万元部分，在现行优惠政策基础上，洞 半征收个人所得税。如果刘某另有一家个体工商户企业2022年应纳税所得额为75万元,则刘某通过上述优惠政策可以减免个人所得税额（）元。 个体工商户从两处以上取得经营所得，需在办理年度汇总纳税申报时，合并个体工商户经营所得年应纳税所得额，重新计算减免税额，多退少', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '刘先生今年40岁，在一家企业工作，月收入15000元，妻子38岁，是一名教师，月收入10000元，家庭每年生活支出12万元，两人育有一子，今年 10岁，刘先生夫妇计划25年后退休，期望退休后保持现有生活水准，假设刘先生夫妇退休后预计生活20年，通货膨胀率为3%，年投资报酬率为 4%。根据以上材料，回答下列问题。 刘先生在进行养老规划时，以下做法不利于实现养老目标的是（）。', '{"A": "8910", "B": "9700", "C": "8950", "D": "9100"}', '["C"]', '养老规划的核心目标是通过长期资金储备和增值，确保退休后能维持既定生活水准。尽早开始储备养老资金：长期投资可通过复利效应积累更多 资金，是实现养老目标的重要基础，有利于目标实现。定期评估并调整规划：家庭收支、市场环境等因素会变化，定期调整可确保规划适配实际 情况，有利于目标实现。充分了解养老金融产品：合理选择产品能优化资产配置，提高资金效率，有利于目标实现。过于保守投资，收益无法覆 17 考虑通货膨胀因素，刘先生夫妇退休第一年所需生活费为（）万元。 刘先生家庭每年生活支出12万元，12×(1+3%)25=25.13（次方在科学计算器中有，考试时候也会提供科学计算器和理财计算器）。故本题选择A选 项。 为保持现有生活水准，刘先生夫妇退休时需要准备的养老金总额约为（）万元。（答案取近似数值） 通货膨胀率为3%，投资收益率为4%，计算实际收益率=（1+名义收益率）／（1+通货膨胀率）-1=（1+4%）／（1+3%）-1=0.97%。本题问的 是刘先生夫妇退休后20年的总支出折现到65岁时点，求现值PV。其中终值FV=0，65岁退休生活开销每年25.13万，属于年金PMT=-25.13（支 出记为负值），利率r=0.97%，期限n=20，生活费支出属于期初年金，将数值代入到理财计算器中，求得PV=459.26（万元）。故本题答案选 为实现上述养老目标，刘先生现在开始每月进行定额投资，则每月初至少应投资（）元。（答案取近似数值） 本题问每月初至少投资，求的是年金PMT，现在每月投资，因为是现在，所以不用考虑通货膨胀率，所以PMT（FV=459，1=4%+12=0.33%， n=25×12=300，期初模式，PV=0）=8949.9，故本题答案选择C选项。 18', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）王先生和王太太今年40岁，女儿王英15岁，儿子王炜9岁，王先生在某证券公司上班，月收入约5万元；王太太在某企业从事财务 工作，月收入约3万元。王先生为独生子，父母均为80岁，与王先生一家共同居住生活，王太太父母已病故。 4.2%),2024年1月，首套房贷首付比例为20%。利率执行LPR-20bp；二套房首付比例为30%，利率执行LPR+20bp。 王先生一家每月开支主要包括日常生活开支和儿女教育开支，除此外无其他支出。王先生一家日常月开支约15000元，女儿和儿子每月各类培训支出 合计约10000元。王先生一家现有现金30万元，5年前通过银行柜台投资某10年期债券，还剩5年，票面利率4%，按年计息，面值100万元。 王太太希望女儿3年后到国外留学6年，每年留学费用预计为15万元；规划儿子10年后在国内大学上学，每年各项学费支出约5万元，学习期限预计7年。 王先生和王太太都计划60岁退休。现有一只年化收益率3%的年金产品，每月定投至退休。退休后按指定期限按月等额本息分红，王先生和王太太希 望通过每月定投，该基金分红能够保障夫妇二人退休后至80岁期间每月的生活支出10000元。 不考虑通货膨胀、学费上涨和房产交易的税费等因素。根据以上材料，回答下列问题。 王先生家庭每月支付的孩子教育培训支出属于家庭支出分类中的（）。', '{"A": "101.93", "B": "101.75", "C": "102.26", "D": "103.16"}', '["C"]', '从个人生命周期来看，王先生当前所处阶段为稳定期，这一时期要做好投资规划与家庭现金流规划，以防范疾病、意外、失业等风险。可考虑采 用定期定额基金投资等方式，利用投资的复利效应和长期投资的时间价值为未来积累财富。故本题选择A选项。 根据当前王先生家庭的财务信息，理财师可能对王先生提出的家庭理财规划建议原则上不包括（）。 在稳定期的理财任务是要尽可能多地储备资产、积累财富。同时，要注意为个人及家庭购买人身险、意外险等险种，未雨绸缪，防忠于未然。B选 项是建立期的任务。故本题选择B选项。 为实现养老目标，王先生家庭每月末需定投金额约为（）元。（答案取近似数值） 为了保障每月的生活支出10000元，所以看退休时点一共需要多少钱，利率3%/12=0.25%，n=25×12=300，C=-10000，FV=0，期初模式， 求得PV=2114036.5，为了实现养老目标，利率3%/12=0.25%，n=15×12=180，FV=2114036.5，PV=0，期末模式，求得C=9314，取近似 数值，故本题选择D选项。【如何区分期初期末：首先要看题目有没有给出期初（年初）、期末（年底、年末）投资这样的字眼，如果有的话， 不考思通货膨胀、学费上涨和房产交易的祝费等因系。根以上材料，回答下列问题。 为调控宏观经济，人民银行可运用的货币政策工具不包括（）。 在公开市场上买卖企业信用债券：这不是人民银行常用的货币政策工具。人民银行在公开市场上买卖的主要是国债、中央银行票据和政策性金融 债券，而不是企业信用债券。公开市场操作是人民银行调节市场流动性、影响货币供应量和市场利率的一种主要货币政策工具。故本题选择C选 王先生基于宏观经济形势预判，计划提前卖出债券，他的预判原则上不包括（）。 一股来说，如果宏观经济形势向好，投资者可能会预期未来的市场利率会上升，这将导致现有债券的价格下跌。因此，投资者可能会选择提前卖 出旧债券以避免损失。A选项：这一数据反映了消费市场的活力，可能意味着整体经济环境较为乐观。这可能会促使投资者预测未来的市场利率将 上升。B选项：PMI（采购经理指数）是一个重要的经济指标，它的持续向好表明制造业处于扩张状态，这通常被视为经济向好的信号。对于长期 债券投资者来说，这可能会促使他们预测未来的市场利率将上升。C选项：国民生产总值的增长超过预期通常意味着经济正在强劲增长，这也可能 接上题，假设王先生2019年认购该柜台债，债券的发行机构最不可能是（）。 省财政厅作为地方政府财政部门的一个组成部分，主要负责财政预算、支出、管理等事务，并不直接作为债券的发行机构。在银行间债券市场 中，地方政府债券的发行是通过地方政府进行的，而不是由财政厅直接发行。因此，对于王先生2019年认购的柜台债，发行机构最不可能是省财 政斤。故本顾洗R. 20 根据2023年8月31日国务院发布的《关于提高个人所得税有关专项附加扣除标准的通知》，在当前情况下，王先生一家每月个人所得税专项附加扣 除总额上限为（）元。 国务院发布关于提高个人所得税有关专项附加扣除标准的通知：①3岁以下婴幼儿照护专项附加扣除标准，由每个婴幼儿每月1000元提高到2000 元。②子女教育专项附加扣除标准，由每个子女每月1000元提高到2000元。③赠养老人专项附加扣除标准，由每月2000元提高到3000元。其 中，独生子女按照每月3000元的标准定额扣除；非独生子女与兄弟姐妹分摊每月3000元的扣除额度，每人分摊的额度不能超过每月1500元。上 理财师建议王先生开立个人养老金账户，按照《个人养老金实施办法》，当前个人养老金账户资金不能用于（）投资。 目前，商业银行在个人养老金方面，主要开办以下五项业务：（1)资金账户业务：(2)个人养老储蓄业务：(3)个人养老金产品代销业务，包括代销 王先生当前每月房贷还款金额为（）元。 (答案取近似数值) 利率=4.2%-20bp=4%，月利率=4%/12=0.3333%，n=10×12=120，PV=100，FV=0，期末模式，求得C=10124.32，故本题选择D选项。 根据经验法则，王先生家庭每月还款额不宜超过24000元，若按20年期每月等额本息贷款买房，则王先生新认购的房产总价上限为（）万元。（答 案取近似数值) 新认购的房产为第二套房产，利率执行LPR+20bp，所以利率=4.2%+20bp=4.4%，l=4.4%/12=0.3667%，n=20×12=240，新认购的房产总 价上限PV（C=24000，I=0.3667%，n=240，期末模式，FV=0）=3826007.8，最高为382万，选一个最接近的为A选项。 21 2024年2月20日，中国人民银行授权全国银行间同业拆借中心公布，5年期以上LPR调降25bp至3.95%。王先生一家当前房', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）王先生和王太太今年40岁，女儿王英15岁，儿子王炜9岁，王先生在某证券公司上班，月收入约5万元；王太太在某企业从事财务 工作，月收入约3万元。王先生为独生子，父母均为80岁，与王先生家共同居住生活，王太太父母已病故。 4.2%),2024年1月，首套房贷首付比例为20%。利率执行LPR-20bp；二套房首付比例为30%，利率执行LPR+20bp。 王先生一家每月开支主要包括日常生活开支和儿女教育开支，除此外无其他支出。王先生一家日常月开支约15000元,女儿和儿子每月各类培训支出 合计约10000元。王先生一家现有现金30万元，5年前通过银行柜台投资某10年期债券，还剩5年，票面利率4%，按年计息，面值100万元。 王太太希望女儿3年后到国外留学6年,每年留学费用预计为15万元；规划儿子10年后在国内大学上学,每年各项学费支出约5万元，学习期限预计7年。 王先生和王太太都计划60岁退休。现有一只年化收益率3%的年金产品，每月定投至退休。退休后按指定期限按月等额本息分红,王先生和王太太希 望通过每月定投，该基金分红能够保障夫妇二人退休后至80岁期间每月的生活支出10000元。 不考虑通货膨胀、学费上涨和房产交易的税费等因素。根据以上材料，回答下列问题。 2021年1月王先生出售债券获得100万元，家庭现金储备按照经验区间上限6个月留足后，其余现金和债券变现资金全部用于新增购房首付。暂不考 虑还贷压力，王先生新购房产价值上限为（）万元。（答案取近似数值）', '{"A": "20346", "B": "19939", "C": "21347", "D": "18929"}', '["C"]', '首先，我们需要计算王先生一家在债券变现后的总资产和总负债。总资产=现有房产市值+债券变现资金，总负债=剩余房贷，现有房 =500万元，债券变现资金=100万元，剩余房贷=100万元，因为不考虑可动用现金情况，所以现金30万不考虑，所以，总资产=50 元=600万元，总负债=100万元，接下来，我们根据经验法则，按照资产负债率50%的上限来计算新增借贷金额的上限。资产负债率 资产，为了保持资产负债率在50%以内，我们需要计算新增借贷金额的上限。假设新增借贷金额为x万元，则：（100+x)/(600+x)< 不等式我们组到：VA00万元所以为径证工牛生一家的盗产负佳率在会理范围内新增借做全额上限是好应控制在A00万元！ 王先生家庭持有的债券属于（）。 留学费用为15万×6=90万，利率=4%/12=0.33%，n=3*12=36，每月初定投金额C（n=36，1=0.33%，FV=90，PV=0，期初模式） =23507.取近似数值，故本题选择C选项 23', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '家庭财务现状分析主要包括（）的内容。', '{"A": "信用和债务管理方面", "B": "投资和资产配置方面", "C": "家庭财务保障方面", "D": "收支结余方面", "E": "流动性方面"}', '["A", "B", "C", "D", "E"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '目前我国实行社会统筹和个人账户相结合的运行模式的保险有（）。 □B.基本医疗保险', '{"A": "生育保险", "C": "工伤保险", "D": "失业保险", "E": "养老保险"}', '["B", "D", "E"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '般来说，客户对退休后生活乐观估计的原因包括（）。 ■B.认为退休后的社会保障、养老金计划或个人储蓄投资能够保障退休生活', '{"A": "认为退休后生活开支会明显减少，未充分考虑旅游、培养兴趣爱好等生活成本", "C": "未充分考虑通货膨胀带来的资金贬值，觉得拥有一笔看似不菲的养老金就能高枕无忧", "D": "认为社会基本医疗保障足够承担医疗费用", "E": "性格上决定其较关心当前生活，不愿意以影响当前的生活品质为代价规划未来，认为退休养老毕竟是很久远的事"}', '["A", "B", "C", "D", "E"]', '船来说。客户对退休后牛活乐观估计的原因包括： 24', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于中小企业的特征，下列表述正确的有（）。', '{"A": "故意杀害被继承人", "B": "继承人、继承人的顺序、继承人继承的遗产份额等都是由被继承人在遗喔中指定", "C": "遗嘱继承实际上是对法定继承的一种排斥", "D": "以欺诈、胁迫手段迫使或者妨碍被继承人设立、变更或者撤回遗嘱。情节严重", "E": "为争夺遗产而杀害其他继承人"}', '["D", "E"]', '25', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '一般而言，下列关于汇率变动的表述，正确的有（）。', '{"A": "市场预期某种货币贬值，该货币在即期市场会发生贬值", "B": "发生恶性通胀的国家的货币会贬值", "C": "国际收支出现顺差的国家的货币会贬值", "D": "真实利率高的国家的货币即期市场会贬值", "E": "如果一国的财政预算出现巨额赤字，则其货币汇率将上升"}', '["A", "B"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '我国财富传承需求越来越旺盛的主要原因有（）。', '{"A": "财富传承财富分配范围广、形式多", "B": "职业经理人制度的缺失", "C": "富裕人群步入中老年", "D": "遗产分配纠纷频发", "E": "个人财富逐步积累"}', '["A", "C", "D", "E"]', '财富传承需求历来有之，只是近年来越来越多的人意识到它的重要性，而且更多时候需要借助专业人士进行专业规划。我国财富传承需求越来越 旺盛的主要原因有： 1.个人财富逐步积累；', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户关系维护或营销需要关注哪些方面（）。', '{"A": "必须建立客户数据", "B": "加强交叉销售、组合销售", "D": "直接频繁面对客户的员工必须经过严格专业培训和标准化管理", "E": "拿出一定比例的费用用于奖励忠诚顾客和改善与客户的关系"}', '["A", "D", "E"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于分红保险的红利，下列说法正确的有（）。 ■E.保险公司可以提供多种红利领取方式，比如现金、抵交保费、累积生息以及购买缴清保额等', '{"A": "红利分配方式有现金红利和增额红利两类", "B": "现金红利分配是指直接以现金的形式将盈余分配给保单持有人的方式", "D": "增加的保额作为红利公布后可以取消"}', '["A", "B", "C", "E"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '证券分析中的公司层面分析，主要是利用公司的历年资料对（）进行详细分析。 □ D.公司的社会责任', '{"A": "公司的偿债能力", "B": "公司的竞争力", "C": "机动车交通事故责任强制保险中医疗费用赔偿限额为1000元人民币", "E": "公司的盈利能力", "D": "机动车交通事故责任强制保险的责任限额由保险公司制定"}', '["B", "E"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，能体现退休养老规划重要性的有（）。 ■E.目前社会养老体系尚不完善', '{"A": "退休者希望退休后维持独立自主、有品质的生活", "B": "生活、卫生条件改善，人均寿命逐渐增长", "C": "人口老龄化趋势，加大了社会养老负担", "D": "环境污染严重，人们罹患疾病的概率增加"}', '["A", "B", "C", "E"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在投资规划中，技术分析的基本假设有（）。 □B.市场行为反映一切信息', '{"A": "历史会重演", "C": "成交量比成交价格先反映趋势", "D": "价格总趋势移动"}', '["A", "B", "D"]', '作为一种投资分析工具，技术分析是以一定的假设条件为前提的，这些假设是：市场行为反映一切信息；证券价格沿趋势移动；历史会重演。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '子女教育规划的极大的不确定性主要体现在（）。', '{"A": "子女对学习的爱好程度无法预测", "B": "子女素质教育方面的支出无法提前预知", "C": "将来的物价水平无法预测", "D": "子女的资质与学习能力无法预测", "E": "学校的收费水平不可预知"}', '["B", "D"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '股而言，保险金信托的功能及优势有（）。', '{"A": "资产隔离", "B": "专业管理", "C": "灵活传承", "D": "资金杠杆", "E": "信息公开透明"}', '["A", "B", "C", "D"]', '保险金信托的功能及优势：资产隔离、灵活传承、资金杠杆和专业管理。不包括信息公开。', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '教育投资规划是针对家庭成员的教育目标制定的财务规划，主要包括哪些内容（）。 □C.明确教育需求', '{"A": "风险估测", "B": "选择理财产品和储蓄、投资方案", "D": "计算学习成本", "E": "计算资金需求和退休收入"}', '["B", "C", "D"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '判别纳税人收税管辖权的指标包括（）。 □E.所得来源于国内或是国外', '{"A": "高管还是一股员工", "B": "在境内居住时间长短", "C": "国籍", "D": "是否有住所"}', '["B", "D"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '办理2022年度汇算清缴过程中，将产生或者可能产生退税的情形有（）。', '{"A": "没有任职受雇单位，仅取得劳务报酬、稿酬、特许权使用费所得，需要通过年度汇算办理各种税前扣除的", "B": "2022年度综合所得年收入额不足6万元，但平时预缴过个人所得税的0", "C": "预缴税款时，未申报享受或者未足额享受综合所得税收优惠的，如残疾人减征个人所得税优惠等", "D": "2022年度有符合享受条件的专项附加扣除，但预缴税款时没有申报扣除的", "E": "纳税人取得劳务报酬、稿酬、特许权使用费所得，年度中间适用的预扣预缴率高于全年综合所得年适用税率的"}', '["A", "B", "C", "D", "E"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '般而言，在进行教育投资规划时应注意遵循的原则有（）。 □B.同步规划', '{"A": "交易商协会中期票据", "C": "国债", "D": "地方政府债", "E": "专项积累", "B": "政策性银行金融债"}', '["A", "D", "E"]', '', 2);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于人寿保险的是（）：', '{"A": "死亡保险、生存保险和两全寿险", "B": "普通意外伤害保险和特定意外伤害保险", "C": "医疗保险和疾病保险", "D": "失能收入损失保险和护理保险"}', '["A"]', '人身保险是以人的寿命和身体为保险标的的保险，包括人寿保险、年金保险、健康保险、意外伤害保险等保险业务。人寿保险是以保险人的寿命作为保险标的，以被保险人 的生存或死亡为给付保险金条件的一种人身保险。人寿保险可以简单划分为普通型人寿保险和新型人寿保险。普通型人寿保险是最常见和最普追的人寿保险，按照保险金给付 条件的不同可以区分为死亡保险、生存保险和两全寿险。常见的新型人寿保险包括分红寿险，投资连结保险和万能寿险。B选项属于意外伤害保险。CD选项属于健康保险。故 本题选择A选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '投资者投资的资产品种很多，既买基金又买股票、国债，此时就应使用经过市场风险系数调整的超额收益，对应的是（）指标，该指标越大，表明组合资产的实际业绩越（），', '{"A": "夏音：差", "B": "特雷诺：好", "C": "夏蕾：好", "D": "特雷诺：差"}', '["B"]', '特雷诺指数给出了单位风险的平均超额收益率，其风险使用的是系统风险，当投资人除当前投资组合外，还有其他若干投资组合，亦即投资完全分散化时，则选择此系数作为 报，当投资人当前的投资组合为唯一投资时，用标准差作为投资组合的风险指标是合适的。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '从宏观发展的角度考虑，影响客户关系管理思想和方法发展的因素不包括（）：', '{"A": "客户消费观念的改变", "B": "社会企业经营理念的变化", "C": "信息技术的推动", "D": "内部考核要求"}', '["D"]', '客户关系管理思想和方法的诞生、发展，有着三方面的因素：社会企业经营理念的变化、客户消费观念的改变以及信息技术的推动。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在客户关系管理中，客户满意度由决定。', '{"A": "产品的性能和价格", "B": "产品的质量和价格", "C": "客户的抱想和忠诚", "D": "客户的预期和体验"}', '["D"]', '客户的满意度不仅取决于金融机构、理财师的服务水平，还与客户的预期相关。客户满意度可以用以下公式说明：客户满意度=客户体验（获得的服务水平）一客户预期。故本 题选择D选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '严先生转让一项专有技术，获得特许权使用费10万元，则这笔特许权使用费的应纳个人所得税额为（）元，', '{"A": "16000", "B": "19625", "C": "2000", "D": "11200"}', '["A"]', '根据《中华人民共和国个人所得税法》，稿酬所得、劳务报酬所得、特许权使用费所得，每次收入不超过4000元的，减除费用800元，每次收入超过4000元以上的，减除20% 纳税额=100000×（1-20%）×20%=16000（元）', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '以死亡为给付保险金条件的保险单，未经（），不得转让或质押。', '{"A": "保险人口头同意", "B": "被保险人书面同意", "C": "保险人书面同意", "D": "被保险人口头同意"}', '["B"]', '根据《保险法》第三十四条规定，按照以死亡为给付保险金条件的合同所签发的保险单，未经被保险人书面同意，不得转让或者质押。故本题选择B选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于子女教育投资规划的表述中，正确的是（）。（1）教育投资规划应提早规划（2）教育投资规划的重要性高于退休金规划（3）教育储备金应专项积累，专款专用（4） 教育投资规划只能投资低风险的投资工具', '{"A": "(1) 、(2) 、(3)", "B": "(2) 、(3) 、(4)", "C": "(2) 、(4)", "D": "(1) 、(3)"}', '["D"]', '子女教育投资规划：1.由于教育投资的重要性和成本的迅速攀升。且其增长速度通常高于家庭其他支出，客户应当尽早进行教育投资规划。（1）正确。2.教育投资规划的重要 性与退休金规划同等重要，不存在教育投资规划的重要性高于退休金规划。（2）错误。3.专款专用是教育金储备过程中应该遵循的重要原则。专项积累。专款专用，谨防教育 金被抑用，（3）正确。4.需要根据客户的教育理财目标和资金需求，制订相应的资产配置方案和推荐合适的投资工具，（4）说法绝对，错误。故本题选择D选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '理财师在帮助客户进行借贷决策时，应该从其未来的还贷能力出发，并对客户家庭财务特别刚性的理财目标进行全而评估，以及对利率上升等风险进行分析后，才能确定借贷金 额，下列说法错误的是（），', '{"A": "根据现有的收支结余情况对可贷金额进行计算", "B": "模拟借贷后的家庭财务报表，如资产负债表和收入支出表，分析借贷后的债务结构以及收入支出结构，评估借贷活动对家庭财务的短期影响以及风险，并做", "C": "对未来的现金流进行模拟，了解还贷现金流对其他理财目标的影响，并做相应的调整", "D": "在采用财务杠杆进行投资时，根据自由资金的额度，对投资标的的价值波动进行敏感分析，并作出相应的调整"}', '["D"]', '理财师在帮助客户进行借贷决策时。应该从其未来的还贷能力出发，并对客户家庭财务特别刚性的理财目标进行全面评估，以及对利率上升等风险进行分析后，才能确定借贷 金额，具体的实务操作内客包括： （1）根据现有的收支结余情况对可贷金额进行计算： （2）模拟借贷后的家庭财务报表，如资产负债表和收入支出表，分析借贷后的债务结构以及收入支出结构，评估借贷活动对家庭财务的短期影响以及风险，并做相应的调整； （3）对未来的现金流进行模拟，了解还贷现金流对其他理财目标的影响，并做相应的调整。 不仅如此，理财师在借贷决策初定之时就应该前瞻性地对客户未来的债务状况和可能出现的问题进行充分分析并提供对策及建议，例如： （1）可考患全部或部分采用固定利率贷款，减少利率波动对还贷的影响： （2）为杠杆投资设计止损机制。所以选项“在采用财务杠杆进行投资时”说法错误，故本题答案选“在采用财务杠杆进行投资时”这个选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在家庭财富保障规划中，如果客户可用于购买保险的资金不多，一股是“保障优先”，下列最符合该原则的是优先购买（），', '{"A": "分红险", "B": "重疾险", "C": "万能险", "D": "投连险"}', '["B"]', '在保险产品的配置问题上，理财师具体应注意以下几个原则： （1）先依照户的保障需求做好人寿保险规划。考虑客户的预算能力来配置险种。 (2）发生概率虽小但后果严重的风险应优先考虑。 （3）应以“保障优先”的原则来制定家庭财富保障规划。优先配置保障型险种。同时要综合考虑客户的财务状况或预算开支能力再考虑储蓄分红或投资连结的险种。对于普通 家庭，保险的主要功能是财富保障，而非资产增值（资产增值手段有多种其他选择）。故本题答案选“重疾险”，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在进行子女教育规划时，下列选项中一般不将其计算在规划工具中的是（）。', '{"A": "教育保险", "B": "银行储蓄", "C": "国家教育助学贷款", "D": "奖学金"}', '["D"]', '大体上来说。教育投资规划工具可分为长期教育投资规划工具和短期教育投资规划工具。短期教育投资规划工具主要包括国家助学贷款。商业助学贷款。出国留学贷款。长期 教育投资规划工具包括银行储蓄、教育保险、基金产品、教育金信托和其他投资理财产品等。不包括奖学金。故本题答案选“奖学金”。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列不属于银行户关系管理中客户定位工作的是（）：', '{"A": "对客户准入门槛进行动态调整", "B": "确定客户准入门槛", "C": "明确服务对象与重点客户", "D": "对客户进行风险能力测评"}', '["D"]', '银行在客户定位环节必须完成三项工作：一是要根据银行业务经营状况、业务发展目标与客户结构和外部发展环境，合理确定客户价值与准入门槛（B属于）：二是要依据银行 制定的客户价值与准入门槛，选定和保留高价值客户，有成长潜力的客户，以明确银行的服务对象与重点客户（C属于）；三是银行客户定位应实行动态管理，不仅要依据银行 业务经营策略、经营目标。经营管理能力和客户结构变动状况适时调整客户准入门槛（A属于），而且要依据客户的忠诚度、贡献度和客户的价值变动状况调整重点服务对象， 以不断适应经营发展所需，本题问不属于的是，答案选择D选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于教育投资规划的流程，下列排序正确的是（），（1)明确客户的教育投资目标(2)制订教育投资规划方案(3)接触客户，建立信任关系(4)收集、整理和分析客户的家庭财务状况 (5)教育投资规划方案的执行(6)后续限踪服务', '{"A": "4-1-3-2-5-6", "B": "3-2-4-1-5-6", "C": "3-4-1-2-5-6", "D": "4-3-1-2-5-6"}', '["C"]', '（4）制定教育 投资规划方案；（ （5）教育投资规划方案的执行：（6）后续眼踪服务。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于责任保险的说法正确的是（）：', '{"A": "属于狭义的财产保险范略", "B": "以被保险人对第三者的财产损失或人身伤害依照法律应负的赔偿责任为保险标的", "C": "以合同的权利人和义务人约定的经济信用为保险标的", "D": "责任保险中的责任指侵权责任"}', '["B"]', '责任保险是以被保险人对第三者的财产损失或人身伤害依照法律应负的赔偿责任为保险标的的保险。主要业务种类包括公众责任保险。产品责任保险、雇主责任保险和职业责 任保险等。广义的财产保险是指以财产及其有关的经济利益和损害赔偿责贵任为保险标的的保险：狭义的财产保险则是指以物质财产为保险标的的保险，狭义的财产保险又称为 财产损失保险。责任保险属于广义的财产保险。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2019年，某经销商进口了一辆3.5L排量的进口车，该车关税完悦价格为30万元，关税适用税率为15%，则应纳关税税额是（）万元。', '{"A": "4.8", "B": "5.25", "C": "3.6", "D": "4.5"}', '["D"]', '应纳关税税额=关税完税价格×适用税率=30×15%=4.5（万元），故本题答案选4.5', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '遗产分割时，应当保留胎儿的继承份额，若胎儿出生时是死体的，保留的份额处理办法是（）。', '{"A": "由其母亲继承", "B": "由其兄第姐妹继承", "C": "由胎儿的继承人继承", "D": "按法定继承办理"}', '["D"]', '按《民法典》规定，遗产分割时，应当保留胎儿的继承份额，如果胎儿出生时是死体的。保留的份额安照法定继承办理。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在评估资产的系统性风险时，可以使用系数来评价，关于系数正确的说法是（）。', '{"A": "β系数的绝对值越大，则投资组合相对全体市场的变化幅度越小", "B": "β系数可以衡量投资组合相对总体市场的波动性，β系数总是介于-1到+1之间", "C": "当市场处在牛市中，投资经理一般回调高投资组合的系数", "D": "全体市场本身的β系数就是0"}', '["C"]', '（1）β绝对值越大，显示其收益变化幅度相对于大盘的变化幅度越大；（2）全体市场本身的β系数为1，若资产组合净值的波动大于全体市场的波动幅度。则系数大于1。反 之，若资产组合净值的波动小于全体市场的波动幅度，则β系数就小于1，不是介于-1到+1之间。故本题答案选择“当市场处在牛市中，投资经理一般回调高投资组合的β系 数，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '对于普通家庭而言，潜在的家庭风险中对客户影响最大的是（），', '{"A": "信用风险", "B": "财产风险", "C": "投资风险", "D": "人身风险"}', '["D"]', '在人身保险中。风险事故是与人的生命和身体有关的“生、老、病、死、残”。客户一旦因意外。疾病或者死亡导致收入减少基至中断的活，不管是短期的还是长期的，对客 户家庭生活来讲都是非常严重的打击。故本题选择D选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '一般而言，下列关于理财师帮助客户制定财富保障规划时给出的建议中，不恰当的是（）。', '{"A": "根据客户的保险需求，选择合适的保险产品，将风险转嫁出去", "B": "在配置保险产品时，需要考虑的首要因素是客户的生命周期", "D": "家庭投保的险种越多，保障范围越大，因此应该让客户尽可能多的买保险"}', '["D"]', '财富保障规划作为理财规划中的重要部分，能够有效地规避或者减少家庭及个人面临的风险，降低风险对生活造成的冲击。将个人及家庭风险转嫁出去。可见，财富保障规划 不仅起到家庭生活保障的作用。还是一种重要的家庭财务安全规划。理财师在帮助客户制定财富保障规划的时候，要把握两个基本原则，一是风险转嫁的原则，根据客户的保 险需求，选择合适的保险产品。将风险转嫁出去；二是量力而行的原则，一般而言，家庭投保的险种越多，保障范围越大，保险金额越高，保险期限越长，保费需求越高。所 以不建议客户“尽可能多的买保险”，故本题答率选“家庭投保的险种越多，保障范围越大，因此应该让客户尽可能多的买保险”该项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '李先生家里有现金20万.另有60万存款是在李先生名下，李先生还买了一份保险，受益人为其夫人，保险总额50万，李先生突然身故，其遇产为）万元。', '{"A": "40", "B": "80", "C": "110", "D": "65"}', '["A"]', '夫妻共同财产总额=现金20万+存款60万=80万元。分割时。需先将共同财产的一半分给配偶(李夫人)，剩余一半属于被继承人(李先生)的遇产。李夫人分得：80万+2=40万元。 剩余部分：40万元，属于李先生的遗产，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列能够作为遗属见证人的是（），', '{"A": "继承人的近亲屋", "B": "与继承人共同经营企业的合伙人", "C": "继承人的债务人", "D": "继承人的同事"}', '["D"]', '遗瞩见证人是证明遗崛真实性的第三人。见证人证明的真伪直接关系着遗瞩的效力，关系到对遗产的处置。因此，遗喉见证人必须是能够客观公正地证明遗真实性的人。 《民法典》第一千一百四十条规定，下列人员不能作为遇崛见证人： （1）无民事行为能力人。限制民事行为能力人以及其他不具有见证能力的人； (2）继承人，受遇赠人： （3）与继承人。受遗赠人有利害关系的人。所以选项“继承人的近亲属、与继承人共同经营企业的合伙人和继承人的债务人”都是与继承人有利害关系的人，所以不能作为遗 嘱见证人。故本题答案选“继承人的同事”，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于企业年金缴费水平的表述，下列叙述错误的是（），', '{"A": "缴费水平应当为职工起到补充养老金的作用", "B": "缴费合计不应超过本企业上年员工工资的10%", "C": "缴费应革顾公平与效率", "D": "缴费应符合企业的经济承受能力"}', '["B"]', '合理的企业年金的缴费水平应当考虑以下几个因素：第一，必须符合企业的经济承受能力。第二，企业年金的缴费水平应当为职工起到补充养老保险的作用，这是企业年金存 在的根本价值。第三，企业年金缴费应兼顾公平和效率，一方面，企业年金应该尽量覆盖全体职工，并起到一定的激励作用：但另一方面，又要注意公平原则，不要将差距拉 得过于是殊，打击员工的积极性。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于教育保险的表述，错误的是（）', '{"A": "教育保险能够在一定程度上抵御通货能胀的影响", "B": "教育保险具有强制储蓄的功能", "C": "保险金额越高，每年需要交付的保费也就越多", "D": "教育保险不具有投资分红功能"}', '["D"]', '', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '退休养老规划是理财规划中不可或缺的理财目标，下列表述错误的是（），', '{"A": "退休养老规划主要由子女负责安排", "B": "需要提早做退休养老规划", "C": "退休养老规划是长期理财目标", "D": "退休养老规划应提前规划生活费支出"}', '["A"]', '退休养老规划是理财规划中不可或缺的长期理财目标。退休养老覆盖的时间长。成本高，面对的风险多，更需要人们提前预期到退休生活面临的各种风险，提前规划加以应 对。退休养老规划主要是由自已负责安排。而不是由子女来规划的。故本题答案选“退休养老规划主要由子女负责安排”。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在制定退休规划时，预期投资回报率的设定与客户的年龄。学历、风险偏好、对投资工具的认识，风险承受能力等相关，下列关于预期投资回报率的表述，错误的是（）。', '{"A": "随着客户的年龄逐渐增大，投资风格总体应趋于稳健，应当避免风险过大的投资行为", "B": "过高估计投资回报率，有可能导致达不到养老金的累计目标", "C": "由于退休规划中投资方式的风险不宜过大，所以对投资回报率的预期也不应过高", "D": "预期投资回报率越高时，客户需要筹备的养老金金额就越多"}', '["D"]', '在进行退休规划安排时。需要考虑七方面的因素：退休年龄。寿命长短、性别差异、通货影胀率、预期生活方式、现有资产状况和预期投资回报率。随着客户的年龄逐渐增 大，投资风格总体应趋于稳健，应当避免风险过大的投资行为，预期收益率要求：对投资回报率的预期不应过高，否则会导致达不到养老金的累计目标，预期投资回报率越高 时，客户需要筹备的养老金金额就越少，所以选项“预期投资回报率越高时，客户需要筹备的养老金金额就越多”说法错误。故本题答案选该项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '理财师在协助客户进行借贷活动决策时，正确的操作顺序是（0，（1）计算可贷金额（2）对未来现金流进行模拟（3）对借贷后家庭财务报表进行模拟', '{"A": "(1)(3)(2)", "B": "(2)(3)(1)", "C": "(1)(2)(3)", "D": "(2)(1)(3)"}', '["A"]', '理财师在帮助客户进行借贷决策时。应该从其未来的还贷能力出发，并对客户家庭财务特别同性的理财目标进行全面评估，以及对利率上升等风险进行分析后，才能确定借贷 金额。具体的实务操作内容如下：（1）根据现有的收支结余情况对可贷金额进行计算。（2）模拟借贷后的家庭财务接表，如资产负债表和收入支出表，分析借贷后的债务结构 整。故本题选择A选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '陈先生的孩子10年后高中毕业，他打算送孩子去国外读大学，陈先生一家目前持有生意资产10万元，并旦准备每年年末再投资2万元，这些钱准备用于孩子出国留学费用，假设 这些投资的年投资报酬率为6%。10年后，陈先生为孩子出国留学共准备了（）万元。（答案取近似数值）', '{"A": "45.85", "B": "44.27", "C": "32.11", "D": "43.08"}', '["B"]', '根据题中条件可知，陈先生用10万元进行投资。现值PV=-10（投资属于支出，记为负值），每年年未再投资2万元，属于年金，PMT=-2，利率r=6%，期数n=10，代入理财 计算器中，求出终值FV=44.27。所以10年后，陈先生为孩子出国留学准备了44.27万元。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在投资连结保险中，投资账户的资产免受保险公司其余负债的影响，资本利得或损失一旦发生，无论是否实现，都会（）。', '{"A": "间接反映到保单的账户价值上", "B": "直接反映到保单的账户价值上", "C": "直接反映到保单的保险金额上", "D": "间接反映到保单的保险金额上"}', '["B"]', '在投资连结保险中，投资账户的资产免受保险公司其余负债的影响，资本利得或损失一旦发生，无论是否实现，都会直接反映到保单的账户价值上。故本题选择B选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '般而言，中小企业财务管理中，面临的最大难题是（）。', '{"A": "管理混乱", "B": "融资难独资费", "D": "资金安全"}', '["B"]', '由于中小企业生产规模小。企业自身的资产规模不大，在中小企业财务管理中，面临的最大难题是融资难融资贵，而造成中小企业融资难的关键是信用级别低。故本题答案选 “融资难融资贵”', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '某债券面值100元，票面利率6%，期限10年，每年付息。如果到期收益率为8%，则其发行价格（）。', '{"A": "低于100元", "B": "高于100元", "C": "无法确定", "D": "等于100元"}', '["A"]', '债券的价格是由其未来现金流入量的现值决定的。债券未来现金收入由各期利息收入和到期时债券的变现价值两部分组成。在这里各期利息收入是100×6%=6（元），贴现率 就是其到期收益率，即8%。发行价格=6/（1+8%）+6/（1+8%）2+6/（1+8%）^3++6/（1+8%）^9+6/（1+8%）^10=86.58100', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '计算退休资金缺口是制定退休养老规划的关键步骤，关于其计算方式，下列选项中正确的是（）。', '{"A": "养老金缺口=FV退休需求-PV退休前资金积累-PV退休后既定养老金", "B": "养老金缺口=PV退休需求-FV退休前资金积累-PV退休后既定养老金", "C": "养老金缺口=FV退休需求-FV退休前资金积累+PV退休后既定养老金", "D": "养老金缺口=PV退休需求-PV退休前资金积累-PV退休后既定养老金"}', '["B"]', '养老金赤字=养老金总需求-养老金总供给=PV退休需求-（FV退休前资金积累+PV退休后既定养老金），其中“"PV退休需求”，反映退休后在保持一定生活水平下的养老金总 自退休后社保养老金等既定养老金在退休时点的现值，这两部分加起来即退休养老的总供给。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '李先生本月工资、新金收入6200元，国债利息收入500元，国家发行的金融债券利息收入400元，教育储蓄存款利息收入200元，则李先生应纳税额0）元。', '{"A": "195", "B": "255", "C": "36", "D": "205"}', '["C"]', '薪金所得，应纳所得税=（6200-5000）×3%=36（元），国债利息收入。国家发行的金融债券利息收入和教育储蓄存款利息收入均免税。因此，李先生该月应纳税额36元。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生今年55岁，计划60岁退休。目前他的年开支为10万元。假设预期寿命为85岁，年投资收益率为6%，在未来年通货影胀率为5%的情况下，张先生要维持现有的生活水准， 目前需要筹备养老金）万元。（答案取近似数值）', '{"A": "201.28", "B": "213.29", "C": "282.74", "D": "285.43"}', '["B"]', '通货膨胀率为5%，投资收益率为6%，实际收益率=（1+名义收益率）/（1+通货能胀率）-1=（1+6%）/（1+5%）-1=0.95%。到60退休时，年生活开销=10×（1+5%） ^5=12.76万元。张先生退休后25年的总支出折现到60岁时点。PV（FV=0，C=-12.76，1=0.95%，n=25，期初年金）=285.45。退休总开支从60岁时点折现到55岁时点， PV（FV=-285.45，n=5，[=6%，C=0）=213.30，故本题选择B选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '一般而言，在偿债能力指标分析中，有关流动比率描述正确的是（）：', '{"A": "流动比率越高，说明资产的流动性越大，短期偿付能力越强", "B": "流动比率可以用来衡量盈利能力对债务偿付的保证程度", "C": "流动比率应维持为1:1左右比较理想"}', '["A"]', '流动比率是衡星企业短期偿债能力的指标。流动比率=流动资产/流动负债，流动比率大于1，说明流动资产大于流动负债，企业短期偿债能力越强。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '联合及生存者年金是指（）： 3090 考前', '{"A": "以两个或两个以上的被保险人中至少还有一人生存为给付条件，且给付金额随着被保险人数的减少而进行调整的年金", "B": "以两个或两个以上的被保险人均死亡为给付条件的年金", "C": "以两个或两个以上的被保险人中至少还有一人生存为给付条件，且给付金额不发生变化的年金", "D": "以两个或两个以上的被保险人均生存为给付条件的年金"}', '["A"]', '联合及生存者年金是指以两个或两个以上保险人中至少还有一人生存为年金给付条件的年金保险，但与最后生存者年金不同的是联合及生存者年金在披保险人人数减少时， 给付的年金金额也会随之相应调低。联合及生存者年金的年金给付方式能较好地反映随着被保险人人数的减少，生活支出也相应减少的实际情况。故本题答案选“以两个或两 个以上的被保险人中至少还有一人生存为给付条件，且给付金额随着被保险人数的减少而进行调整的年金”', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在均衡状态下，最优风险组合中共有200只股票，200只股票市值合计为500亿元，其中某证券市值为5亿元，该证券在最优风险组合中的占比应该为（）。', '{"A": "1%", "B": "大于0且不高于0.5%", "C": "大于0且不高于1%", "D": "0.5%"}', '["A"]', '在均衡时，最优风险组合中各证券的构成比例等于市场组合中各证券的构成比例。所以该证券在最优风险组合中的占比=5+500=1%。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2023年1月，张先生和李女士夫妻二人有一个幼儿园即格毕业的儿子和一个刚出生的女儿。张先生父母健在，张父62岁，张母58岁，张先生还有一个亲哥哥在夏门工作。李女士 只有父亲健在，李父61岁，李女士为独生子女，夫妻二人在上海有一套住房，该房屋是张先生父母早年所购买，房屋产权证明登记为张先生，贷款合同的贷款人为张先生父母， 因工作原因，张先生需要在深圳租房居住，张先生2019年在接受学历继续教育的同时还取得技能人员职业资格证书。夫妻二人均为税前月收入3万元，无年终奖，根据以上资 料。回答下列问题。 2023年1月张先生和李女士的儿子幼儿园毕业，当月夫妻二人的子女教育专项时加扣除最合理的情况是（）', '{"A": "张先生1500元，李女土元1500元", "B": "张先生1000元，李女士1000元", "C": "张先生1500元，李女士2500元", "D": "张先生0元，李女士0元"}', '["B"]', '2022年1月1日起新增3岁以下婴幼儿照护个人所得税专项附加扣除。国务院发布关于提高个人所得税有关专项附加扣除标准的通知：①3岁以下婴幼儿照护专项扣除标准。 由每个婴幼儿每月1000元提高到2000元。②子女教育专项附加扣除标准，由每个子女每月1000元提高到2000元。父母可以选择由其中一方按扣除标准的100%扣除，也可以 选择由双方分别接扣除标准的50%扣除。所以答案选B选项', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2023年1月，张先生和李女士夫妻二人有一个幼儿园即将毕业的儿子和一个刚出生的女儿。张先生父母健在，张父62岁，张母58岁，张先生还有一个亲哥哥在厦门工作。李女士 只有父亲健在，李父61岁，李女土为独生子女，夫妻二人在上海有一套住房，该房屋是张先生父母早年所购买，房屋产权证明登记为张先生，贷款合同的贷款人为张先生父母， 因工作原因，张先生需要在深圳租房居住。张先生2019年在接受学历继续教育的同时还取得技能人员职业资格证书。夫妻二人均为税前月收入3万元，无年终奖。根据以上资 料，回答下列间题。 2023年1月张先生和李女士夫妻二人住房贷款和住房金专项时加扣除最合理的情况是0。', '{"A": "张先生1500元，李女士1000元", "B": "张先生1250元，李女士1250元", "D": "张先生2500元，李女士0元"}', '["C"]', '纳税人及其配偶在一个纳税年度内不能同时分别享受住房贷款利息和住房租金专项附加扣除。所以按照张先生租房来算，扣除标准为1500每月。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2023年1月，张先生和李女士夫妻二人有一个幼儿园即将毕业的儿子和一个刚出生的女儿。张先生父母健在，张父62岁，张母58岁，张先生还有一个亲哥哥在厦门工作。李女士 只有父亲健在，李父61岁，李女士为独生子女，夫妻二人在上海有一套住房，该房屋是张先生父母早年所购买，房屋产权证明登记为张先生，贷款合同的贷款人为张先生父母， 因工作原因，张先生需要在深圳租房居住。张先生2019年在接受学历继续教育的同时还取得技能人员职业资格证书。夫妻二人均为税前月收入3万元，无年终奖，根据以上资 料，回答下列问题， 2023年1月张先生工资收入适用的个人所得税税率是（）。', '{"A": "10%", "B": "5%", "C": "20%", "D": "3%"}', '["D"]', '张先生月收入为3万，扣除个税起征点5000元后，为25000元，根据前两问和第四问所求得的结果，张先生专项附加扣除可扣除2000+1500+1500=5000，25000- 5000=20000元，属于个人所得税税率表中的第一级，适用3%。 11', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2023年1月，张先生和李女士夫妻二人有一个幼儿园即将毕业的儿子和一个刚出生的女儿，张先生父母健在，张父62岁，张母58岁，张先生还有一个亲哥哥在厦门工作。李女士 只有父亲健在，李父61岁，李女士为独生子女，夫妻二人在上海有一套住房，该房屋是张先生父母早年所购买。房屋产权证明登记为张先生，贷款合同的贷款人为张先生父母， 料，回答下列问题。 2023年张先生和李女士，李父和家里的小女儿由于车祸均达到大病医疗扣除的“起付线”，则下列说法错误的是（）。', '{"B": ",李父的大病医疗支出，可以在李女士一方扣除包,过押是", "C": "夫妻两人同时有符合条件的大病医疗支出，可以选择都在男方扣除", "D": "小女儿的大病医疗支出，可以在李女士一方扣除"}', '["B"]', '纳税人发生的医药费用支出可以选择由本人或者其配偶扣除；未成年子女发生的医药费用支出可以选择由其父母一方扣除，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2023年1月，张先生和李女士夫妻二人有一个幼儿园即将毕业的儿子和一个刚出生的女儿。张先生父母健在，张父62岁，张母58岁，张先生还有一个亲哥哥在厦门工作。李女士 只有父亲健在，李父61岁，李女士为独生子女，夫妻二人在上海有一套住房，该房屋是张先生父母早年所购买，房屋产权证明登记为张先生，贷款合同的贷款人为张先生父母， 因工作原因，张先生需要在深圳租房居住。张先生2019年在接受学历继续教育的同时还取得技能人员职业资格证书。夫妻二人均为税前月收入3万元，无年终奖。根据以上资 料，国答下列间题。 2023年张先生和李女士夫妻二人继续教育专项附加扣除最合理的情况是（），', '{"A": "张先生2400元，李女士2400元", "B": "张先生4800元，李女士0元", "C": "张先生8400元，李女士0元", "D": "张先生3600元，李女士0元"}', '["C"]', '纳税人在中国境内接受学历（学位）继续教育的支出。在学历（学位）教育期间按照每月400元定额扣除。纳税人接受技能人员职业资格继续教育、专业技术人员职业资格继 续教育的支出，在取得相关证书的当年，按照3600元定赖扣除，纳税人接受学历继续教育，可以按照每月400元的标准扣除，全年共计4800元；在同年又取得技能人员职业资 格证书的，且符合扣除条件的，可按照3600元的标准定额扣除。因此对同时符合两种情形的纳税人，该年度可叠加享受两类扣除，当年可享受继续救育专项附件扣除共计8400 元（4800+3600）。 12', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '理财经理小危为客户蔡先生建立的投资组合由股票型基金、债券型基金以及国债三种证券构成。已知国债的预期收益率为5%，股票型基金的预期收益率为20%，标准差为30%； 债券型基金的预期收益率为10%，标准差为10%，由股票型基金和债券型基金组成的最优风险资产组合中的股票型基金占60%，债券型基金占40%，股票型基金与债券型基金的 相关系数为-0.4。根据以上材料，回答问题。', '{"A": "证券组合理论解释了投资者应当如何构建有效的证券组合并从中选出最优的证券组合", "B": "证券组合理论由哈里·马柯维茨创立", "C": "证券组合理论证明了分散投资可以保证一定预期收益。但无法降低组合的投资风险", "D": "证券组合理论量化了单一证券和证券组合的预期收益和风险"}', '["C"]', '证券投资组合理论由哈里·马柯维茨创立，该理论解释了投资者应当如伺构建有效的证券组合并从中选出最优的证券组合，所以选项A和B正确：1952年，哈里·马柯维茨发表了 一靠题为《证券组合选择》的论文，首次提出采用期望收益率和收益率的方差来衡量投资的预期收益水平和风险。把复杂的投资决策问题简化为一个均值与方差的二维问题。 并且，证明了分散投资可以在保证一定预期收益的情况下尽可能地降低风险，证券组合理论闻明了如何度量单一资产和资产组合的风险及预期收益，解释了投资者应当如何构 建有效的证券投资组合。所以选项D正确，选项C错误，错在“但无法降低组合的投资风险”，故本题答案选C。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '理财经理小會为客户藜先生建立的投资组合由股票型基金、债券型基金以及国债三种证券构成。已知国债的预期收益率为5%股票型基金的预期收益率为20%，标准差为30%； 债券型基金的预期收益率为10%标准差为10%，由股票型基金和债券型基金组成的最优风险资产组合中的股票型基金占60%，债券型基金占40%，股票型基金与债券型基金的 相关系数为-0.4。根据以上材料，回答问题。 （2）以下关于投资组合中两种证券间的相关系数。说法正确的是（。', '{"A": "当两种证券间的相关系数等于1时，这两种证券收益率之间没有什么关系", "B": "当两种证券间的相关系数等于1时，这两种证券收益率的变动方向是不一致的。但变动程度相同", "C": "当两种证券间的相关系数等于1时，这两种证券收益率的变动方向是一致的，但变动程度不同", "D": "当两种证券间的相关系数等于1时，这两种证券收益率的变动方向是一致的，并且变动程度也是相同的"}', '["D"]', '当两种证券间的相关系数等于1时，这两种证券收益率的变动方向是一致的。并且变动程度也是相同的。故本题答案选D，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '理财经理小靠为客户蔡先生建立的投资组合由股票型基金、债券型基金以及国债三种证券构成。已知国债的预期收益率为5%，股票型基金的预期收益率为20%，标准差为30%；债券型基金的预期收益 率为10%。标准差为10%。由股票型基金和债券型基金组成的最优风险资产组合中的股票型基金占60%，债券型基金占40%，股票型基金与债券型基金的相关系数为-0.4。根据以上材料，回答问题。 （3）蔡先生由股票型基金和债券型基金构成的最优风险资产组合的预期收益率为（）， %830', '{"A": "12%", "B": "20%", "D": "16%", "E": "(R) ="}', '["D"]', '预期收益率=60%×20%+40%×10%=16%，预期收益率的计算公式如下： Z(P × R)', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '理财经理小詹为客户蒙先生建立的投资组合由股票型基金、债券型基金以及国债三种证券构成。已知国债的预期收益率为5%，股票型基金的预期收益率为20%，标准差为 30%；债券型基金的预期收益率为10%，标准差为10%，由股票型基金和债券型基金组成的最优风险资产组合中的股票型基金占60%，债券型基金占40%，股票型基金与债券 型基金的相关系数为-0.4。根据以上材料，回答问题。 （5）假设风险资产在该组合中的投资比例为78%，黎先生的股票型基金、债券型基金和国债构成的整个投资组合的预期收益率为（），', '{"A": "18.23%", "B": "13.58%", "C": "15.39%", "D": "20.5%"}', '["B"]', '步骤1：计算最优风险资产组合的预期收益率 已知最优风险资产组合中，股票型基金占比60%，债券型基金占比40%，两者的预期收益率分别为20%和10%。最优风险资产组合的预期收益率=股票型基金占比×股票预 期收益率+债券型基金占比×债券预期收益率即：0.6×20%+0.4×10%=12%+4%=16% 步骤2：确定整个投资组合的构成 题目中风险资产在组合中的投资比例为78%，则无风险资产（国债）的投资比例为：1778%=22% 步骤3：计算整个投资组合的预期收益率 整个组合的预期收益率=风险资产组合占比×风险资产组合收益率+国债占比×国债收益率，已知国债预期收益率为5%，代入数据：', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '小王的客户李小姐是一位网络主播。2021年9月至10月为甲公司进行市场推广，双方签署了一份劳务协议，协议约定按照完工进度分3次付款，9月份分两次付款，每次均支付5， 000元，10月份支付8，500元，李小姐11月为乙公司提供咨询服务获得收入5，000元，12月为丙单位提供3次主持服务，每次报酬700元，各项收入均为税前收入，根据以上材 料，回答下列问题。 甲公司支付李小姐劳务费用时，预扣预的个人所得税适用税率是（），', '{"A": "20%", "B": "25%", "D": "10%"}', '["A"]', '劳务费用金额=5000+5000+8500=18500元，应纳脱所得额=18500*（1-20%）=14800元，查看劳务报酬三级税率表，适用20%的税率。故本题选择A选项。 14', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '小王的客户李小姐是一位网络主播。2021年9月至10月为甲公司进行市场推广，双方签署了一份劳务协议，协议约定按照完工进度分3次付款，9月份分两次付款，每次均支付5， 000元，10月份支付8，500元。李小姐11月为乙公司提供咨询服务获得收入5，000元。12月为丙单位提供3次主持服务，每次报酬700元。各项收入均为税前收入。根据以上材 料，回答下列问题。 甲公司应为李小姐劳务费用预扣预缴个人所得税（）元。', '{"A": "2960", "B": "0", "D": "4840"}', '["A"]', '应纳税额=14800×20%=2960元。故本题选择A选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '小王的客户李小姐是一位网络主播。2021年9月至10月为甲公司进行市场推广，双方签署了一份劳务协议，协议约定按照完工进度分3次付款，9月份分两次付款，每次均支付5， 000元，10月份支付8，500元。李小姐11月为乙公司提供咨询服务获得收入5，000元。12月为丙单位提供3次主持服务，每次报酬700元。各项收入均为税前收入。根据以上材 料，回答下列问题。 乙公司应为李小姐提供的咨询服务预扣预缴个人所得税（）元，', '{"A": "1000", "B": "560", "D": "O"}', '["C"]', '应纳税额=5000×（1-20%）×20%=800元。故本题选择C选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '小王的客户李小姐是一位网络主播。2021年9月至10月为甲公司进行市场推广，双方签署了一份劳务协议。协议约定按照完工进度分3次付款，9月份分两次付款，每次均支付5， 000元，10月份支付8，500元。李小姐11月为乙公司提供咨询服务获得收入5，000元。12月为丙单位提供3次主持服务，每次报酬700元。各项收入均为税前收入。根据以上材 料，回答下列问题。 丙单位应为李小姐提供的主持服务预扣预缴个人所得税（）元。', '{"A": "525", "B": "390", "D": "260"}', '["D"]', '应纳税赖=（3×700-800）×20%=260元，故本题选择D选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '小王的客户李小姐是一位网络主播。2021年9月至10月为甲公司进行市场推广，双方签署了一份劳务协议，协议约定按照完工进度分3次付款，9月份分两次付款，每次均支付5， 000元，10月份支付8，500元。李小姐11月为乙公司提供咨询服务获得收入5，000元。12月为丙单位提供3次主持服务，每次报酬700元。各项收入均为税前收入。根据以上材 料，回答下列问题， 李小姐听朋友说通过设立个人独资企业可以大幅度降低所得税率至5%以下，小王下列做法正确的是（）。', '{"A": "告诉李小姐他可以协助安非设立个人独资企业", "B": "告诚李小姐这种做法可能步嫌愉税漏税", "D": "为李小姐介绍转换为外籍身份的巢道从而减少税负"}', '["B"]', '税。故本题选择B选项。 15', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '刘先生的女儿8年后上大学,刘先生现在投入10万元作为学费专项资金，假设本科和研究生共7年，年学费现值为6万元，年投资回报率是6%。费用增长率是5%。根据以上材料,回 答下列问题。 （1）刘先生女儿上大学当年的费用是（）万元。（答案取近似数值）', '{"A": "9.12", "B": "8.86", "C": "6.42", "D": "6.12"}', '["B"]', '年学费现值为6万元费用增长率是5%，所以6×（1+5%）8=8.86，故本题选择B选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '刘先生的女儿8年后上大学,刘先生现在投入10万元作为学费专项资金，假设本科和研究生共7年，年学费现值为6万元，年投资回报率是6%。费用增长率是5%。根据以上材料,回 答下列问题。 2）假设刘先生需要在女儿上大学当年一次性准备好大学7年的学费，需要（）万元。（答案取近似数值）', '{"A": "59.98", "B": "57.86", "C": "61.23", "D": "60.3"}', '["D"]', '本题可看做增长型年金求现值，因为大学期间学费也在增长，学费支出为期初年金，PV=C/(r-g)(1-[(1+g)/(1+r)^t)（1+r），其中C=8.86，g=5%，t=7，r=6%，求得 PV=60.29，故本题选择D选项。【如何区分期初期末：首先要看题目有没有给出期初（年初），期末（年底。年末）投资这样的字眼，如果有的话，需要根据题目要求选择期 初和期末。如果没有，一般默认是期末，期初需要记佳几个爱考的，房租。养老金支出。生活费支出，看到这几个就选期初。复利问题直接默认勾选期未即可。】', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '刘先生的女儿8年后上大学,刘先生现在投入10万元作为学费专项资金，假设本科和研究生共7年，年学费现值为6万元，年投资回报率是6%。费用增长率是5%。根据以上材料.回 答下列问题。 （3）假设刘先生需要在女儿上大学当年准备好全部费用，则上大学当年的资金缺口是（）万元。（答案取近似数值）', '{"A": "44.36", "B": "40.48", "C": "41.92", "D": "46.24"}', '["A"]', '现在投入10万元作为学费专项资金，期限为8年，利率为6%，所以FV=10×（1+6%）8=15.94,缺口为60.3-15.94=44.36，故本题选择A选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '刘先生的女儿8年后上大学刘先生现在投入10万元作为学费专项资金，假设本科和研究生共7年，年学费现值为6万元，年投资回报率是6%。费用增长率是5%。根据以上材料,回 答下列问题。 （4）为了弥补女儿教育支出的缺口，刘先生计划每年末定投部分资金，假设年报酬率也是6%,则每年需要投入（）万元。（答案取近似数值）', '{"A": "4.23", "B": "4.48", "D": "4.98"}', '["B"]', '每年需要投入，也就是求C，C（I=6%，n=8，PV=0，FV=44.36，期末模式）=4.48，故本题选择B选项。 16', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '刘先生的女儿8年后上大学，刘先生现在投入10万元作为学费专项资金，假设本科和研究生共7年，年学费现值为6万元，年投资回报率是6%。费用增长率是5%。根据以上材料.回 答下列问题， （5）关于刘先生女儿的教育投资规划原则，下列说法中错误的是（），', '{"A": "计划周详、稳健投资", "B": "提前规划、从宽预计", "C": "专项积累、专款专用", "D": "积极进取，高额回报"}', '["D"]', '进行教育投资规划时，应注意遵循以下三项原则：提前规划、从宽预计（B选项）：专项积累、专款专用（C选项）：计划周详、稳健投资（A选项），故本题选择D选项，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '赵先生是一家互联网公司的创始人，公司年利润500万元。赵先生个人年收入200万元，其中工资薪金120万元，分红80万元。另外。赵先生拥有一套用于出租的房产，年租金收 入15万元。假设五险一金个人缴比例为工资薪金的20%，个人所得税起征点为每年6万元，股息红利所得适用税率为20%，假设当地上年社会平均工资为每月1万元，不考虑其他 专项附加扣除。根据以上材料。回答下列题。 赵先生当年缴纳的五险一金金额上限为（）万元', '{"A": "24", "B": "12.8", "C": "11", "D": "4.4"}', '["A"]', '赵先生当年缴纳的五险一金金额为120×20%=24万元，故本题答案选择A选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '赵先生是一家互联网公司的创始人，公司年利润500万元。赵先生个人年收入200万元，其中工资薪金120万元，分红80万元。另外，赵先生拥有一套用于出租的房产，年相金收 入15万元，假设五险一金个人撤比例为工资薪金的20%，个人所得税起征点为每年6万元，股息红利所得适用税率为20%，假设当地上年社会平均工资为每月1万元，不考虑其他 专项附加扣除。根据以上材料，回答下列问题。 赵先生按上限缴纳五险一金后，当年工资薪金应纳税所得额为（）万元。', '{"A": "60", "B": "114", "C": "90", "D": "100"}', '["C"]', '应纳税所得额=工资薪金收入-基本减除费用（起征点）-专项扣除（五险一金个人缴纳部分）工资薪金收入：题目明确为120万元。基本减除费用（起征点）：每年6万元。专 项扣除（五险一金）：24万元。代入公式计算：应纳税所得额=(120-6-24=90）（万元）', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '赵先生是一家互联网公司的创始人，公司年利润500万元。赵先生个人年收入200万元，其中工资薪金120万元，分红80万元，另外，赵先生用有一套用于出租的房产，年租金收 入15万元。假设五险一金个人缴比例为工资薪金的20%，个人所得税起征点为每年6万元，股息红利所得适用税率为20%，假设当地上年社会平均工资为每月1万元，不考虑其他 专项附加扣除。根据以上材料，回答下列问题。 当年赵先生工资薪金部分缴纳的个人所得税为（）万元。（答案取近似数值）', '{"A": "29.87", "B": "25.31", "C": "22.23", "D": "23.72"}', '["C"]', '工资薪金所得适用七级超额累进税率，90万适用税率为35%，速算扣除数为8,592万元，所以90×35%-8.592=22.908，取近似值为22.23万。 17', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '赵先生是一家互联网公司的创始人，公司年利润500万元。赵先生个人年收入200万元，其中工资薪金120万元，分红80万元。另外，赵先生拥有一套用于出租的房产，年租金 收入15万元。假设五险一金个人缴比例为工资薪金的20%，个人所得税起征点为每年6万元，股息红利所得适用税率为20%，假设当地上年社会平均工资为每月1万元，不考虑 其他专项射加扣除。根据以上材料，回答下列问题。 赵先生的公司若想降低企业所得税税负，以下做法可行的是（）。', '{"A": "多发放点员工福利，超出合理范围", "B": "陷藏部分收入", "C": "随意调整固定资产折旧年限", "D": "对研发费用进行加计扣除"}', '["D"]', '选项A：多发放点员工福利，超出合理范围企业发放合理的员工福利可作为成本费用在税前扣除，但超出合理范围的福利支出无法全额扣除。根据税法规定，不合理的福利 支出可能被税务机关认定为“与生产经营无关的支出”，不予税前扣除，基至可能被视为避税行为面临处罚，因此该做法不可行。选项B：隐藏部分收入，隐藏收入属于偷税 漏税行为，违反《税收征收管理法》。税务机关通过稽查可发现隐满收入的情况，企业将面临补税、滞纳金及罚款，情节严重者可能追究刑事责任，该做法完全不可行。选 项C：随意调整固定资产折旧年限，固定资产折旧年限需按照税法规定或企业会计准则确定，随意调整折旧年限以增加折旧费用。减少应纳税所得额，属于人为操纵利润的避 税行为。税务机关有权进行纳税调整，要求企业按正确年限计算折旧并补税。因此该做法不可行。选项D：对研发费用进行加计扣除，根据我国企业所得税法，企业开展研 发活动发生的研发费用，未形成无形资产计入当期损益的，在按规定据实扣除的基础上，可按实际发生额的175%在税前加计扣除；形成无形资产的，可按无形资产成本的', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）客户背景资料 2023年1月，理财师小张认识了罗先生一家，罗先生35岁，在一家外企担任人力资源总监。罗太太王女士与其同龄，是基层公务员，夫妻两人都有社会保险。女儿小罗7岁，刚 上小学一年级，罗先生的母亲62岁，和罗先生一家同住。罗先生的父亲2021年去世，罗父的兄弟姐妹四人均健在，其兄弟姐妹也有子女与罗先生年龄相近，王女士父母健在。 与王女士的哥哥住在一起。 2022年罗先生税前月薪是50000元，其他税前收入来源方面，罗先生于2022年末领取年终奖100000元；当年还偶尔给大学生进行线上授课，全年课酬收入共10000元。2022 一家四口每月主要支出项目：房贷、水。电。煤、通讯及家庭生活用品等的开销，女儿的教育费用，还有人身保险费用及社交等机动开支约25000元；每年度的大项开支主要 为10000元左右的汽车维修及保险费用，以及50000元的出国旅游费用。 现有住房是两人的主要资产，目前市值500000元，房贷余额3000000元，购房时的房贷利率为4%，购房后一直未调整，房贷还剩20年。其他资产方面，目前夫妻在某国有 大行有1000000元存款，专项用于女儿未来的学费，每年存款利息22000元。罗先生企业年金账户累积了100000元。他们还有一辆价值200000元的家用车。罗先生公司另有 份团体意外险，如发生意外事故赔付金额为700000元，另外有保额为1000000元的定期寿险，王女士个人购买了两份投连险保险，保单现金价值10000元。请根据该案例的 背景信息，回答下列问题： 罗先生家庭处在（）生命周期，管理资产应当（）。', '{"A": "成长期，注重投资的风险管理", "B": "成熟期，降低投资风险", "C": "形成期，追求高风险高收益资产", "D": "衰老期，投资以固定收益类为主"}', '["A"]', '', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）客户背景资料 2023年1月，理财师小张认识了罗先生一家，罗先生35岁，在一家外企担任人力资源总监。罗太太王女士与其同龄，是基层公务员，夫妻两人都有社会保险，女儿小罗7岁， 上小学一年级，罗先生的母亲62岁，和罗先生一家同住。罗先生的父亲2021年去世，罗父的兄弟姐妹四人均健在，其兄弟姐妹也有子女与罗先生年龄相近，王女士父母健在。 与王女士的哥哥住在一起。 2022年罗先生税前月薪是50000元，其他税前收入来源方面，罗先生于2022年末领取年终奖100000元；当年还偶尔给大学生进行线上授课，全年课酬收入共10000元。2022 一家四口每月主要支出项目：房贷、水、电、煤、通讯及家庭生活用品等的开销，女儿的教育费用，还有人身保险费用及社交等机动开支约25000元；每年度的大项开支主要 为10000元左右的汽车维修及保险费用，以及50000元的出国旅游费用。 现有住房是两人的主要资产，目前市值5000000元，房贷余额3000000元，购房时的房贷利库为4%，购房后一直未调整，房贷还剩20年，其他资产方面，目前夫妻在某国有 大行有1000000元存款，专项用于女儿未来的学费，每年存款利息22000元。罗先生企业年金账户累积了100000元。他们还有一辆价值200000元的家用车。罗先生公司另有 一份团体意外险，如发生意外事故赔付金额为700000元，另外有保额为1000000元的定期寿险，王女士个人购买了两份投连险保险，保单现金价值10000元。请根据该案例的 背景信息，回答下列问题： 2023年5月，王女士的粗母和罗先生同时耀患大病，个人花费均超过8万元的限额。罗先生和王女士当月的个人所得税专项时加口除，最有可能的情况是（），', '{"A": "罗先生83000元，王女士1000元", "B": "罗先生4000元，王女士160000元", "C": "罗先生82000元，王女士84000元", "D": "罗先生83000元，王女士83000元"}', '["A"]', '', 3);
