INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）客户背景资料 2023年1月，理财师小张认识了罗先生一家，罗先生35岁，在一家外企担任人力资源总监。罗太太王女士与其同龄，是基层公务员，夫要两人都有社会保险。女儿小罗7岁，刚 上小学一年级，罗先生的母亲62岁，和罗先生一家同住。罗先生的父亲2021年去世，罗父的兄弟姐妹四人均健在，其兄弟姐妹也有子女与罗先生年龄相近，王女士父母健在。 与王女士的哥哥住在一起。 2022年罗先生税前月薪是50000元，其他税前收入来源方面，罗先生于2022年末领取年终奖100000元；当年还偶尔给大学生进行线上授课，全年课酬收入共10000元。2022 一家四口每月主要支出项目：房贷、水、电、煤、通讯及家庭生活用品等的开销，女儿的教育费用，还有人身保险费用及社交等机动开支约25000元；每年度的大项开支主要 为10000元左右的汽车维修及保险费用，以及50000元的出国旅游费用。 现有住房是两人的主要资产，目前市值5000000元，房贷余额3000000元，购房时的房贷利率为4%，购房后一直未调整，房贷还剩20年。其他资产方面，目前夫要在某国有 大行有100000元存款，专项用于女儿未来的学费，每年存款利息22000元。罗先生企业年金账户累积了100000元。他们还有一辆价值200000元的家用车。罗先生公司另有 一份团体意外险，如发生意外事故赔付金额为700000元，另外有保额为1000000元的定期寿险，王女士个人购买了两份投连险保险，保单现金价值10000元，请根据该案例的 背景信息，回答下列问题： 罗先生父亲去世时，关于其遗产继承的说法，正确的是（）。', '{"A": "罗先生的女儿有转继承权", "B": "罗先生堂弟的儿子有代位继承权", "C": "罗先生的太太有继承权", "D": "罗先生的母亲有继承权"}', '["D"]', '', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）客户背景资料 2023年1月，理财师小张认识了罗先生一家，罗先生35岁，在一家外企担任人力资源总监。罗太太王女士与其同龄，是基层公务员，夫妻两人都有社会保险。女儿小罗7岁，刚 上小学一年级，罗先生的母亲62岁，和罗先生一家同住。罗先生的父亲2021年去世，罗父的兄弟姐妹四人均健在，其兄弟姐妹也有子女与罗先生年龄相近，王女士父母健在， 与王女士的哥哥住在一起。 2022年罗先生税前月薪是50000元，其他税前收入来源方面，罗先生于2022年末领取年终奖100000元；当年还偶尔给大学生进行线上授课，全年课酬收入共10000元。2022 一家四口每月主要支出项目：房贷、水、电、煤、通讯及家庭生活用品等的开销，女儿的教育费用，还有人身保险费用及社交等机动开支约25000元：每年度的大项开支主要 为10000元左右的汽车维修及保险费用。以及50000元的出国旅游费用。 现有住房是两人的主要资产，目前市值5000000元，房贷余额3000000元，购房时的房贷利率为4%，购房后一直未调整，房贷还剩20年。其他资产方面，目前夫妻在某国有 大行有1000000元存款，专项用于女儿未来的学费，每年存款利息22000元。罗先生企业年金账户累积了100000元。他们还有一辆价值200000元的家用车。罗先生公司另有 一份团体意外险，如发生意外事故赔付金额为700000元，另外有保额为1000000元的定期寿险，王女士个人购买了两份投连险保险，保单现金价值10000元。请根据该案例的 背景信息，回答下列问题： 理财师小张为罗先生介绍家族信托业务时，其中正确的说法是（）。', '{"A": "家族信托的受益人人数不能超过8人，且不能是外籍人士", "B": "家族信托的受益人应包括委托人及其家庭成员，其中要托人可以是唯一受益人", "C": "家族信托可以聘请不同的投资顾问打理信托财产，投资顾问可以是银行、资产管理公司", "D": "家族信托受益人可以是慈善组织，但不能是慈善信托"}', '["C"]', '', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项》客户背景资料 2023年1月，理财师小张认识了罗先生一家，罗先生35岁，在一家外企担任人力资源总监。罗太太王女士与其同龄，是基层公务员，夫妻两人都有社会保险，女儿小罗7岁，刚 上小学一年级，罗先生的母亲62岁，和罗先生一家同住，罗先生的父亲2021年去世，罗父的兄弟姐妹四人均健在，其兄弟姐妹也有子女与罗先生年龄相近，王女士父母健在， 与王女士的哥哥住在一起。 2022年罗先生税前月薪是5000元，其他税前收入来源方面，罗先生于2022年末领取年终奖100000元；当年还偶尔给大学生进行线上授课，全年课酬收入共10000元。2022 一家四口每月主要支出项目：房贷、水、电、煤。通讯及家庭生活用品等的开销，女儿的教育费用，还有人身保险费用及社交等机动开支约25000元；每年度的大项开支主要 为10000元左右的汽车维修及保险费用，以及50000元的出国旅游费用。 现有住房是两人的主要资产，目前市值5000000元，房贷余额3000000元，购房时的房贷利率为4%，购房后一直未调整，房贷还剩20年。其他资产方面，目前夫妻在某国有 大行有1000000元存款，专项用于女儿未来的学费，每年存款利息22000元，罗先生企业年金账户累积了100000元。他们还有一辆价值200000元的家用车。罗先生公司另有 一份团体意外险，如发生意外事故赔付金额为700000元，另外有保额为1000000元的定期寿险，王女士个人购买了两份投连险保险，保单现金价值10000元。请根据该案例的 背景信息，回答下列问题： 保险金信托作为一种新兴的财富传承工具受到了王女士的关注，下列关于保险金信托的说法，错误的是（），', '{"A": "不是所有的保险产品都可以纳入保险金信托", "B": "保险金信托的起点金额可以为100万元人民币", "C": "人寿保险的受益人，需要同时是信托计划的受益人和信托计划本身，保险金信托才能设立", "D": "保险金信托一般为他益信托，以家庭财富的保护、传承和管理等为目的而设立"}', '["B"]', '', 3);
