INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）客户背景资料 2023年1月，理财师小张认识了罗先生一家，罗先生35岁，在一家外企担任人力资源总监。罗太太王女士与其同龄，是基层公务员，夫妻两人都有社会保险。女儿小罗7岁，刚 上小学一年级，罗先生的母亲62岁，和罗先生一家同住。罗先生的父亲2021年去世，罗父的兄弟姐妹四人均健在，其兄弟姐妹也有子女与罗先生年龄相近，王女士父母健在。 与王女士的哥哥住在一起。 2022年罗先生税前月薪是50000元，其他税前收入来源方面，罗先生于2022年末领取年终奖100000元；当年还偶尔给大学生进行线上授课，全年课酬收入共10000元，2022 一家四口每月主要支出项目：房贷、水、电、煤、通讯及家庭生活用品等的开销，女儿的教育费用，还有人身保险费用及社交等机动开支约25000元：每年度的大项开支主要 为10000元左右的汽车维修及保险费用，以及50000元的出国旅游费用。 现有住房是两人的主要资产，目前市值5000000元，房贷余额3000000元，购房时的房贷利率为4%，购房后一直未调整，房贷还剩20年。其他资产方面，目前夫妻在某国有 大行有1000000元存款，专项用于女儿未来的学费，每年存款利息22000元。罗先生企业年金账户累积了100000元。他们还有一辆价值200000元的家用车。罗先生公司另有 一份团体意外险，如发生意外事故赔付金额为700000元，另外有保额为1000000元的定期寿险，王女士个人购买了两份投连险保险，保单现金价值10000元。请根据该案例的 背景信息，回答下列问题： 疫情结束后，罗先生一家有境外旅游的计划，并考虑换取一定量的外汇，下列关于个人外汇业务的说法中正确的是（），', '{"A": "同日同一币种，不同银行或者外币兑换机构的汇率可能不同", "B": "商业银行能办理某种货币的现汇业务就一定能办理该币种的现钞业务", "C": "在用人民币购买外汇时应参考银行买入价（汇）", "D": "出国旅游无论去鄂个国家都需要在银行开具存款证明"}', '["A"]', '', 3);
