INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）客户背景资料 2023年1月，理财师小张认识了罗先生一家，罗先生35岁，在一家外企担任人力资源总监。罗太太王女士与其同龄，是基层公务员，夫妻两人都有社会保险，女儿小罗7岁，刚 上小学一年级，罗先生的母亲62岁，和罗先生一家同住。罗先生的父亲2021年去世，罗父的兄弟姐妹四人均健在，其兄弟姐妹也有子女与罗先生年龄相近，王女士父母健在。 与王女士的哥哥住在一起。 2022年罗先生税前月薪是50000元，其他税前收入来源方面，罗先生于2022年末领取年终奖100000元；当年还偶尔给大学生进行线上授课，全年课酬收入共10000元。2022 一家四口每月主要支出项目：房贷、水、电、煤、通讯及家庭生活用品等的开销，女儿的教育费用，还有人身保险费用及社交等机动开支约2500元；每年度的大项开支主要 为10000元左右的汽车维修及保险费用，以及50000元的出国旅游费用。 现有住房是两人的主要资产，目前市值5000000元，房贷余额3000000元，购房时的房贷利率为4%，购房后一直未调整，房贷还剩20年。其他资产方面，目前夫麦在某国有 大行有1000000元存款，专项用于女儿未来的学费，每年存款利息22000元。罗先生企业年金账户累积了100000元。他们还有一辆价值200000元的家用车。罗先生公司另有 一份团体意外险，如发生意外事故赔付金额为700000元，另外有保额为1000000元的定期寿险，王女士个人购买了两份投连险保险，保单现金价值10000元。请根据该案例的 背景信息，回答下列问题： 罗先生看到银行销售的理财产品有不同的业绩比较基准或业绩展示，下列理财产品的业绩比较基准或业绩展示中，不合规的是（）。', '{"A": "沪深300ESG基准指数*30%+中债综合指数(全价)*65%+活期存款利率*5%", "B": "2.75%-2.95%，保底收益率不低于2.75%", "C": "7日年化收益率3.14%，万份收益0.7541元", "D": "成立以来年化收益率3.74%"}', '["B"]', '', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '（不定项）客户背景资料 2023年1月，理财师小张认识了罗先生一家，罗先生35岁，在一家外企担任人力资源总监。罗太太王女士与其同龄，是基层公务员，夫妻两人都有社会保险。女儿小罗7岁， 上小学一年级，罗先生的母亲62岁，和罗先生一家同住。罗先生的父亲2021年去世，罗父的兄弟姐妹四人均健在，其兄弟姐妹也有子女与罗先生年龄相近，王女士父母健在。 与王女士的哥哥住在一起。 2022年罗先生税前月薪是50000元，其他税前收入来源方面，罗先生于2022年末领取年终奖100000元；当年还偶尔给大学生进行线上授课，全年课酬收入共10000元。202 一家四口每月主要支出项目：房贷、水、电、煤、通讯及家庭生活用品等的开销，女儿的教育费用，还有人身保险费用及社交等机动开支约25000元；每年度的大项开支主要 为10000元左右的汽车维修及保险费用，以及50000元的出国旅游费用。 现有住房是两人的主要资产，目前市值5000000元，房贷余额3000000元，购房时的房贷利率为4%，购房后一直未调整，房贷还剩20年。其他资产方面，目前夫要在某国有 大行有100000元存款，专项用于女儿未来的学费，每年存款利息22000元。罗先生企业年金账户累积了100000元，他们还有一辆价值20000元的家用车。罗先生公司另有 一份团体意外险，如发生意外事故赔付金额为700000元，另外有保额为1000000元的定期寿险，王女士个人购买了两份投连险保险，保单现金价值10000元。请根据该案例怕 背景信息，回答下列问题： 王女士了解到购买投资连结保险，既能增加自身的保险，又能参与资本市场投资。于是请教理财师小张关于投资连结保险的业务细节。理财师小张在解释投资连结保险时说 到，投资连结保险的死亡保险金额是按照保险金额和投资账户价值两者较大者确定的，死亡保险金额的变化规律是（）。', '{"A": "保单前期不变，在投资账户价值超过保险金额后，随保险金额波动", "B": "保单后期不变，在投资账户价值超过保险金额前，随保险金额动", "C": "保单前期不变，在投资账户价值超过保险金额后，随投资账户价值波动", "D": "保单后期不变，在投资账户价值超过保险金额前，随投资账户价值波动"}', '["C"]', '', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）客户背景资料 2023年1月，理财师小张认识了罗先生一家，罗先生35岁，在一家外企担任人力资源总监。罗太太王女士与其同龄，是基层公务员，夫妻两人都有社会保险。女儿小罗7岁，刚 上小学一年级，罗先生的母亲62岁，和罗先生一家同住，罗先生的父亲2021年去世，罗父的兄弟姐妹四人均健在，其兄弟姐妹也有子女与罗先生年龄相近，王女士父母健在， 与王女士的哥哥住在一起。 2022年罗先生税前月薪是50000元，其他税前收入来源方面，罗先生于2022年末领取年终奖100000元；当年还偶尔给大学生进行线上授课，全年课酬收入共10000元。2022 一家四口每月主要支出项目：房贷、水。电、煤、通讯及家庭生活用品等的开销，女儿的教育费用，还有人身保险费用及社交等机动开支约25000元；每年度的大项开支主要 为10000元左右的汽车维修及保险费用，以及50000元的出国旅游费用。 现有住房是两人的主要资产，目前市值5000000元，房贷余额3000000元，购房时的房贷利率为4%，购房后一直未调整，房贷还剩20年，其他资产方面，目前夫妻在某国有 大行有1000000元存款，专项用于女儿未来的学费，每年存款利息22000元。罗先生企业年金账户累积了100000元。他们还有一辆价值200000元的家用车。罗先生公司另有 一份团体意外险，如发生意外事故赔付金额为700000元，另外有保额为1000000元的定期寿险，王女士个人购买了两份投连险保险，保单现金价值10000元。请根据该案例的 背景信息，回答下列问题： 王女士认为理财师小张有不当销售行为，因此去找小张所在的机构进行投诉。在处理投诉时，大堂经理小刘的下列说法中，最恰当的是（）。', '{"A": "我们发现小张没有问题", "B": "我会尽快联系有关部门为您解决问题", "C": "这不是我们管辖的范围", "D": "您的问呕不属于我们部门的责任"}', '["B"]', '', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '除了基本社会养老保险之外。其他类型的社会福利还包括（）。', '{"A": "国家基本医疗保障计划", "B": "员工持股计划", "C": "利润分享计划", "D": "失业保险和就业保障", "E": "国家住房保障计划"}', '["A", "D", "E"]', '除了基本社会养老保险之外，其他类型的社会福利还包括国家基本医疗保障计划、国家住房保障计划、失业保险和就业保障、工伤保险，最低生活保障等， 25', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '关于税务规划。下列表述错误的有（）。', '{"A": "税负转嫁筹划和节税筹划都受到商品供求弹性影响", "B": "节税筹划和税负转嫁筹划都不影响整体税收收入", "C": "税负转嫁筹划和节税筹划都受到政策导向的影响", "D": "节税筹划是为纳税主体实现不缴税或少缴税的目的", "E": "税负转嫁筹划与节税筹划都是合法的税务规划手段"}', '["A", "B", "C"]', '税负转嫁是指纳税人为了达到减轻税负的目的，通过价格的调整和变动。将税负转嫁给他人承担的经济行为。节税筹划是指纳兑人在不违背税法立法精神的前提下，充分利用 税法中固有的起征点、减免税等一系列优惠政策，通过对筹资活动、投资活动以及经营活动进行一定的安排，从而实现少缴或不缴税。D选项正确。（1）转嫁不影响税收收 项错误。（3）如果纳税人通过节税筹划最大限度地利用税法中固有的优惠政第来享受其利益，其结果正是税法中优惠政策所要引导的，因此。节税本身正是优惠政策借此实现 宏观调控目的的载体。C选项错误。（4）税负转嫁筹划与节税筹划都是合法的税务规划手段，E选项正确。故本题选择ABC选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '制定教育投资规划方案的主要步案包括（）。', '{"A": "计算教育资金总供给和资金缺口", "B": "计算资金需求和退休收入", "C": "计算教育资金需求", "D": "风险估测"}', '["A", "C", "E"]', '制定教育投资规划方案的主要步骤包括：（1）计算教育资金需求；（2）计算教育资金总供给和资金缺口：（3）制订教育投资方案、选择投资工具。 26', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '关于速释继承，下列说法正确的有（）', '{"A": "如果其数份遗喔中有一份是经过公证的，则以公证的遗瞩为准", "B": "对于其遗喉中没涉及的财产，应按法定继承处理", "C": "即使有数份遗嘱。也应按法定继承处理", "D": "如果其数份遗曬内容相冲突，应以代书遗眠为准"}', '["B", "E"]', '遇属继承：（1）立有数份遇喉。内容相抵触的。以最后的遗喔为准。并不是以公证的、代书的遗崛或者是法定继承为准，ACD错误。（2）对于其遇崛中没涉及的财产，应按 法定继承处理，B正确。（3）遗嘱的内客是遇嘱人在遇瞩中表示出来的对自己合法财产进行处分的意思，是对其合法财产以及相关事直的处置、安排，应明确。具体，便于执 行，E正确。故本题选择BE选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '以下关于基金的表述，正确的有（）， ■A.基金管理人与基金托管人之间是经营与监管的关系', '{"B": "基金管理人可以将自有财产混同于基金财产从事证券投资", "C": "基金持有人与基金管理人之间是所有者与经营者的关系", "D": "基金管理人与基金托管人之间是委托与受托的关系", "E": "基金持有人与基金管理人之间是持有与托管的关系"}', '["A", "C"]', '（1）持有人与管理人之间：基金持有人是基金的实际所有者，而基金管理人则是凭借专门的知识与经验，运用所管理基金的资产，根据法律、法规及基金章程或基金契约的 是所有人与经营者之间的关系。 （2）管理人与托管人之间：管理人与托管人之间是经营与监管的关系。基金管理人和基金托管人应当在行政上、财务上相互独立，其高级管理人员不得在对方兼任何职务。 基金管理人由投资专家组成，负责基金资产的经营；托管人由主管机关认可的金融机构担任，负责基金资产的保管，依据基金管理机构的指令处置基金资产并监督管理人的 投资运作是否合法合规。对基金管理人而言，处理有关证券、现金收付的具体事务交由基金托管人办理，自己就可以专心从事资产的运用和投资决策。基金管理人和基金托 管人均对基金持有人负责。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '甲乙已经办理结婚登记但还没有举行婚礼，甲就意外死亡，此时，乙已经怀孕3个月，因此（）可以参加继承甲遇产。', '{"A": "乙未出生的孩子", "B": "甲的父母", "C": "甲与前妻生的孩子", "D": "乙的父母", "E": "乙本人"}', '["A", "B", "C", "E"]', '男女双方办理了结婚登记之后，即确立了互为配偶的夫麦关系。有相互继承遗产的权利。第一顺序继承人为：配偶、父母、子女，遗产分割时。应当保留胎儿的继承份额。第 二顺序：兄弟姐妹。祖父母、外祖父母。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '关于两种资产收益率的协方差和相关系数。下列说法正确的有0）。 ■C.协方差为负，说明两种资产收益率变动方向相同', '{"A": "协方差为正，说明两种资产收益率变动方向相同", "B": "相关系数为零，说明两种资产收益率变动方向无关", "D": "相关系数为正，说明两种资产变动方向相同", "E": "相关系数为负，说明两种资产收益率变动方向相同"}', '["A", "B", "D"]', '协方差的符号（正或负）可以反映出投资组合中两种资产之间的相互关系：（1）如果协方差为正，那就表明投资组合中的两种资产的收益呈同向变动趋势，即在任何一种经济 情况下同时上升或同时下降，A正确。（2）如果协方差为负值，则反映出投资组合中两种资产的收益具有反向变动的关系，即在任何一种经济情况下，一种资产的收益上升， 那么另一种资产的收益就会下降，C错误，如果协方差的值为零，就表明两种金融资产的收益没有相关关系。（3）相关系数等于两种金融资产的协方差除以两种金融资产的标 资产的收益负相关，D正确。E错误；如果相关系数为零，说明两种资产的收益之间没有相关性，B正确。故本题选择ABD选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '一般而言，下列属于退休规划制定步曬的有（）。', '{"A": "计算资金需求和退休收入", "B": "计算资金缺口", "C": "确定家庭成员的需求", "D": "制订退休规划，确定投资工具", "E": "确定退休目标"}', '["A", "B", "D", "E"]', '退休养老规划步分析：（1)接触客户，建立信任关系：（2)收集、整理和分析客户的家庭财务状况；（3)明确客户的退休目标（E正确）：（4)制订退休养老规划方案，第一步：计 算退休养老资金需求（A正确）。第二步：计算退休收入（A正确）。第三步：计算资金缺口（B正确），第四步：制订退休养老规划。养老投资规划的制定。基于前期对客户 财务状况的了解，包括现有储蓄、投资分布和风险偏好，综合考忠养老金缺口，然后确定投资工具、投资组合的选择（D正确），（5)退休养老规划方案的执行：（6)后续跟踪服 务。故本题选择ABDE选项。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '在实际生活中，中小企业主的生活与企业之间关联较高，因此中小企业主体为一个群体，面临的风险特征主要包括），', '{"A": "企业经营风险", "B": "地缘政治风险", "C": "资产传承风险", "D": "个人人身风险", "E": "宏观政第风险"}', '["A", "C", "D"]', '一般而言，中小企业主所面临的风险有以下特征：企业经营风险：个人人身风险；资产传承风险， 28', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '理财师分析完客户财务状况之后，通常可以得出初步诊断和建议的有（），', '{"A": "养老规划方案", "B": "家族信托方案", "C": "移民和留学规划", "D": "家庭现金储备的改善", "E": "指出客户当前的资产配置的问题和风险"}', '["D", "E"]', '分析完客户的财务状况，理财师可以得出初步的诊断和建议： 1.通过收入结构的分析，为客户提供税务筹划： 2.通过流动性分析，引导客户关注家庭现金储备的问题： 3.通过信用和债务管理方面的分析，为客户提供债务整合计划： 4.通过投资现状的分析，指出客户当前资产配置的问题及其风险： 5.通过家庭财务保障的分析，提醒客户关注潜在的财务风险等，故本题答案选“家庭现金储备的改善和指出客户当前的资产配置的问题和风险”，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '在解决了客户“现在在哪里”和“准备去哪里”的问题后，理财师需要向客户提出综合的实现其各项理财目标的建议。措施。这些建议主要包括（），', '{"A": "针对客户现阶段的家庭财富保障的建议，以及保险产品的推荐", "B": "针对客户现阶段的资产配置的诊断分析和调整建议，以及具体理财产品的推荐", "C": "关于实施理财规划方案的相关安排和建议", "D": "针对其他各项理财目标和方案的总结，以及提出的具体财务安排或措施", "E": "针对客户当前关心的财务问题的建议，以及和其他理财目标之间的关系和影响的分析"}', '["A", "B", "C", "D", "E"]', '心的财务问题的建议，以及和其他理财目标之间的关系分析：（2）针对其他各项理财目标和方案的总结，以及提出的具体财务安排或措施；（3）针对客户现阶段的家庭财富 保障的评估和建议，依据保费预算和应有保额配置保险产品： （4）针对客户现阶段的资产配置的诊断分析和调整建议，配置投资理财产品： （5）关于理财规划方案实施的相 关安排和建议，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '王先生在购买保险时了解到。在我国投保人购买保险时需要履行告知义务。从理论上讲。投保人需告知的内容包括（）：', '{"A": "已知的与风险和标的有关的实质性重要事实", "B": "保验标的风险增加的事实", "C": "应知的与风险和标的有关的实质性重要事实", "D": "保险合同免责条款", "E": "投保申请表中的问题"}', '["A", "B", "C"]', '告知（也称披露或陈述）是指合同订立前、订立时及在合同有效期内，要求当事人实事求是、尽自己所知、毫无保留地向对方所作的口头或书面陈述。具体而言，是投保人对 已知或应知的与风险和标的有关的实质性重要事实向保险人作口头或书面的申报（A。C正确）：保险人也应将对投保人利害相关的重要条款内容据实告知投保人（B正确）。 故本题选择ABC选项。 29', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '投资性资产的主要特征包括（），', '{"A": "可以用于维持生活品质", "B": "具有一定的流动性", "C": "长期资本升值和收益有一定的预见性", "D": "主要目的为长期的收益和资本利得", "E": "可用于近期支出和短期债务的偿还"}', '["B", "C", "D"]', '有一定的流动性：（3）长期资本升值和收益有一定的预见性（以便于对客户所需要的投资回报进行资产配置）：（4）出售套现的时候不会对客户的生活品质造成负面的影', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '对中小企业而言，要注重在投融资活动中的税收筹划，下列关于投融资税收筹划描述正确的有0。', '{"A": "在企业胜资方面，从债务方式选择上，主要有银行借款。企业发行债券和民间借贷三大类", "B": "银行借款的成本可在税前扣除", "C": "企业发行债券的利息可计入成本", "D": "利息支出作为费用支出，计算应纳税所得额时予以扣除", "E": "股利支付不作为费用，而在税后利润中支付"}', '["A", "B", "C", "D", "E"]', '在企业融资方面，从债务方式选择上，主要有银行借款，企业发行债券和民间借贷三大类。银行借款的成本主要是利息，可在税前扣除，所以具有节税功能。企业发行债券的 利息可计入成本，要尽量选择定期还本付息方式。使企业在债券有效期内不用付息。民间借贷具有很强的操作空间。企业可选择有利于自已的方案。理财规划人员要注意到股 权和债权的选择在税收方面的差异。根据现行财务制度和悦法规定，股利支付不作为费用支出，而在税后利润中支付：利息支出则是作为费用支出，在计算应纳税所得额时予 以扣除。因此，负债经营因利息计入成本具有节税作用，企业如具有偿债能力，应优先考虑适度负债经营。', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于保险金信托表述正确的是（）， ■E.人寿保险赔款免纳个人所得税', '{"A": "人寿保险的给付可防止财产变现带来的损失", "B": "人寿保验金不得用于偿还被保险人破产债务", "C": "人寿保险可实现遗的部分功能", "D": "投保时无须指定受益人"}', '["A", "B", "C", "E"]', '人寿保险功用特征包括：（1）人寿保险赔款免纳个人所得税。（2）人寿保险金不得用于偿还被保险人破产债务。债权人不能要求债务人变现还债：人寿保单未经被保险人书 面同意，不得转让或者质押。（3）人寿保险可实现遗瞩的部分功能，（4）人寿保验的给付可防止财产变现带来的损失，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '一般而言，在偿债能力指标分析中，有关已获利息倍数描述正确的是（）。', '{"A": "已获利息倍数不仅反映了获利能力而且反映了获利能力对偿还到期债务的保证程度", "B": "已获利息倍数是衡量企业长期偿债能力的指标", "C": "在进行已获利息倍数指标的同行业比较分析时，从稳健的角度出发以本企业该指标最低的年度数据作为分析依据", "D": "已获利息倍数等于税前利润与利息支出的比率"}', '["A", "B", "C", "E"]', '已获利息倍数=息税前利润/利息费用。已获利息倍数至少等于1才能说明企业可以负担利息支出。一般认为已获利息倍数为3时，比较恰当。如已获利息倍数为负数，说明企业 亏损。 30', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '在企业的财务指标中，关于速动比率的计算方法，正确的有（）。', '{"A": "速动比率=（流动资产存货)/流动负债", "B": "速动比率=流动资产/负债总额", "C": "速动比率=速动资产/负债总额", "D": "速动比率=流动资产/流动负债", "E": "速动比率=速动资产/流动负债"}', '["A", "E"]', '运用资产负债表可计算的比率有：（1）流动比率=流动资产/流动负债：(2）速动比率=速动资产/流动负债=（流动资产-存货）/流动负债：（3）资产负债率（又称负债比率） ■负债总额/资产总额。故本题选择AE选项，', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '为客户进行财富传承规划能够丰富金融机构和理财师的专业服务内容。提升专业形象，加强客户关系，具体表现包括（）。', '{"A": "增加客户粘性，沉淀长期金融资产", "B": "提高金融机构和理财师的知名度", "C": "提升专业形象", "D": "提高客户的忠诚度", "E": "维护客户关系，实现长期合作"}', '["A", "C", "E"]', '对提供财富传承规划的服务机构来说，为客户进行财富传承规划能够丰富金融机构和理财师的专业服务内容。提升专业形象，加强客户关系。具体表现在： （1）增加客户站 性，沉淀长期金融资产：（2）维护客户关系，实现长期合作：（3）提升专业形象。 31', 3);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '如果夏普比率大于0，说明在衡量期内基金的平均净值增长率（）无风险利率。', '{"A": "无法比较", "B": "高于", "C": ",低于", "D": "等于"}', '["B"]', '如果夏普比率为正值。说明在衡量期内基金的平均净值增长率超过了无风险利率。夏普比率越大，说明基金单位风险所获得的风险回报越高。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王某12月份取得工资收入8000元，年终奖24000元，不考虑五险一金，其12月份应数纳个人所得税为（）元，', '{"A": "440", "B": "810", "C": "345", "D": "250"}', '["B"]', '工资应纳税额：（8000-5000）×3%=90（元）：年终奖应纳税额的计算：24000-12=2000，税率3%，年终奖应纳税额=24000×3%=720（元），12月份应缴纳个人所得 税为90+720=810（元），', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于口头遇嘱，下列表述错误的是（）。', '{"A": "是指由遇人口头表述的遇帽", "B": "若速最人在危急情况过后能够用书面形式立遗喔，所立口头遗属仍有效", "C": "是一种特殊方式的遗眠，遗嘱人在危急情况下，可设口头遇喔", "D": "应当有两个以上见证人在场见证，才是有效的速瞩"}', '["B"]', '故B选项错误。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生计划在60岁退休时储备一笔资金，以确保自己一直到80岁时每月初都能拿到8000元的生活费，假设投资收益率能够达到5%/年，则他需要在退休的时候至少储备（）万元 的退休金。', '{"A": "121.22", "B": "140.12", "C": "138.89", "D": "121.73"}', '["D"]', '期初年金终值的计算，期限n=（80-60）×12，[=5%/12，年金C=8000，期初模式，求得PV=121.73，故本题选择D选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '某1年期零息债券，面值为100元，若到期收益率为4%，则该债券的合理发行价格为（），（答案取近似数值）', '{"A": "93.76元", "B": "100元", "D": "96.15元"}', '["D"]', '方法一：公式法，债券收益率计算公式如下：PV=FV/（1+i）^n，零息债券可以看成货币时间价值的现值和终值的情况，即发行价格为现值，债券面值为终值，即：为到期 利率=4%，零息债券可以看成货币时间价值的现值和终值的情况，即发行价格为现值，债券面值为终值，所以终值=100，期末模式，带入理财计算器，求得PV=96.15。故本 题选择D。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '某公司员工魏女士于2010年8月在某市参加工作，其所在单位按照国家规定为其缴纳基本养老保险。按照规定，她将于2040年8月年满55岁在该市退休。退休时其个人账户积累 总额为300000元，本人指数化月平均缴费工资为5500元/月，该市2039年职工平均工资为4000元/月。她退休后第一月所领取到的基本养老金是（）元。 （假设计发月数为 175）（答案取近似数值）', '{"A": "3139.29", "B": "2785.34", "C": "4178.26", "D": "1555.54"}', '["A"]', '以《国务院关于建立统一的企业职工基本养老保险制度的决定》为分界线。在《决定》实施后参加工作、缴费年限累计满15年的人员。退休后按月发给基本养老金，按照38号 文件的养老金计发公式。魏女土属于制度“新人”，退休后第一个月领取基本养老金■（统筹上一年度职工月平均工资+个人指数化月平均缴费工资）/2×缴费年限（含视同缴 费年限）×1%+个人账户储存额/计发月数=（4000+5500）/2×30×1%+300000/175=1425+1714.29=3139.29，故本题选择A选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '假定教育成本的年增长率为4%，而教育资金的年回报率为5%，则教育投资的实际报酬率为（。', '{"A": "1%", "B": "0.96%", "C": "0.8%", "D": "1.25%"}', '["B"]', '实际报酬率=【（1+名义收益率）/（1+通货能影胀率）1-1=［（1+5%）／（1+4%）1-1=0.96%，故本题选择B选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '孙小姐为某企业员工，2022年和2023年月平均工资分别是26000元和28000元，2022年当地职工月平均工资为8000元。2023年11月孙小姐个人缴纳的基本养老金是（）元。', '{"A": "2180", "B": "2240", "C": "1880", "D": "1920"}', '["D"]', '通常员工个人缴费基数是经过核定的上年度本人月平均工资，费率为8%，同时，缴费基数最高为统筹地职工上年度月平均工资的300%，最低为统筹地职工上年度月平均工资 的60%。所以孙小姐的缴费基数=8000×300%=24000元，孙小姐月缴养老金=养老保险缴费基数×个人缴费费率=24000×8%=1920（元）。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '选择基金产品用于教育投资的优点不包括（）。', '{"A": "本金安全", "B": "定期定额强制积累", "C": "投资多样化和灵活性好", "D": "买卖灵活方便"}', '["A"]', '基金产品作为教育投资的工具，有如下优势： （1）品种选择多：基金一股分为货币型、股票型、债券型、平衡型等多种，能够满足不同类型的客户育投资规划需求； （3）灵活方便：客户可以根据自身教育规划需求选择投资基金的品种。金额和时间。对大多数客户来说基金投资没有上限。一次投资几千元或几万元都可以，每次追加投资最 少要求1000元基至更低（定期定投下限更低）：开户后客户可以到金融机构网点或网上选择投资或转换基金： （4）基金定期定额投资：由于教育规划刚性需求的属性。资金的积累时间长，且需要增值与稳健兼题。使用定期定额投资的方式准备教育经费是一种常用的选择。教育规划作 为一个长期的理财计划，定期定额投资可以在长年累月下积少成多，并且降低原有的风险。另外。基金定额定投具有投资标的价格低时购买数量加大、价格高时购买数量减少 的自动调整功能，无论市场价格如问变化，总能获得一个比较低的平均持仓成本，一定程度上平摊了建仓的成本，降低了投资的风险，而选项“本金安全”不涉及。故本题答 案选“本金安全”，', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户忠诚度是建立在0基础之上的。因此需提供高品质的产品和服务来提升客户体验。', '{"A": "客户的盈利率", "B": "客户价值", "C": "客户资源规模", "D": "睿户的满意度"}', '["D"]', '客户满意是客户忠诚的前提和基础。显而易见，如果客户在很行网点或与理财师打交道过程中的体验不佳，就不可能成为忠诚客户。故本题答案选“客户的满意度”', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '孙娟预计其儿子5年后上大学，届时需学费30万元。为筹集学费孙娟每年年未投资3万元到年投资回报率7%的平衡基金，则5年后（），（答案取近似值）', '{"A": "需要额外支付17.25万元", "B": "需要额外支付12.75万元", "C": "无需额外支付学费", "D": "会获得30万元的本息"}', '["B"]', '根据题意：计算5年后孙娟的投资收益总额：现值PV=0，“每年年未投资3万元”，为期未年金，PMT=-3，期限n=5，利率r=7%，代入到理财计算器中，求得终值 FV=17.25，所以5年后孙娟的投资收益总额为17.25万元，需要额外支付30-17.25=12.75万元。故本题答案选“需要额外支付12.75万元。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '根据《民法典》的相关规定，下列关于法定继承的说法正确的是（）。', '{"A": "在适用效力上，法定继承的效力优于遗瞩继承", "B": "在法定继承中，继承人参加继承的顺序，是由法律直接规定的", "C": "法定继承直接体现被继承人的意志", "D": "法定维承是以法律关系为基础的"}', '["B"]', '法定继承中法定继承人是基于一定的身份关系而确定的，法定维承是以身份关系为基础的。故“法定继承是以法律关系为基础的”错误；在适用效力上，法定继承的效力低于 遗崛继承，遗嘱继承的效力优于法定继承。故“在适用效力上，法定继承的效力优于遇嘱继承”错误：在法定继承中，可参加继承的继承人。继承人参加继承的顺序，继承人 应继承的遗产份额以及速产的分配原则，都是由法律直接规定的。因而法定继承并不直接体现被维承人的意志，仅是法律依推定的被继承人的意思将其速产由其法定继承人继 承，故“法定继承直接体现被继承人的意志”错误。故本题答案选“在法定继承中，继承人参加继承的顺序，是由法律直接规定的”，', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于人寿保险在财富传承中的作用，下列表述错误的是（）。', '{"A": "通过合理安排，可以让保险给付金及保单里的现金价值不被第三方随意侵占", "B": "人寿保险的给付可防止财产变现带来的损失", "C": "合理节税是现阶段高资产人群投保高额保单的驱动因素之一", "D": "人寿保险单不指定受益人也能保证被保险人离世时家庭内部没有财产纷争"}', '["D"]', '人寿保验的功用特征：（1）合理节税是现阶段高净值人群投保高额保单的驱动因素之一。C选项正确。（2）保单可以指定多名受益人，同时还可以指定受益份额和受益顺 序。即便被保险人离世时未留下遗哦，也可在一定程度上随免家庭内部的纷争。选项为“没有财产纷争”说法错误，D选项错误，（3）人寿保险的给付可防止财产变现带来的 损失。B选项正确。（4）被保险人身故后，在指定受益人的条件下，寿险的保险金直接归受益人所有，不属于被保险人的遗产，受益人无须清偿被保险人生前所欠的税款和债 务，即通过合理安排为投保人及受益人增添了一层保护，从而让保额及保单里的现金价值不能被第三方随意侵占。A选项正确，故本题选择D选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户关系管理的首要环节是）：客户关系管理的终极目标是（）的最大化。', '{"A": "加强客户维护管理：客户资产", "B": "制定和实施营销策略：客户资源", "C": "明确客户策路：客户终身价值"}', '["C"]', '明确客户策略是银行实施客户关系营销的基础，是客户关系管理的首要环节：客户关系管理的终极目标是客户终身价值的最大化。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在有效市场的三种类型中，）市场中通过内幕交易无法获得经济利润。', '{"A": "半强式有效市场", "B": "就式有效市场", "C": "半翼式有效市场", "D": "强式有效市场"}', '["D"]', '强式有效市场假说指所有的信息都反映在股票价格中。这些信息不仅包括公开信息，还包括各种私人信息，即内幕消息。强式有效市场意味着所有的分析都无法击败市场。因 为只要有人得知了内幕消息，他就会立即行动，从而使证券价格迅违达到该内幕消息所反映的合理水平，这样，其他再获得该内幕消息的人就无法从中获利。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列指标可用于分析企业偿债能力的是（）。', '{"A": "应收账款固转次数", "B": "资产负债率", "C": "基本获利率", "D": "净资产利润率"}', '["B"]', '偿债能力分析是指企业偿还到期债务的能力。通过以下几项偿债能力分析指标，一方面可以看出企业偿还长期、短期债务的能力和存在的风险，另一方面也能看出企业运用现 金、借款的能力，偿债能力分析指标主要有以下几项：①流动比率。②速动比率。③现金比率，③资产负债率，③有形资本负债率。③产权比率，①已获利息倍数。故本题选 择B选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '赵兰特别喜欢自己活泼可爱的小怪女，打算在她12岁生日时为其侄女投保一份定额寿险，没想到保险公司拒保，其拒保的理由是（），', '{"A": "赵兰对其任女不具有保险利益", "B": "赵兰违反了损失补偿原则", "C": "赵兰违反了最大诚信原则", "D": "赵兰侄女年龄小"}', '["A"]', '保险的基本原则之一是保险利益原则。投保人对下列人员具有保险利益：（1)本人：(2)配偶。子女、父母：(3)前项以外与投保人有抚养、赚养或者扶养关系的家庭其他成员 近亲属：（4)与投保人有劳动关系的劳动者。除前款规定外。被保险人同意投保人为其订立合同的，视为投保人对被保险人具有保险利益。赵兰对自己的侄女不具有保险利益， 所以订立合同时，合同无效。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于企业财务管理指标的描述中，错误的是（）：', '{"A": "应收账款周转天数越短，说明企业应收账款的变现能力越强", "B": "流动比率大于1，说明流动负债大于流动资产", "C": "净资产利润率越高，说明企业全部资产的盈利能力越强", "D": "若已获得利息倍数为负数，说明企业亏损"}', '["B"]', '（1）应收账款周转天数=应收账款平均余额×360/企业销售收入净额，所以应收账款周转天数越短，说明企业应收账款的变现能力越强； (2）流动比率=流动资产/流动负债，流动比率大于1，说明流动资产大于流动负债，企业短期偿债能力越强。所以选项“流动比率大于1，说明流动负债大于流动资产”说法 错误： 盈利能力越强： （4）已获利息倍数=息税前利润/利息费用。息税前利润=利润总额+利息费用。分子中的利息不包括固定资产中的利息支出，而分母中的费用包括财务费用和固定资产中的利 息支出。已获利息倍数至少等于1才能说明企业可以负担利息支出，一股认为已获利息倍数为3时，比较恰当。如已获利息倍数为负数，说明企业亏损。故本题答案选“流动比 率大于1。说明流动负债大于流动资产', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于资本资产定价模型中的β系数，下列描述正确的是（）： 考前', '{"A": "β系数的绝对值越小，则证券或证券组合的非系统性风险越大", "B": "β系数的绝对值越大，则证券或证券组合的收益水平对于市场平均收益水平的变动的敏感性越大90", "C": "β系数越小，则证券或证券组合的系统性风险越大"}', '["B"]', 'β系数是一种评估证券系统性风险的工具，用以度量一种证券或一个投资证券组合相对总体市场的波动性。β系数越小，则证券或证券组合的系统性风险越小；风险包括系统风 险和非系统风险，贝塔系数只反映证券或证券组合的期望收益与其所含的系统风险的关系。β绝对值越大，显示其收益变化幅度相对于大盘的变化幅度越大。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '理财师对客户的理财目标进行综合评估和分析时，可以使用“全生涯模拟仿真法”，这种方法最主要的目的是模拟（）。', '{"A": "客户的投资报酬率", "B": "真实通货膨胀率", "C": "客户家庭的投资负债变化", "D": "客户家庭未来每年的现金流"}', '["D"]', '酬率的变动情况；这种模拟方法通常会模拟客户人生不同阶段的现金流，也被叫作“全生注模拟仿真法”，故本题选择D选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于处理客户投诉的要点。下列表述错误的是（）。', '{"A": "首先解决客户的情绪问题，再解决客户的投诉问题", "B": "迅速采取行动", "C": "学会倾诉，善于“少听多说”", "D": "换位思考"}', '["C"]', '关于客户投诉处理的方法和技巧有许多，在具体实践中理财师应该做好以下三方面工作。（1）行动迅速。面对投诉的客户或客户的抱怨，金触机构和理财师的及时响应。接触 项正确），（3）客户投诉处理方法应该标准化、流程化，而且要告知客户，这样客户遇到问题愿意投诉，客户的投诉也能够很快得到响应，并且客户知道投诉处理的责任人或 联系方式和流程后，也会减少不必要的焦虑和误解（D选项正确），故本题选择C选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于投资性资产特征的是0）。', '{"A": "长期资本升值和收益有一定的预见性", "B": "具有一定的流动性", "C": "增值性资产量然有一定的资本增值但不产生收入", "D": "主要目的是为长期的收益和资本利润"}', '["C"]', '投资性资产指能够产生利息收入或资本利得的资产中，扣除自用性资产后的资产，都属于投资性资产，其主要特征及其运用包括以下几个方面： （1）主要目的为长期的收益和资本利得： (2）具有一定的流动性： （3）长期资本升值和收益有一定的预见性（以便对客户所需的投资回报进行资产配置），不包括“增值性资产量然有一定的资本增值但不产生收入”，故本题答案选该项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于设立保险金信托的流程，下列排序正确的是（）。', '{"A": "（1）签订保险合同（2）尽职查（3）信托财产管理（4）保险金信托成立", "B": "（1）签订保险合同（2）尽职调查（3）保险金信托成立（4）信托财产管理", "C": "（1）尽职调查（2）签订保险合同（3）信托财产管理（4）保险金信托成立", "D": "（1）尽职调查（2）签订保验合同（3）保险金信托成立（4）信托财产管理"}', '["B"]', '客户一般可以按照以下步豫设立保险金信托，实现家族财富的管理和传承。1.签订保险合同：2.尽职调查：3.保险金信托成立：4.信托财产管理。故本题选择B选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王女士在50岁时获得10万元现金收入，她用这笔现金一次性购买了一份年金保险，以便在60岁后按月领取年金收入，下列说法错误的是（），', '{"A": "该年金的年金期间是1个月", "B": "该年金的给付期间是20年", "C": "该年金的类型是盈缴延期年金", "D": "该年金的累积期间是10年"}', '["B"]', '年金保险是指以生存为给付保险金条件。并按约定的时间间隔分期给付生存保险金的人身保险。年金期间是相邻两次定期给付的时间间隔。王女士每月都可获领取年金收入， 所以年金期间是1个月，A选项正确。累积期间是投保人开始投保到保险人开始给付的期间，即从王女士50岁投保到王女士60岁保险公司开始给付，累积期间是10年，D选项正 确。给付期间是保险人提供给付的期间。是从王女士60岁以后至终身，B选项错误。王女士一次性缴纳保费，10年后才开始领取年金，所以是查缴延期年金产品，C选项正确。 故本题选择B选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '李先生2021年3月取得劳务报酬收入3000元，稳酬收入2000元：5月取得劳务报酬收入30000元，特许权使用费收入2000元。下列关于其在这两个月预扣预缴个人所得税的说法 中，错误的是（， 考前纸', '{"A": "稿酬收入2000元的所得税预扣预缴税额为168元", "B": "劳务报酬收入30000元的所得税预扣顶缴税额为7200元", "C": "劳务报酬收入3000元的所得税预扣预缴税额为440元"}', '["B"]', '劳务报酬所得、稳酬所得和特许权使用费所得，每次收入不超过4000元的，减除费用800元，每次收入超过4000元以上的，减除20%的费用。并且稿酬所得按减除费用后的 70%计算收入额。（1）劳务报酬收入30000元预扣预缴应纳税所得额=30000×（1-20%）×30%-2000=5200（元）（B选项错误）：（2）劳务报酬收入3000元预扣预缴应 纳税所得额=（3000-800）×20%=440（元）（C选项正确）：（3）稿酬收入2000元预扣预缴应纳税所得额=（2000-800）×70%×20%=168（元）（A选项正确）； （4）特许权使用费收入2000元预扣预缴应纳脱所得额=（2000-800）×20%=240（元），故本题选择B选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '信托委托人将其财产所有权委托给受托人，便受托人按照信托协议的约定，保障受益人教育费用支出的产品是（），', '{"A": "养老信托", "B": "投资信托", "C": "教育金信托", "D": "资产信托"}', '["C"]', '教育金信托一股为要托人（如家长)根据理财规划的目标，将资产所有权委托给受托人（如信托机构).受托人按照信托协议的约定为受益人(如子女或配绸）的利益，管理、分配信托 资产的行为，题干中说明是教育费用。故本题选择C选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '李某购买中国体育彩票中奖9000元，需要交纳的个人所得税为（）元', '{"A": "896", "B": "1280", "C": "O", "D": "1600"}', '["C"]', '偶然所得是指个人取得的所得是非经常性的，属于各种机遇性所得，包括得奖、中奖、中彩以及其他偶然性质的所得（含奖金、实物和有价证券），个人购买福利彩票、体育 彩票，一次中奖收入在1万元以下的免征个人所得税，超过1万元全额计征，故需要交纳的个人所得税为0元，本题选择C选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '基本养老金替代率的含义是（）。 考前', '{"A": "养老金领取水平与同年度消费水平之间的比率", "B": "养老金领取水平与同年度在职职工的工资收入水平之间的比率", "C": "同年度消费水平与养老金领取水平之间的比率", "D": "同年度在职职工的工资收入水平与养老金领取水平之间的比率"}', '["B"]', '养老金替代率是国际通用的衡量劳动者退休前后养老保障水平差异的基本标准，通常以“某年度新退休人员的养老金领取水平与同年度在职职工的工资收入水平之间的比率” 获得。从国际经验上看，养老金替代率大于70%即可维持退休前的生活水平：如果养老金替代率达到60%~70%,即可维持基本生活水平：如果养老金替代率低于50%，则生活 水平会较之前有大幅下降。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于家度资产负债表的描述，错误的是（），', '{"A": "活期存款。股票、债券、基金等变现较快，属于流动性资产", "B": "当负债相对于所有者权益来说过高时，个人容易出现财务危机", "C": "分析客户的资产负债表是进行财务规划的基础", "D": "净资产就是资产减去负债"}', '["A"]', '普通家庭的资产通常被分为三大类：自用性资产、流动性资产和投资性资产。在个人资产负债表中，流动资产主要有现金、存款和货币市场基金等。股票和债券属于投资资 产。所以A选项说法错误。分析客户的资产负债表是进行财务规划的基础，资产负债表包括资产、负债、净资产三部分内容，总资产减去总负债即净资产，C、D选项正确。当 负债相对于所有者权益来说过高时，个人容易出现财务危机。B选项正确。故本题选择A选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，属于退休规划核心内容的有（），（1）养老金（2）老年医疗（3）储蓄（4）老年住房（5）养生服务 (4) 、 (5) (2) 、 (4) (2) 、 (3) (3) 、 (4)', '{"A": "(2) 、", "B": "(1) 、", "C": "(1) .", "D": "(1)"}', '["B"]', '退休规划以养老金。老年医疗、老年住房为核心内容。故本题选择B选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '老陈计划在60岁退休的时候储备一笔资金，以确保自己一直到85岁时每个月初都能拿到3000元的生活费，如果他的收益率能够达到4%，则他需要在退休的时候储备）元的 退休基金。', '{"A": "572626.3", "B": "495065.5", "C": "568357.4", "D": "496715.7"}', '["A"]', '根据题干中“每个月初都能拿到3000元的生活费”求“他需要在退休的时候储备多少退休基金”可转化成已知期初年金求现值。题目中条件可知，年金PMT=3000，利率 r=4%+12，期数n=25×12=300，该生活费是月初拿到，所以是期初支付。将数值代入到理财计算器中，如图所示： 理财计算器', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在税务规划中，延期纳税的优点不包括（）。', '{"A": "减少税种降低税率", "B": "节省利息支出", "C": "降低了实际纳税额", "D": "有利于资金周转"}', '["A"]', '延期纳税的好处有：有利于资金周转。节省利息支出，以及由于通货膨胀的影响，延期以后缴纳的税款必定下降，从而降低了实际纳税额。不包括“减少税种降低税率”，故 本既答案选该项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，关于个人所得税大病医疗专项附加扣除，说法错误的是（）。', '{"A": "大病医疗扣除，设定扣除金额上限，采取限额内据实扣除方式", "B": "未成年子女发生的医药费用支出可以选择由其父母一方扣除", "C": "纳税人发生的医药费用支出可以选择由本人或其配偶一方扣除", "D": "纳税人父母的大病医疗支出可以在纳税人税前扣除"}', '["D"]', '对大病医疗扣除设定扣除金额上限，采取限额内据实扣除方式，在次年3月1日至6月30日汇算清缴时扣除。所以选项“大病医疗扣除，设定扣除金额上限，采取限额内据实扣 除方式”正确： 用支出可以选择由本人或其配偶一方扣除”正确： 目前未将纳税人的父母纳入大病医疗扣除范围，所以选项“纳税人父母的大病医疗支出可以在纳税人税前扣除”错误，故本题答案选“纳税人父母的大病医疗支出可以在纳税 人税前扣除”。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在行业生命周期中。成长期的特点是（）：', '{"A": "行业利润率较低，市场增长率较高", "B": "行业生产能力接近饱和", "C": "市场增长率不高，行业进入壁垒很高", "D": "需求高速增长，技术渐超定型"}', '["D"]', '成长期，这一时期的市场增长率很高，需求高速增长，技术新趋定型（D选项正确），行业特点、行业竞争状况及用户特点已比较明朗，企业进入壁垒提高，产品品种及竞争 者数量增多，这个时期的主要特征可以概括如下：产品已经为大众所认识。但需要不断进行产品的更新换代：市场需求逐步扩大；公司销售收入迅速增长，成长期初期企业仍 处于亏损或微利状态。然后利润增长很快：市场风险很大；对投资的需求很强烈；投资优势企业常常获得较理想的回报。A选项是幼稚期的特点，B、C选项是成熟期的特点， 故本题选择D选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '纳税人发生的下列行为中，可以从销项税额中抵扣的是（）。', '{"A": "将购买的货物用于非增值税应税项目", "B": "将购买的货物用于集体福利或个人消费", "C": "正常损失的购进货物及相关的应税劳务", "D": "随同货物运费支付的保险费"}', '["C"]', '下列项目的进项税额不得从销项税额中抵扣： （1）用于非增值税应税项目、免征增值税项目、集体福利或者个人消费的购进货物或者应税劳务。所以选项“用于集体福利或个人消费”和“用于非增值税应税项目”不能抵 扣: （2）非正常损失的购进货物及相关的应税劳务： （3）非正常损失的在产品、产成品所耗用的购进货物或者应税劳务： （4）国务院财政、税务主管部门规定的纳税人自用消费品： （5）本条第（1）项至第（4）项规定的货物的运输费用和销售免税货物的运输费用。所以选项“随同货物运费支付的保险费”不能抵扣。所以不包括选项“正常损失的购进 货物及相关的应税劳务”，故本题答案选“正常损失的购进货物及相关的应税劳务”，', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '综合理财规划服务的主要内容不包括（），', '{"A": "制定综合理财规划方案", "B": "理财规划方案的执行", "C": "评估、选择、确立理财目标", "D": "研究客户性格特征"}', '["D"]', '综合理财规划服务的主要内容如下： 第一，了解和分析家庭财务状况（现在身处何方）： 第二，评估、选择和确立理财目标（要到邮里去，能不能去成？选择、取舍、备选方案，后续跟踪及服务调整）： 第三，制订综合理财规划方案（如何去）： 第四，执行理财规划方案（计划执行的细节和注意事项等），不包括“研究客户性格特征”，故本题答案选“研究客户性格特征”，', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '反映企业资产运营能力的指标是（）。', '{"A": "速动比率和产权比率", "B": "应收账款周转率和存货周转率", "C": "存货周转率和产权比率", "D": "应收账款周转率和速动比率"}', '["B"]', '资产运营能力指企业资产及其组成要素在生产过程中的运营能力。主要包括应收账款周转率和存货周转率两大类财务指标。故本题选择B选项。 10', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '此她向理财师就子女教育规划方而的问题进行了咨询。 如果郑女土的女儿还有四年上大学，目前大学及硕土费用为12万元，以5%的学费上涨率计算，到郑女士的女儿上大学时，其大学和硕土期间共需（0元的学费。', '{"A": "132670.25", "B": "145860.75", "C": "128794.15", "D": "128632.75"}', '["B"]', '到郑女士的女儿上大学时，其大学和硕土期间需要的学费为12×(1+5%)^4=14.586075万元。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '我国传统上家长对子女的教育就比较重视。但随着教育费用越来越高，为了保证子女的上学费用，十分有必要做好子女教育规划。客户郑女士有一个在读初中三年级的女儿，就 此她向理财师就子女教育规划方面的问题进行了咨询。 如果郑女士每月初固定拿出一笔资金进行定投，则郑女士每月需投（）元，方可弥补教育金缺口。', '{"A": "2179.54", "B": "1925.31", "C": "1967.12", "D": "2218"}', '["D"]', '资金缺口为145860.75-25249.54=120611.21元，本题转换为已知终值求年金。r=6%/12，n=48，PV=0，FV=120611.21，代入到理财计算器中，求得PMT=-2218.', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '落先生持有200万股甲公司的股票，目前市值为2000万元，其购入成本为200万元，按照上市时的承诺，落先生三个月后可以减持100万股。剩余100万股必须至少再持有5年，此外，落先生目前税前 年收入为120万元，包括工资20万元和公司股东分红100万元，此外还有现金储蓄200万元。洛先生属于保守型的投资者，他希望投资的税后收益率在扣除通货能胀后能达到3%，假设通货能胀率为 2.9%，洛先生请金融理财师兰小姐为他做理财规划。兰小姐为洛先生提出了如下4个投资组合： 预期收 配置权置 益率 国债 59% 096 3% 10% 0% 债券基金 30% 20% 20% 6% 10% 中小股基金 10% 20% 30% 25% 30% 8% 20% 25% 蓝筹股基金 40% 45% QDII基金 20% 20% 15% 796 15% 总和 100% 100% 100% 100% 配置预计总收益 7.55 7.75 6.8 8.15 综合期望标准差 8.0 8.5 9.0 9.3 (%) 根据审慎投资的原则，兰小姐提供的下列建议中最不合理的是（）。', '{"A": "甲公司的成长性很好，不要做任何减持，还应该继续追加投资", "B": "减持股票的资金投入到防御性行业的股票", "C": "减持甲公司的股票以达到分敢风险的效果", "D": "200万元的储蓄太多，应该做投资理财"}', '["A"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '潜先生持有200万股甲公司的股票，目前市值为2000万元，其购入成本为200万元，按照上市时的承诺，混先生三个月后可以减持100万股，剩余100万股必须至少再持有5年。此外。落先生目前税前 年收入为120万元，包括工资20万元和公司股东分红100万元，此外还有现金储富200万元。洛先生属于保守型的投资者，他希望投资的税后收益率在扣除通货影胀后能达到3%，假设通货影胀率为 2.9%，落先生请金融理财师兰小姐为他做理财规划，兰小姐为落先生提出了如下4个投资组合： 预期收 配置权置 益率 国债 10% 0% 396 0% 债券基金 6% 30% 20% 20% 10% 中小股基金 10% 20% 30% 25% 30% 蓝筹股基金 896 20% 25% 40% 459% QDI基金 20% 20% 15% 7% 15% 总和 100% 100% 100% 100% 配置预计总收益 7.55 7.75 6.8 8.15 (%) 综合期望标准差 8.0 8.5 9.0 9.3 对于兰小姐的投资组合建议，从夏普比率角度来看最优的配置方案是（），', '{"A": "配置A", "C": "配置C", "D": "配置B"}', '["B"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '洛先生持有200万股甲公司的股票，目前市值为2000万元，其购入成本为200万元，按照上市时的承诺，落先生三个月后可以减持100万股，剩余100万股必须至少再持有5年，此外，落先生目前税前 年收入为120万元，包括工资20万元和公司股东分红100万元，此外还有现金储蓄200万元。洛先生属于保守型的投资者，他希望投资的税后收益率在扣除通货影胀后能达到3%，假设通货影胀率为 2.9%，洛先生请金融理财师兰小姐为他做理财规划，兰小姐为落先生提出了如下4个投资组合： 预期收 配置权置 益率 国债 10% 3% 5% 0% 0% 债券基金 30% 20% 20% 6% 10% 中小股基金 10% 30% 20% 25% 30% 896 25% 40% 蓝筹股基金 20% 45% QDI基金 7% 20% 20% 15% 15% 100% 总和 100% 100% 100% 配置预计总收益 7.55 6.8 7.75 8.15 (%) 综合期望标准差 8.0 8.5 9.0 9.3 (%) 现代证券组合管理理论的开端是（）： 您的案：', '{"A": "均值方差模型", "B": "资本资产定价模型（CAPM）", "C": "套利定价理论（APT)", "D": "三因子模型"}', '["A"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2021年末，吕先生家庭有活期存款2万元，定期存款50万元，自住房产一套价值300万元，投资性房产一套，剩余房货120万元。吕先生当年家庭年收入情况如下：税后工资收入30万元，理财收入3万 元，支出情况如下：每月房贷支出5000元，每月生活支出8000元，每年学费支出1万元，每年献游支出1万元。根据以上信息。回答下列问题： 昌先生家庭的理财收入占比约为（），1分》（答案取近似数值）', '{"A": "9%", "B": "16%", "C": "20%", "D": "15%"}', '["A"]', '理财收入3万元，家庭年收入=30+3=33万，3/33=9%，故本题选择A造项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2021年末，吕先生家庭有活期存款2万元，定期存款50万元，自住房产一套价值300万元，投资性房产一套，剩余房贷120万元。吕先生当年家庭年收入情况如下：税后工资收入 30万元，理财收入3万元，支出情况如下：每月房贷支出5000元，每月生活支出8000元，每年学费支出1万元，每年旅游支出1万元。根居以上信息，回答下列问题： 昌先生家庭的财务自由度约为（）。（答案取近似数值）', '{"A": "89%", "B": "25%", "C": "31%", "D": "17%"}', '["C"]', '财务自由度=投资理财收入/生活支出=30000/（8000×12）=31.25%，故本题选择C选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2021年未，吕先生家庭有活期存款2万元，定期存款50万元，自住房产一套价值300万元，投资性房产一套，剩余房贷120万元。吕先生当年家庭年收入情况如下：税后工资收入 30万元，理财收入3万元。支出情况如下：每月房贷支出5000元，每月生活支出8000元，每年学费支出1万元，每年旅游支出1万元。根据以上信息，回答下列问题： 一般而言，昌先生家庭合理的紧急预备金额度较适合的为）万元。', '{"A": "14.8", "B": "7.8", "C": "13.9", "D": "3.8"}', '["B"]', '理财师通常会要求客户建立紧急预备金账户，并保持较高的流动性；紧急预备金额度通常为家庭月支出的3-6倍为宜，以抵御家庭收入突然中断或奕发性大笔支出的风险。家庭 月支出=5000+8000+10000/12+10000/12=14666.66元，14666.66×3=43,999.98，14666.66×6=87,999.96元，故7.8万元最符合。 14', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2021年末，吕先生家庭有活期存款2万元，定期存款50万元，自住房产一套价值300万元，投资性房产一套，剩余房贷120万元。吕先生当年家庭年收入情况如下：税后工资收入 30万元，理财收入3万元。支出情况如下：每月房贷支出5000元，每月生活支出8000元，每年学费支出1万元，每年旅游支出1万元。根据以上信息，回答下列问题： 吕先生家庭的2021年结余为（）万元。', '{"A": "26.4", "B": "16.4", "C": "15.4", "D": "25"}', '["C"]', '结余=300000+30000-5000×12-8000×12-10000-10000=154000元，故本题选择C选项，', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2024年1月，王先生计划通过银行柜台购买某新发行的25年期债券。该债券票面利率为3.5%，每年提前还本4%，王先生认购债券面额为100万元， 根据以上材料。回答下列问题。 （1）同时在交易所、银行间、银行柜台市场流通的金融产品不包括（）。', '{"A": "股票", "B": "国开债", "C": "国债", "D": "地方政府债"}', '["A"]', '近年来，随着我国柜台市场的发展。银行柜台代理的债券日趋多元化，国债、地方债、国开债、政策性金融债等债券已可通过银行柜台(或手机客户端)进行投资。故本题选择A 选项。 15', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2024年1月，王先生计划通过银行柜台购买某新发行的25年期债券。该债券票面利率为3.5%，每年提前还本4%，王先生认购债券面额为100万元， 根据以上材料，回答下列问题。 （2）王先生通过银行柜台购买的债券最可能是（）。', '{"A": "选项：这类债券是由股份制银行发行的，用于筹集资金。它们的期限可以相对较长，利率通常取决于市场条件和银行的信用评级。由于它们是银行发行的，所以通常有一", "B": "国债", "C": "企业债", "D": "中期票据"}', '["A"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2024年1月，王先生计划通过银行柜台购买某新发行的25年期债券。该债券票而利率为3.5%，每年提前还本4%，王先生认购债券而额为100万元。 根据以上材料，回答下列问题。 (3）若王先生当日买入该债券的到期收益率为3%，买入成本为（）万元。（答案取近似数值）（2分）', '{"A": "115.55", "B": "99.85", "C": "105.05"}', '["C"]', 'n=25，1=3%，FV=100，C=100×3.5%=3.5，期末模式，求得PV=108.7，取近似值，故本题选择C选项。还本，是指购买债券后，购买方固定还本付息，一般估值或估价公 式里是用不到这个条件。或者也可以这样考虑：到期收益率小于票面利率，所以是溢价发行，也就是说成本价高于票面价。但是利率差距较小，所以最接近的也是C选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2024年1月，王先生计划通过银行柜台购买某新发行的25年期债券。该债券票面利率为3.5%，每年提前还本4%，王先生认购债券面额为100万元。 根据以上材料，回答下列问题。 （4）若王先生当日买入该债券的到期收益率为4%，买入成本为（）万元。（答案取近似数值）（1分）', '{"A": "85.35", "B": "95.31", "C": "102.95", "D": "105.05"}', '["B"]', 'n=25，I=4%，FV=100.C=100×3.5%=3.5，期末模式，求得PV=92.19。取近似值。故本题选择B选项。 16', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2024年1月，王先生计划通过银行柜台购买草新发行的25年期债券。该债券票面利率为3.5%，每年提前还本4%，王先生认购债券面额为100万元。 根据以上材料，回答下列问题。 （5）未来某一时点，因某时点性因素，王先生计划提前卖出该期债券，最不可能导致王先生做出该投资决策的原因是（）。', '{"A": "选项：这通常意味着政府需要从市场上筹集资金以满足支出需求，可能会导致市场利率上升。债券价格下跌。从王先生作为债券持有者的角度来看，可以选择卖出债券。B选", "B": "银行月末、季末为应对MPA考核大量融入资金", "C": "大型节假日之前，企事业单位、储户大幅提取现金", "D": "即将进入集中缴税期，大量财政税金入库"}', '["D"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生35岁，年工资收入30万元，要子32岁，年工资收入15万元。家庭每月生活支出1万元，现有房贷余额80万元，剩余还款期限20年，两人育有一个5岁的女儿。张先生希望 通过保险规划,保障家庭在面临意外，疾病等风险时的经济稳定。根据以上材料。回答下列问题。 从家庭经济责任角度，张先生本人最急需配置的保险是（）。', '{"A": "终身寿险：保障期限为终身，兼具储善和保障功能。但保费较高，且张先生当前更需以较低成本覆盖家庭责任期内的风险，而非终身保障或储蓄需求，优先级较低。B定期寿", "B": ",定期寿险", "C": "教育金保险", "D": "养老保验"}', '["B"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生35岁，年工资收入30万元，要子32岁，年工资收入15万元，家应每月生活支出1万元，现有房贷余额80万元，利余还款期限20年，两人育有一个5岁的女儿。张先生希望 通过保险规划保障家庭在面临意外，疾病等风险时的经济稳定。根据以上材料，回答下列问题。 张先生考虑自己购买重疾险，以下关于重疾险的说法正确的是0。', '{"A": "重疾险的赔付可用于弥补惠病期间的收入损失", "B": "重疾险确诊即赔，无需考虑疾病程度", "C": "重疾险保障的疾病种类越多越好", "D": "重疾险的保费与被保险人年龄无关"}', '["A"]', '选项A分析：重疾险的核心功能之一是提供“收入损失补偿”。被保险人确诊约定重疾后，保险公司会一次性给付保险金，这笔资金可自由支配。既可以用于支付医疗费、康复 费，也能弥补患病期间无法工作导致的收入中断，保障家庭经济稳定。因此，该说法正确。选项B分析：重疾险并非“确诊即赔”，赔付条件需根据具体疾病和条款约定，并非 所有情况都“确诊即赔”。该说法错误。选项C分析：重疾险的保障效果并非取决于疾病种类多少。行业已规定28种高发重疾（占理赔率95%以上）必须纳入重疾险保障范 围，额外增加的罕见疾病对普通消费者实际意义不大，反而可能推高保费。选择重疾险时，应优先关注高发重疾、轻症/中症的覆盖完整性及赔付比例。而非单纯追求“种类 多”，该说法错误。选项D分析：重疾险保费与被保险人年龄密切相关。年龄越大，患病风险越高，保费通常越高：且年轻时投保可锁定较低费率，避免因年龄增长或键康变 化导致投保困难或保费大幅上涨。因此，保费与年龄直接相关，该说法错误。综上，正确答案是A。 17', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生35岁，年工资收入30万元，妻子32岁，年工资收入15万元。家庭每月生活支出1万元，现有房贷余额80万元，剩余还款期限20年，两人育有一个5岁的女儿，张先生希望 通过保险规划.保障家庭在面临意外、疾病等风险时的经济稳定。根据以上材料，回答下列问题。 张先生妻子所在学校为其购买了团体意外险，张先生妻子（）。', '{"A": "无需再购买个人意外险", "B": "购买个人意外险会被保险公司拒绝", "C": "只能购买与学校团体意外险相同保额的个人意外险", "D": "可根据自身需求补充购买个人意外险"}', '["D"]', '团体意外险是学校作为投保人给员工购买的福利性保险，通常保额和保障范围较为基础，且保障期限与劳动关系挂钩（如离职后保障可能终止），个人意外险则是个人自主购 买的保险，可根据自身需求选择保额。保障内容（如意外医疗、伤残、身故等）和保障期限。两者在保障上并不冲突，也无投保限制。A错误：团体意外险的保障可能不足，例 据自身对意外风险的保障需求，额外购买个人意外险以弥补团体意外险的不足，两者赔付可登加（如身故/伤残保额累加，意外医疗费用在保额内按约定报销），故本题答案选 择D选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生35岁，年工资收入30万元，妻子32岁，年工资收入15万元。家庭每月生活支出1万元，现有房贷余额80万元，剩余还款期限20年，两人育有一个5岁的女儿。张先生帮望 通过保险规划保障家庭在面临意外、疾病等风险时的经济稳定。根据以上材料，回答下列问题。 以下适用于张先生家庭资产传承规划的产品为（）。 ●A医疗险', '{"B": "定期寿险", "C": "终身寿险", "D": "意外险"}', '["C"]', '资产传承规划的核心是将个人或家庭资产在身故后有序传递给受益人，同时可能涉步及资产保值、规避继承纠纷、税务优化等目标。这类规划需要长期稳定的保障，且保额或现 金价值在被保险人身故时能确定给付。A医疗险：主要用于报销医疗费用，属于消费型短期保障，无身故给付功能，与资产传承无关，B定期寿险：提供固定期限内的身故保 障，保费低、杠杆高，但保障期限到期后失效，若被保险人在期限后身故则无赔付，无法满足长期资产传承需求。C终身寿险：保障期限为终身，必然会发生身故赔付。其保额 或现金价值可在投保时确定，被保险人身故后，保险金将直接给付受益人，是资产传承规划的常用工具。D意外险：仅针对意外导致的身故或伤残赔付，保障范围有限，且保 额通常较低，无法满足系统性资产传承需求，故本题答案选择C选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）罗先生今年35岁，在一家外企任人力资源总监，罗先生2021年税后年薪60万元，另有年终奖税后10万元，罗太太王女士是基层公务员，今年也是35 岁，王女士税后收入14.4万元，另有讲课带来的税后收入2万元、出版书籍获得稿酬的税后收入1万元和家用车短期出租的税后收入1万元，女儿娜今年8岁，就读于某公办小 学。罗先生和王女士的双亲均健在，且双方的相母也均健在。罗先生家庭主要支出项目包括： 房贷每月还20,000元还剩20年，贷款年利率为5.145%； 水、电、煤、通讯及家庭生活用品的开销为每月5,000元； 每月5000元用于女儿的教育费用，还有每月6,000元的机动开支。 罗先生家庭所有资产均为婚后资产，其中自有住房是主要资产，目前市值5000000元；夫要二人还有1000000元存款在王女士名下，每年存款利息为5000元或30000元， 罗先生名下长期投资了200,000元某混合型基金，不过3年来净值上上下下，最终没有什么收益，他们各自还拥有一辆市值为200000元的家用车。夫妻两人都享有标准的社会 保险，罗先生公司另有一份团体意外险，如发生意外事故赔付金额为月薪的4倍，另外有保额为1000000元的定期寿险，王女士还持有某投资连结型保险，当前账户价值为 1000000元，保单已经生效5年可以随时终止。假设2021年度罗先生夫妇所在城市的月平均工资6666.67元，三险一金缴纳比例为20%。请根据该案例的背景信息，回答下列 问题。 下列关于罗先生家庭状况的表述中错误的是（）。', '{"A": "罗先生家庭资产缺乏流动性，应当设立应急准备金", "B": "罗先生家庭投资收益未超过房贷利息，可以考虑提前偿还部分房贷", "C": "罗先生家庭有社保，有定期寿险和万能险,保险保障充足", "D": "罗先生家庭理财收入占比较低，需要调整投资方案"}', '["C"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）罗先生今年35岁，在一家外企任人力资源总监，罗先生2021年税后年薪60万元，另有年终奖税后10万元。罗太太王女士是基层公务员，今年也是35 岁，王女士税后收入14.4万元，另有讲课带来的税后收入2万元、出版书籍获得稿酬的税后收入1万元和家用车短期出租的税后收入1万元。女儿娜娜今年8岁，就读于某公办小 学。罗先生和王女士的双亲均健在,且双方的母也均健在。罗先生家庭主要支出项目包括： 房贷每月还20,000元，还剩20年，贷款年利率为5.145%； 水、电、煤、通讯及家庭生活用品的开销为每月5000元； 每月5000元用于女儿的教育费用，还有每月6.000元的机动开支， 罗先生家庭所有资产均为婚后资产，其中自有住房是主要资产，目前市值5000000元；夫要二人还有1000000元存款在王女士名下，每年存款利息为5000元或30000元， 罗先生名下长期投资了200,000元某混合型基金，不过3年来净值上上下下，最终没有什么收益，他们各自还拥有一辆市值为200000元的家用车，夫麦两人都享有标准的社会 保险，罗先生公司另有一份团体意外险，如发生意外事故赔付金额为月薪的4倍，另外有保额为1000000元的定期寿险。王女士还持有某投资连结型保险，当前账户价值为 1000000元，保单已经生效5年可以随时终止。假设2021年度罗先生夫妇所在城市的月平均工资6666.67元，三险一金缴纳比例为20%。请根据该案例的背景信息，回答下列 问题。 通过背景资料信息，罗先生家庭的存款属于（），', '{"A": "结构性存款", "B": "定期存款", "C": "通知存款", "D": "美元存款"}', '["A"]', '', 4);
