INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）罗先生今年35岁，在一家外企任人力资源总监，罗先生2021年税后年薪60万元，另有年终奖税后10万元。罗太太王女士是基层公务员，今年也是35 岁，王女士税后收入14.4万元，另有讲课带来的税后收入2万元、出版书箱获得稿酬的税后收入1万元和家用车短期出租的税后收入1万元。女儿解娜今年8岁，就读于某公办小 学。罗先生和王女士的双亲均健在,且双方的祖母也均健在。罗先生家庭主要支出项目包括： 房贷每月还20.000元还剩20年，贷款年利率为5.145%； 水、电、煤、通讯及家庭生活用品的开销为每月5,000元； 每月5000元用于女儿的教育费用，还有每月6,000元的机动开支， 罗先生家庭所有资产均为婚后资产，其中自有住房是主要资产，目前市值5000000元；夫妻二人还有1000000元存款在王女士名下，每年存款利息为5000元或30000元。 罗先生名下长期投资了200.000元某混合型基金，不过3年来净值上上下下，最终没有什么收益，他们各自还拥有一辆市值为200000元的家用车，夫妻两人都享有标准的社会 保险，罗先生公司另有一份团体意外险，如发生意外事故赔付金额为月薪的4倍，另外有保额为1000000元的定期寿险。王女士还持有某投资连结型保险，当前账户价值为 100000元，保单已经生效5年可以随时终止，假设2021年度罗先生夫妇所在城市的月平均工资6666.67元，三险一金缴纳比例为20%。请根据该案例的背景信息，回答下列 问题。 罗先生夫妇计划投保某保险公司的医疗保验，下列关于医疗保险的说法中错误的是（）。', '{"A": "定额给付型医疗保险，是指按照约定的数额给付保险金的医疗保险", "B": "费用补偿型医疗保险的给付金额不得超过被保险人实际发生的医疗、康复费用金额", "C": "有社会保险就完全不用投保商业医疗保险", "D": "商业医疗保险按照保险金的给付性质分为费用补偿性医疗保险和定额给付型医疗保险"}', '["C"]', '', 4);
