INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '（不定项）罗先生今年35岁，在一家外企任人力资源总监，罗先生2021年税后年薪60万元，另有年终奖税后10万元。罗太太王女士是基层公务员，今年也是35 岁，王女士税后收入14.4万元，另有讲课带来的税后收入2万元、出版书籍获得稿酬的税后收入1万元和家用车短期出租的税后收入1万元。女儿娜娜今年8岁，就读于某公办小 学，罗先生和王女士的双亲均健在,且双方的祖母也均健在。罗先生家庭主要支出项目包括： 房贷每月还20,000元还剩20年，贷款年利率为5.145%； 水、电、煤。通讯及家庭生活用品的开销为每月5,000元； 每月5000元用于女儿的教育费用，还有每月6,000元的机动开支。 罗先生家庭所有资产均为婚后资产，其中自有住房是主要资产，目前市值5000000元；夫妻二人还有1000000元存款在王女士名下，每年存款利息为5000元或30000元。 罗先生名下长期投资了200,000元某混合型基金，不过3年来净值上上下下，最终没有什么收益，他们各自还拥有一辆市值为200000元的家用车。夫妻两人都享有标准的社会 保险，罗先生公司另有一份团体意外险，如发生意外事故赔付金额为月薪的4倍，另外有保额为1000000元的定期寿险，王女士还持有某投资连结型保险，当前账户价值为 1000000元，保单已经生效5年可以随时终止，假设2021年度罗先生夫妇所在城市的月平均工资6666.67元，三险一金缴纳比例为20%，请根据该案例的背景信息，回答下列 问题， 在做养老规划时，罗先生了解了养老目标日期基金产品。下列关于养老目标日期基金特点的说法错误的是（）。', '{"A": "产品每日开放，方便投资者流动性管理", "B": "动态配置，风险随着接近到期日逐步降低", "C": "主要采用FOF形式运作", "D": "可以用投资人计划退休日期命名"}', '["A"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）罗先生今年35岁，在一家外企任人力资源总监，罗先生2021年税后年薪60万元，另有年终奖税后10万元，罗太太王女士是基层公务员，今年也是35 岁，王女士税后收入14.4万元，另有讲课带来的税后收入2万元、出版书籍获得稿酬的税后收入1万元和家用车短期出租的税后收入1万元，女儿挪娜今年8岁，就读于某公办小 学。罗先生和王女士的双亲均健在,且双方的祖母也均健在，罗先生家庭主要支出项目包括： 房贷每月还20.000元还剩20年，贷款年利率为5.145%； 水电、煤、通讯及家庭生活用品的开销为每月5,000元； 每月5000元用于女儿的教育费用，还有每月6,000元的机动开支， 罗先生家庭所有资产均为婚后资产，其中自有住房是主要资产，目前市值5000000元；夫妻二人还有1000000元存款在王女士名下，每年存款利息为5000元或30000元。 罗先生名下长期投资了200,000元某混合型基金，不过3年来净值上上下下，最终没有什么收益，他们各自还拥有一辆市值为200000元的家用车。夫妻两人都享有标准的社会 保险，罗先生公司另有一份团体意外险，如发生意外事故赔付金额为月薪的4倍，另外有保额为1000000元的定期寿险。王女士还持有某投资连结型保险，当前账户价值为 1000000元，保单已经生效5年可以随时终止。假设2021年度罗先生夫妇所在城市的月平均工资6666.67元，三险一金缴纳比例为20%。请根据该案例的背景信息，回答下列 问题。 在做养老规划时，理财师向罗先生介绍了缴费确定型与待遇确定型企业年金在缴费方式、风险承担、养老金权益积累等方面的区别。下列关于两种企业年金的说法，错误的是 0.', '{"A": "缴费确定型企业年金雇主按事先确定的标准向企业年金计划缴费，同时承担账户亏损的责任。待遇确定型企业年金雇主提供承诺水平养老金的责任", "B": "缴费确定型企业年金取决于个人账户余额。待遇确定型企业年金取决于员工在单位的服务年限、平均薪酬收入及养老金权益的年度积索率", "C": "缴费确定型企业年金参保员工缴费，雇主提供匹配缴费。待遇确定型企业年金参保员工个人一般不缴费雇主提供全部缴费", "D": "缴费确定型企业年金和待遇确定型企业年金均可选择一次性发放或年金的形式发放"}', '["A"]', '', 4);
