INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项》罗先生今年35岁，在一家外企任人力资源总监，罗先生2021年税后年薪60万元，另有年终奖税后10万元。罗太太王女士是基层公务员，今年也是35 岁，王女士税后收入14.4万元，另有讲课带来的税后收入2万元、出版书籍获得稿酬的税后收入1万元和家用车短期出租的税后收入1万元。女儿娜娜今年8岁，就读于某公办小 学，罗先生和王女士的双亲均健在,且双方的祖母也均健在。罗先生家庭主要支出项目包括： 房贷每月还20,000元，还剩20年，贷款年利率为5.145%； 水、电、煤、通讯及家庭生活用品的开销为每月5,000元； 每月5000元用于女儿的数育费用，还有每月6,000元的机动开支。 罗先生家庭所有资产均为婚后资产，其中自有住房是主要资产，目前市值5000000元；夫妻二人还有1000000元存款在王女士名下，每年存款利息为5000元或30000元， 罗先生名下长期投资了200000元某混合型基金，不过3年来净值上上下下，最终没有什么收益，他们各自还拥有一辆市值为200000元的家用车。夫要两人都享有标准的社会 保险，罗先生公司另有一份团体意外险，如发生意外事故赔付金额为月薪的4倍，另外有保额为1000000元的定期寿险。王女士还持有某投资连结型保险，当前账户价值为 问题。 2022年初般市大幅波动，王女士计划将持有的混合型公募基金转换为不受股市影响的基金产品，她最应该选择的是（）：', '{"A": "二级债基", "B": "转债基金", "C": "定增基金", "D": "货币基金"}', '["D"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）罗先生今年35岁，在一家外企任人力资源总监，罗先生2021年税后年薪60万元，另有年终奖税后10万元。罗太太王女士是基层公务员，今年也是35 岁，王女士税后收入14.4万元，另有讲课带来的税后收入2万元、出版书籍获得稿酬的税后收入1万元和家用车短期出租的税后收入1万元。女儿娜娜今年8岁，就读于某公办小 学。罗先生和王女士的双亲均健在,且双方的祖母也均健在。罗先生家庭主要支出项目包括： 房贷每月还20,000元还剩20年，贷款年利率为5.145%； 水、电、煤、通讯及家庭生活用品的开销为每月5,000元； 每月5000元用于女儿的教育费用，还有每月6,000元的机动开支。 罗先生家庭所有资产均为婚后资产，其中自有住房是主要资产，目前市值5000000元；夫妻二人还有1000000元存款在王女士名下，每年存款利息为5000元或30000元。 罗先生名下长期投资了200,000元某混合型基金，不过3年来净值上上下下，最终没有什么收益，他们各自还拥有一辆市值为200000元的家用车，夫妻两人都享有标准的社会 保险，罗先生公司另有一份团体意外险，如发生意外事故赔付金额为月薪的4倍，另外有保额为1000000元的定期寿险。王女士还持有某投资连结型保险，当前账户价值为 1000000元，保单已经生效5年可以随时终止，假设2021年度罗先生夫妇所在城市的月平均工资6666.67元，三险一金缴纳比例为20%。请根据该案例的背景信息，回答下列 问题。 进入2022年后，王女士发现银行无论是网点还是手机APP都无法购买到保本理财产品其原因是受（）影响。', '{"A": "《存款保险条例》", "B": "《关于规范金融机构资产管理业务的指导意见》", "C": "《证券投资基金销售管理办法》", "D": "《个人理财业务管理暂行办法》"}', '["B"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于中小企业主共同特征的表述，正确的有（）。', '{"A": "随着年龄的增加倾向于选择职业经理人接手", "B": "做事干练一般喜欢独自做决定", "C": "随着年龄增长，关心个人财富传承", "D": "个人人身风险对企业经营影响大", "E": "较为以自我为中心"}', '["B", "C", "D", "E"]', '中小企业主一般都是私营业主，在企业中具有绝对的领导地位，企业的利益与自身利益之间联系累密，一般而言，作为群体，中小企业主的性格有以下几个特色：以自我为中 心、做事干练、决策简练、时间观念强。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '依照继承法规定，有下列（）情形的按法定继承来办理。', '{"A": "遗嘱继承人丧失继承权", "B": "被继承人生前没有立下遗喉", "C": "遗崛继承人受遗赠人先于被继承人死亡", "D": "遇嘴继承人放弃继承", "E": "受遗赠人放弃受遇赠"}', '["A", "C", "D", "E"]', '继承开始后，按照法定继承办理。虽有遗哦但是有下列情形之一的，遗产中的有关部分按照法定继承办理：（1）遗喔继承人放弃继承或者受遗赠人放弃受遗赠的；（2）遗哦 继承人丧失继承权的：（3）遗崛继承人。受遗赠人先于遗哦人死亡的：（4）遗弱无效部分所涉及的遗产；（5）遗处分的遗产，B选项：被继承人生前没有立下遗崛，还需 要看是否有遗赠扶养协议或者遗赠，若有则就按照协议或遗赠办理。若都没有，那么财产按照法定继承顺序来继承，B选项说法不准确，故不选，故本题选择ACDE选项。 25', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '一般而言，下列关于理财师给客户提供的保险产品配置建议中，恰当的有（），', '{"A": "处于人生形成期阶段的年轻人，建议的保险组合为两全险+终身寿险+住院医疗险", "B": "处于人生成熟期阶段的中年人，建议的保险组合为重疾险+住院险+津贴型保险", "C": "处于退休阶段的老年人，建议的保险组合为意外伤害险+意外医疗保验", "D": "处于人生成长期阶段的家庭成员，建议的保险组合为终身寿险+重疾险+意外险+医疗险", "E": "对于风险认知和承受能力比较低的客户，可以配置分红险、投连险及定期寿险等组合"}', '["B", "C", "D"]', '和风险偏好等进行合理的保险配置。 （1）建议年轻人的组合应为：意外险+定期寿险+住院医疗险。 （2）建议成家立业期客户的保险组合应为：终身寿险+重疾险+意外险+医疗险， （3）建议中年人的保险组合应为：重疾险+住院险+津贴型保险。 （4）建议老年人的保险组合应为：意外伤害险+意外医疗保险， 一般而言，风险认知和承受能力比较低的客户，对意外险、定期寿险、终身寿险和两全寿险的保障需求较多；而风险认知和承受能力高的客户，在风险保障的需求前提下， 可以配置分红险、万能险以及投资连结险等投资型寿险产品。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于医疗保险的表述，正确的有（）。', '{"A": "定期给付型医疗保险，是指按照约定的数额给付保险金的医疗保险", "B": "医疗保险按解保险金的给付性质分为费用补偿型医疗保险和定额给付型医疗保险", "C": "费用补偿型医疗保险的给付金额可以超过被保险人实际发生的医疗、康复费用金额", "E": "医疗保险是指按照保险合同约定为被保险人的医疗、康复等提供保障的保险"}', '["B", "D", "E"]', '医院杂费。手术费用及检查费用等。所以选项“医疗费用包括内容”表述正确。不同的医疗保险会对其中的一项或若干项费用提供保障。医疗保险按照保险金的给付性质分为 费用补偿型医疗保险和定额给付型医疗保险。所以选项“医疗保险分类”表述正确。费用补偿型医疗保险。是指根据被保险人实际发生的医疗、康复费用支出，按照约定的标 准确定保险金数额的医疗保险：费用补偿型医疗保险的给付金额不得超过被保险人实际发生的医疗、康复费用金额。所以选项“费用补偿型医疗保险表述”错误。定额给付型 医疗保险，是指按约定的数额给付保险金的医疗保险。所以选项“定期给付型医疗保险定义”说法错误。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列财产可以称为遗产的是（）', '{"A": "公民在宅基地上自种的树木", "B": "人寿保险赔款", "C": "游戏装备", "D": "会员账号", "E": "比特币"}', '["A", "B", "C", "D", "E"]', '根据《民法典》第一千一百二十二条的规定：遇产是自然人死亡时遇留的个人合法财产。依照法律规定或者根据其性质不得继承的遇产，不得继承。《民法典》在立法上采取 了概括的方式，只要是自然人合法取得的财产，都属于遗产，可以被继承，最大限度地保障私有财产继承的需要。虚拟货币也可以作为遗产继承。 26', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '根据《中华人民共和国保险法》的规定，应当由保险人承担的费用有（）：', '{"A": "保险事故发生后，被保险人为防止或者减少保险标的损失所支付的施救费用", "B": "为超过了保险责任范围的损失所支付的受损标的检验、估价、出售的费用", "C": "责任保险的被保险人因发生给第三者造成损害的保险事故而被提起诉讼公或仲裁所支出的诉讼费或仲裁费用", "D": "被保险人为避免保险事故的发生，而采取的管理、维修等措施所支出的费用", "E": "保险事故发生后，被保险人为确定事故性质进行勘查。鉴定所支出的合理费用"}', '["A", "C", "E"]', '根据《保险法》第五十七条规定，保险事故发生后，被保险人为防止或者减少保险标的的损失所支付的必要的、合理的费用，由保险人承担。A正确。根据《保险法》第六十四 条规定，保险人。被保险人为查明和确定保险事故的性质、原因和保险标的的损失程度所支付的必要的、合理的费用，由保险人承担，正确。根据《保险法》第六十六条规 定，责任保险的被保险人固给第三者造成损害的保险事故而被提起仲裁或者诉讼的。除合同另有约定外，由被保险人支付的仲裁或者诉讼费用及其他必要的、合理的费用，由 保险人承担，C正确。BD两项所发生的费用不属于保险人的责任范围。故本题选择ACE选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '买卖二手房可能涉及的税种包括）', '{"A": "城市继护建设税", "B": "印花悦", "C": "契税", "D": "增值税", "E": "个人所得悦"}', '["A", "B", "C", "D", "E"]', '买卖房屋需要缴纳的税种有增值税、房产税。契税。城市维护建设税及教育费附加，土地增值税、印花税和个人所得税。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '在经济萧条时，产权比率高说明企业的（）：', '{"A": "利息支出多", "B": "负债占比大", "C": "偿债能力好", "D": "财务风险大", "E": "经营较稳健"}', '["A", "B", "D"]', '产权比率=负债总额/所有者权益总额。产权比率反映的是资本结构，用于衡量企业财务结构是否稳建及企业的长期偿债能力。产权比率高说明高风险。高报酬的财务结构，反 本题选择ABD选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列0属于单位福利。', '{"A": "最低生活保障", "B": "失业保险和就业保障", "C": "股权激励", "D": "利润分享计划", "E": "员工持股计划"}', '["C", "D", "E"]', '除了企业年金之外，其他类型的单位福利还包括单位保健计划、利润分享计划、员工持股计划、股权激励等、其他两项属于社会福利。 27', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列支出属于家庭生活支出的包括（）。', '{"A": "专项支出", "B": "日常生活支出", "C": "投资理财咨询费支出", "D": "保费支出", "E": "礼金支出"}', '["A", "B"]', '家庭生活支出包括家庭日常生活支出和专项支出两个部分。家庭日常生活支出包括在衣。食。住、行、娱乐休闲。医疗等方面的支出：专项支出包括子女教育和按揭贷款还 款。信用卡还款。赠养支出等。CD属于理财支出。E属于其他支出，故本题选择AB选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '人寿和健康保险合同由大量条款组成。其中许多条款用以保护投保人，帮助解决潜在的信息不对称问题。保护投保人的条款主要包括（），', '{"A": "项，宽限期条款是对没有按时缴纳续期保费的投保人给予一定的时间宽限去缴纳续期保费。B项，复效条款是指保险单因投保人欠缴保费而失效后，投保人可以在一定时期内", "B": "复效条款", "C": "犹像期条款", "D": "免责条款", "E": "不丧失价值条款"}', '["A", "B", "C", "E"]', '', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列选项中。属于风险管理的基本程序环节的有（）。', '{"A": "风险转移", "B": "风险评价", "C": "风险估测", "D": "风险识别", "E": "风险回避"}', '["B", "C", "D"]', '风险管理的基本程序分为风险识别、风险估测。风险评价、选择风险管理技术和评估风险管理效果五个环节。风险管理的方法包括：回避风险、预防风险、自留风险和转移风 险。故本题答案选“风险评价、风险估测和风险识别，', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '企业年金的资金来源比较少，一般是由（）组成。', '{"A": "员工个人缴费", "B": "其他补贴", "C": "企业缴费", "D": "财政支出", "E": "企业年金基金投资运营收入"}', '["A", "C", "E"]', '企业年金的资金来源相对较少，仅由企业缴费、员工个人缴费和企业年金基金投资运营收益组成。 28', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '理财师在做退休规划时需要了解客户的现有资产状况，其内容主要包括（），', '{"A": "未来退休生活的收入来源", "B": "家庭成员的婚姻状况", "C": "未来家庭成员的职业发展状况", "D": "客户目前的家庭资产、现金流、人力资本（未来收入）等财务情况", "E": "家庭成员的结构变化"}', '["A", "C", "D", "E"]', '在制定退休规划前首先应对家庭及个人现有资产状况充分了解，包括两个方面：①要对客户目前的家庭资产。现金流、人力资本（未来收入）等财务情况以及未来家庭成员的 职业发展状况家庭成员的结构变化等进行评估：②了解现有资产状况有助于了解未来退休生活的收入来源。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于企业投融资中的税收筹划的说法，正确的是（）', '{"A": "计算应纳税所得额时不得扣除利息支出", "B": "企业投资股票所得股利天须缴纳所得税", "C": "不同的投资方式所面对的税收法规也不同", "D": "股利支付不作为费用支出，而要在税后利润中支付", "E": "税收筹划遵循时效性原则"}', '["C", "D", "E"]', '利息支出是作为费用支出，在计算应纳税所得额时予以扣除；企业投资股票所得股利须缴纳所得税，但企业购买国库券的利息收入则可免征所得税，', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '在教育投资规划中，教育金保险相较于银行储蓄的优势包括（）。', '{"A": "强制储蓄", "B": "利息收入", "C": "保障功能", "D": "投资分红功能", "E": "保费格免"}', '["A", "C", "D", "E"]', '教育保险又称教育金保险。子女教育保险，是以为子女准备教育基金为目的的保险。教育保险是储蓄性的险种。既具有强制储蓄的作用又有一定的保障功能。保费韬免是教育 金保险的一个优势。教育金保险通常还具有强制储蓄的功能。另外，教育金保险一般都具有投资分红功能。由于投资期限相对较长，同时分多次给付，能够在一定程度上抵御 通货能胀的影响，利息收入是银行储蓄的特点。 29', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '在企业财务分析中，流动比率是对企业偿债能力分析的重要指标之一。下列有关流动比率描述正确的有0）。', '{"A": "流动比率过高，说明企业现金过于充裕，没有很好的发挥作用", "B": "流动比率过低，说明企业现金过于紧张，偿还短期负债有可能需要动用长期资产", "C": "企业流动比率过高，有可能存在存货严重，应收账款过多等现象", "D": "流动比率=流动资产/流动负债，流动比率大于1，说明流动资产大于流动负债，企业短期偿债能力强", "E": "流动比率=（速动资产+存货）/流动负债，流动比率小于1，说明流动资产大于流动负债，企业长期偿债能力强"}', '["A", "B", "C", "D"]', '流动比率■流动资产/流动负债，流动比率大于1，说明流动资产大于流动负债，企业短期偿债能力越强。故选项“流动比率=（速动资产+存货）/流动负债”说法错误。其他 选项表述均正确。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于技术指标分析的说法，正确的有（）， 考前', '{"A": "在进行某项技术指标的分析时，经常用到其他技术分析方法的基本结论", "B": "实际应用时，应将多种技术指标结合起来，进行组合分析", "C": "技术指标分析是相对于基本面分析而言的", "D": "任何技术指标都有自己的适应范围和应用条件", "E": "实际应用时，仅应用一种最优的技术指标，不需要进行组合分析"}', '["A", "B", "C", "D"]', '指标法是指考虑市场行为的各个方面，建立一个数学模型，通过数学计算得到一个体现股票市场某个方面内在实质的数字（指标值），指标的具体数值和相互间的关系直接反 映股市所处的状态，为我们的投资操作提供指导的方向。在实际应用时，不能仅应用一种最优的技术指标，还是需要进行组合分析的。所以选项“不需要进行组合分析”说法 错误，故本题答库除了不选该项外，其他的全选。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '□D.假设终老年龄', '{"A": "假设家庭资产负债表", "B": "假设客户职业发展前景", "C": "假设未来收入和支出的增长率", "E": "假设家庭现金流量表"}', '["C", "D"]', '括固定收入。非固定收入。固定家庭基本支出、非固定支出等)。故本题选择CD选项。', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '孙先生拥有一家个人独资企业，计划为企业职工购买团体医疗保险，但他对保险公司提供的产品不甚满意，因此希望能够修改保险合同。下列说法正确的有（），', '{"A": "团体合同的设计具有极大的灵活性，没有任何约束", "B": "由于保险合同是格式条款，因此不能修改", "C": "保险人为了规避医疗费用过高的风险，在团体医疗保险合同中，还常常附加有免赔额条款及共同保险条款", "D": "保验合同可以修改，但只稳在原有产品条款的基础上做小范围的调整", "E": "团体合同设计的灵活性在某种程度上依赖于该企业的规模"}', '["C", "E"]', '团体保险的投保人是单位团体，保单使用团体保单，保费统一缴纳，因此，保险人对于团体保险给予了一定的灵活性，团体合同设计的灵活性在某种程度上依赖于该企业的规 模。保险合同是可以修改的：但也受一定条件的约束。故本题选择CE选项。 30', 4);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '2018年实行的《企业年金办法》规定：企业和职工个人缴费合计不超过本企业职工工资总额的（）。', '{"A": "12%", "B": "6%", "C": "8%", "D": "10%"}', '["A"]', '2018年实行的《企业年金办法》规定，企业缴费每年不超过本企业职工工资的8%，企业和职工个人缴费合计不超过本企业职工工资的12%。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列居民个人收入项目中，以每月取得的收入为一次计算应纳税所得额的是（）。', '{"A": "基金分红所得", "B": "财产租赁所得", "C": "财产转让所得", "D": "俱然所得"}', '["B"]', '纳税人取得利息、股息。红利所得。财产租赁所得。财产转让所得和偶然所得，按月或者按次计算个人所得税，有扣缴义务人的。由扣缴义务人按月或者按次代扣代缴税 款，其中偶然所得和财产转让所得是按次计算个人所得税，财产租赁所得是按月计算个人所得税，基金分红所得不交税，故本题选择B选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于代位继承，下列表述错误的是（）。', '{"A": "需有被承人的子女先于披继承人死亡这一法律事实", "B": "被继承人的兄弟姐妹先于被继承人死亡的，不能由被继承人的兄弟姐妹的子女代位继承", "C": "代位继承只适用于法定继承，不适用于遇嘎继承", "D": "代位继承人一般只能继承被代位承人有权继承的遇产份额"}', '["B"]', '代位继承作为法定继承制度的一个不可分割的组成部分，其构成条件为：（1）存在被继承人的子女先于被继承人死亡这一法律事实。死亡包括自然死亡和宣告死亡，宣告 被继承人的子女的直系晚辈血亲代位继承。被继承人的兄弟姐妹先于被继承人死亡的，由被继承人的兄弟姐妹的子女代位继承。B选项错误。（4）代位继承是一次继 承，代位继承人是基于其代位继承权而直接参加继承被继承人遗产的继承，从而取得遗产。D选项正确。本题选择B选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '假设金融市场上无风险收益率为2%，某投资组合的β系数为1.5，市场组合的预期收益率为8%，根据资本资产定价模型，该投资组合的预期收益率为（），', '{"A": "11%", "B": "13%", "C": "12%", "D": "10%"}', '["A"]', '资本资产定价模型公式为：股票的必要报酬率=无风险收益率+该股票β系数×（市场组合必要报酬率-无风险收益率），将数值代入公式中得到：2%+1.5×（8%-2%） =11%.', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '一股而言，下列应用范围最广、最有效的风险管理手段是（）：', '{"A": "预防风险", "B": "自留风险", "C": "回避风险", "D": "转移风险"}', '["D"]', '（1）回避风险是指主动避开损失发生的可能性。如考虑到游泳有蒲水的危险，就不去游泳，量然回避风险能从根本上消除隐患。但这种方法明显具有很大的局限性，因 为并不是所有的风险都可以回避或应该进行回避： （2）预防风险涉及一个现时成本与潜在损失比较的问题：若潜在损失远大于采取预防措施所支出的成本，就应采用预防风险手段： （3）自留风险是指自己非理性或理性地主动承担风险，一般适用于应对发生概率小，且损失程度低的风险， （4）转移风险是指通过某种安排。把自己面临的风险全部或部分转移给另一方。通过转移风险而得到保障。是应用范国最广、最有效的风险管理手段，保险就是其中之 ，故本题答案选“转移风险”。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '购买保险产品时，下列需要注意的事项中不恰当的是。', '{"A": "坚持购买保障期限长的保险", "B": "要灵活利用附加险", "C": "注重保险与储蓄和金融投资产品的区别", "D": "尽量避免保验功能重复"}', '["A"]', '配置保险产品需要注意的其他事项：（一）保险与储蓄、金投资产品的区别：（二）长期保险与短期保险相结合：（三）灵活利用附加险： （四）尽量避免保险功能重 复客户在选购保险产品时，需要按朋家庭实际情况和需要选择适合的保险产品，长期保险与短期保险相结合：（五）充分挖掘线上渠道的优势产品。所以选项“坚持购买 保障期限长的保险”不恰当，故本题答案选该项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于教育投资的说法，不正确的是（），', '{"A": "银行储蓄能够抵抗通胀保值增值，是主要的教育投资工具", "B": "教育保险中的保险豁免可以防范因家长造遇不幸而导致的收入中断风险", "C": "投资期限越长，投资标的的流动性要求可以越低", "D": "由于投资期限长，可以采取定期定额投资的策略"}', '["A"]', '银行储蓄星然省时省力，但是考虑到通货能胀率的不断攀升，其常常不能达到教育资金保值增值的目的。保费豁免是教育金保险的一个优势。一旦投保的家长遭受不幸， 身故或者全残，保险公司将豁免所有未缴保费，子女还可以继续得到保障和资助。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '小明申请了本科四年每年12000元的国家助学贷款，约定毕业后开始计息，分六年偿还，年利率为4.8%，则小明毕业后每个月工资用于归还助学贷款不能低于（）元。（答 案取最接近数值）', '{"A": "670", "B": "769", "C": "568", "D": "895"}', '["B"]', '根据题目，小明共货款12000×4=48000元，年利率为4.8%，月利率为4.8%+12=0.4%。还款期数为6×12=72，用等额本息还款法计算，每月还款额=贷款本金×[月利 率×（1+月利率）^还款期数1/（1+月利率）^还款期数-1)=769元，使用理财计算器，利率=0.4%，期数=72，PV=48000，FV=0，期末模式，求得每月还款额 =769,', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王某预计退休后能够生存25年，退休后每年年初从退休基金中拿出40000元用于一年的生活支出。如果退休基金的投资回报率为3%，为了满足退休后的生活需要，王某在 退休时应该准备（）元退休基金。', '{"A": "717405.5", "B": "717421.68", "C": "727415.6", "D": "720000"}', '["B"]', '可以根据期初年金现值公式或理财计算器求出。方法一：公式法：PMT=40000r=3%，期数n=25，带入公式PV=PMT×[1-（1+r）^（-n）1/r×（1+r）， PV=40000×[1- (1+3%)(-25)]/25× (1+3%)，求得PV=717421.68, 方法二：理财计算器法：利率=3%，期数=25，FV=0，C=-40000，期初模式，求得PV=717421.7。故本题选择B选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '理财规划师在为客户进行教育规划时。估算教育费用第一步要做的是（）。 考前绝径', '{"A": "确定教育规划的目标", "B": "按预计通货能胀率计算所需要的最终费用", "C": "计算所需各项费用"}', '["B"]', '教育费用的增长率一方面受到通货能长率的影响，另一方面教育费用的增长率通常又高于通货能账率，且呈现逐年上升的趋势。因此在估算教育费用的增长时，一般在通', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '对于中小企业税收筹划是指将企业作为一个整体，安排自身经营项目，用足税收条款证对自身有利的政策，体现了税收筹划的（）：', '{"A": "系统性原则", "B": "完整性原", "C": "综合平衡原则", "D": "合法性原则"}', '["A"]', '系统性原则是指将企业作为一个整体。安排自身经营项目，用足税收条款中对自身有利的政策：资料完整性原测则是保存相关账用为了迎接纳税检查，真正实现税收筹划： 综合平衡原则是服从。服务于企业整体财务管理目标，注重综合平衡：合法性原则是税收筹划要合理，通过积极的税收筹划降低税收负担，增加企业盈利是非常必要的。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，关于个人所得税子女教育专项付加扣除，说法错误的是（）。', '{"A": "子女6月高中毕业，9月上大学，7-8月能享受子女教育专项附加扣除", "B": "境外学校接受教育可以享受子女教育专项附加扣除", "D": "民办学校接受救育可以享受子女救育专项时扣除"}', '["C"]', '子女教育专项附加扣除包括子女接受学前教育和学历教育两部分。学历教育包括义务教育（小学和初中教育），高中阶股教育（普通高中。中等职业教育、技工教育）， 高等教育（大学专科。大学本科、硕土研究生、博士研究生教育），上大学也享受子女教育专项附加扣除的，但是，大学本科结束后，备考研究生期间，父母不可以扣子 女教育的专项扣除。所以“本科毕业之后，准备考研究生的期间”说法错误。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，不属于客户家庭财务信息来源的是（）：', '{"A": "调查问卷", "B": "户口信息", "C": "面谈征询", "D": "开户资料"}', '["B"]', '信息收集方法，主要有开户资料、调查问卷、面谈征询和客户能提交的一些账户，财务资料。故本题选择B选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '刘明强今年65岁，立下遗哦：“大女儿读完大学，已经找到工作，有固定工资收入。小儿子大专刚毕业，目前待业没有生活来源，我百年之后，所遇两居房屋，在××路×x 号，由小儿子继承。“刘明强亲自签名，记某年月日，不久其去世。关于本例，（）说法正确。', '{"A": "刘明强的遗喔无见证人，无效", "B": "刘明强的遗喔符合法律规定", "C": "刘明强的遗嘱未经公证，无效"}', '["B"]', '遗嘱的有效须具备的条件为：①立遗瞩人在立遗嘎时必须有民事行为能力：②遗届必须是遗嘱人的真实意思表示；③遗瞩的内容必须合法；①遗喔的形式必须符合法律规 定。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '存货的流动性将直接影响企业的流动比率，因此，企业特别重视对存货的分析。下列有关存货流动性的表述，错误的是（），', '{"A": "用时间表示的存货周转率就是存货周转天数", "B": "存货的流动性，一般用存货的周转速度指标来反映。即存货周转次数或存货周转天数", "C": "销售收入越高，存货周转率越低"}', '["C"]', '存货周转率反映的是企业存货周转次数，包括存货周转次数和存货周转天数两个指标：①存货周转次数=销售成本/存货平均余额。存货周转次数越多，说明企业存货周转 速度快，企业存货管理水平高。②存货周转天数=360/存货周转次数或存货周转天数=存货平均余额×360/销售成本。存货周转天数越少，说明存货周转次数越多，存货 管理水平越高。存货周转率和销售成本有关，和销售收入无关。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '在教育规划之前，理财师应当对客户的家庭财务信息进行询问，下列选项中，理财师不应涉及的是（）。', '{"A": "客户的家庭是否为单亲家庭", "B": "客户同事的子女教育金筹备计划", "C": "客户子女的特长爱好情况", "D": "客户是否希望子女出国留学"}', '["B"]', '客户家庭财务信息的内容主要包括以下几个方面： （1）资产信息（包括储蓄、投资账户、保单信息等）； （2）负债信息； （3）收入信息（包括收入来源）： （4）支出信息； （5）其他相关的家庭、财务信息。 不包括“客户同事的子女教育金筹备计划”。故本题答案选该项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '自先生为非居民个人，2021年在境内居住天数不满90天，2021年1月，自先生取得境内支付的股权激励所得50万元，其中归属于境内工作期间的所得为10万元，则白先生 在境内股权激励动所得的应纳税额为（）元。', '{"A": "4740", "B": "106970", "C": "40495", "D": "11540"}', '["D"]', '非居民个人一个月内取得股权激励所得，单独按照无住所个人工资薪金所得收入额计算规定计算当月收入额，不与当月其他工资薪金合并，按6个月分摊计税（一个公历 年度内的股权激励所得应合并计算），不减除费用，适用月度税率表计算应纳税额，计算公式如下：当月股权激动所得应纳悦额=【（本公历年度内股权激励所得合计 额/6）×适用税率-速算扣除数)×6-本公历年度内股权激励所得已纳税额，当月股权激励所得应纳税额=［（100000/6）×20%-1410]×6=11540故本题选择D选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列属于失能收入损失保险特有特点的是（）：', '{"A": "规定年龄误售条款", "B": "给付金额一股低于正常工作收入水平", "C": "规定不丧失价值条款", "D": "规定受益人条款"}', '["B"]', '失能收入损失保险一般是按月或按周进行补偿，主要根据被保险人的选择而定，每月或每周可提供金额相一致的收入补偿。失能收入损失保险所提供的保验金不一定能完 全补偿被保险人因伤残而导致的收入损失。失能收入损失保险的给付额一般都有一个最高限额。该限额低于被保险人在伤残以前的正常收入水平，。这一限制的目的是为了 促使残疾的被保险人尽早重返工作岗位。故本题选择B选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '秦女士向他的理财师小王询问子女教育金规划的特性和原则。小王的介绍如下，其中正确的是）。（1）子女教育金可以通过国家强制的教育金账户来储蓄。个人储蓄只 是补充性的（2）教育金支出的成长率一般高于通货能胀率，因此子女教育金投资不能太过保守，至少要是投资收益率高于通货膨胀率（3）子女教育金没有费用弹性，但是 时间弹性比较高，规划时要多考虑时间因素（4）教育金支出的成长率比较高，因此需要从宽规划（5）子女教育金规划可配合保险规划 (3) (5) (3) (4) (2) (4) (4)', '{"A": "(2)", "B": "(1)", "D": "(2)"}', '["D"]', '确。故本题答案选“(2）（4）（5）。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于人口老龄化对社会经济的影响，下列表述错误的是（）。', '{"A": "老年人体质较弱，人口老龄化将增加医疗卫生支出压力", "B": "老龄化产业是朝阳产业。人口老龄化有助于经济发展", "C": "人口老龄化增加了社会养老成本", "D": "人口老龄化将减少适龄劳动人口规模，影响经济发展"}', '["B"]', '人口老龄化，是指老年人在总人口中的相对比例上升，按照国际通行的标准，60岁以上的人口占总人口的比例超过10%。或65岁以上的人口占总人口的比例超过7%，即 可看作达到了人口老龄化，人口老龄化带来的问题不仅仅是老年人口的增加，劳动力在人口中的比例也会降低，社会抚养比会继续下降，所以人口老龄化加重了社会的养 老负担，B选项错误。故本题选择B选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于财富传承规划基本概念的认识，不正确的是（）。 考前维', '{"A": "财富传承都是基于特定受益人或继承人，而特定受益人大多是家庭中重要的成员", "B": "财富转移或传承时机选择多是为了提升其以货币计价的财富转移的效率", "C": "对象是客户的资产和负债"}', '["D"]', '当转移对象为慈善机构时。转移财产一般完全免税，即税负不是考虑因素，财富控制权是主要考虑因素。如果财富升值的速度快。财富拥有者又不想过早失去控制或决策 权，转移的时间就应当尽可能地延迟。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列哪一项不属于客户退休后的收入（）：', '{"A": "企业年金", "B": "商业保险", "C": "正常工作收入", "D": "社会保障"}', '["C"]', '退休收入的主要构成包括社会养老金、家庭存款。企业年金、商业保险、其他收入和一些社会保障等。目前而言，社会养者金仍然是退休收入的主要来源，这项收入也是 计算退休金缺口的主要数据。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列选项中，属于员工福利主要特征的有（）。（1）保障基本生活需要和提高员工生活质量（2）以当期支付为主（3）是劳动报酬的货币形式（4）以公平分配原则为主 (3) (4)', '{"A": "(1) (4)", "B": "(1)", "C": "(2)", "D": "(2) (3)"}', '["A"]', '福利则是企业为员工提供的另一种补充性薪酬。以便为员工提供各种与生活质量保障、工作生活平衡相关的物质补偿与服务形式。薪酬代扣项目中的基本社会保险费、住 房公积金缴费等均属于社会福利，而企业年金、补充医疗保险等属于单位福利。这些薪酬将会在员工退休生活开始后提供收入来源。这些福利均是延期支付。故本题答案 选~ (1) (4)。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列事件中，属于由非系统性风险造成证券价格变化的是（），', '{"A": "人民币升值趋势明显，热钱加速流入，受此影响，某银行股票价格大幅上涨", "B": "某上市公司因财务造假被证监会立案调查，受此影响，该公司股票价格大幅下跌", "C": "央行突然宣布提高基准利率，受此影响，某公司股票价格大幅下跌", "D": "受欧债危机影响，全球股票市场均出现不同幅度下跌"}', '["B"]', '非系统性风险是一种与特定公司或行业相关的风险，例如，一个新的竞争者可能开始生产同样的产品。一次技术突破使一种现有产品消亡。通过分散投资，非系统性风险 能被降低；而且，如果分散是充分有效的，这种风险还能被消除，因此，又称为可分散风险。非系统性风险具体包括财务风险、经营风险、信用风险、偶然事件风险等。 系统性风险是由那些影响整个投资市场的风险固素所引起的，这些因素包括经济周期、国家宏观经济政策的变动等。这类风险影响所有投资资产变量的可能值，因固此不能 通过分散投资相互抵消或者削霸。因此又称为不可分散风险。系统性风险具体包括政策风险、利率风险、购买力风险和市场风险等。故本题答案选“某上市公司因财务造 假被证监会立案调查，受此影响，该公司股票价格大幅下跌”，', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '某人于2023年1月取得一次性劳务报酬30000元，按规定其当月该项收入应预嫩个人所得税为（元。', '{"A": "5200", "B": "7200", "C": "4800", "D": "7000"}', '["A"]', '劳务报配酬适用的是劳务报酬所得三级税率表，劳务报酬所得。稿酬所得和特许权使用费所得。每次收入不超过4000元的。减除费用800元，每次收入超过4000元以上 的，减除20%的费用，并且稿酬所得按减除费用后的70%计算收入额。30000×（1-20%）×30%-2000=5200（元）【备注：2000是速算扣除数】故本题选择A选 项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户王女士在理财师的推荐下进行了资产配置。几年后，在评估业绩时，理财师发现该配置的愈森指数为0.8%，表明该资产配置过去几年的实际收益率（）。', '{"A": "比无风险收益低", "B": "比市场平均水平低", "C": "比无风险收益高", "D": "比市场平均水平高"}', '["D"]', '詹森指数是指在给出投资组合的贝塔及市场平均收益率的条件下，投资组合收益率超过CAPM预测收益率的部分。如果投资组合位于证券市场线的上方，则α值（詹森指 数）大于零，说明投资组合收益率高于市场平均水平，可以认为其绩效很好：如果投资组合位于证券市场线的下方，则α值小于零，表明该组合的绩效不好。题干数值 0.8%大于零，说明高于市场平均水平。故本题选D.【补充】其公式为：αp=RP-[Rf+βP(Rm-Rf）1.', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '现代证券组合管理理论的开端是（），', '{"A": "资本资产定价模型（CAPM）", "B": "均值方差模型", "C": "三因子模型", "D": "套利定价理论（APT）"}', '["B"]', '1952年，美国经济学家哈里·马柯维茨发表了《资产组合选择一投资的有效分散化》一文，这成为现代证券组合管理理论的开端。马柯维茨对风险和收益进行了量化， 建立了均值方差模型，提出了确定最佳资产组合的基本模型，故本题选择B选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '刘小姐就职于某商业银行。计划工作三年后出国留学，预计花费为120万元。目前有60万元的初始投资，若年投资回报率为6%，则刘小姐每月末至少需从工作收入中拿出 0元用于投资。 （答案取近似数值）', '{"A": "14382", "B": "12466", "C": "12254", "D": "12192"}', '["C"]', '根据题意，本题要求每月未至少需从工作收入中拿出多少元用于投资，可知是求年金C，题干中给的是年，要转化成月，利率为6%/12=0.5%，期限n=3*12=36， PV=-60，FV=120，期末模式，代入到理财计算器中，求得C=12254故本题选择C选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于资本市场线、证券市场线的理解，下列说法正确的是（）：', '{"A": "证券市场线反映了资产或资产组合的收益与时间的相关性", "B": "资本市场线反映了资产或资产组合的期望收益率与其风险的关系", "D": "资本市场线反映了资产或者资产组合的收益与时间的相关性"}', '["B"]', '证券市场线与资本市场线，都是描述资产或资产组合的期望收益率与风险之间关系的曲线。资本市场线的横轴是标准差，既包括系统性风险又包括非系统性风险，它所反 映的是这些资产组合的期望收益与其全部风险问的依赖关系。证券市场线的横轴是贝塔系数，只包括系统性风险，', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '目前我国养老金发放过低受围于多方面原因，其中不包括（）。', '{"A": "双轨制运行使得养老金替代率呈现分化态势", "B": "养老金来源的单一化", "C": "养老金缴费比率过低", "D": "养老金调整机制缺失"}', '["C"]', '目前我国养老金发放过低受困于多方面，一是养老金调整机制的缺失，使得养老金增长没有稳定的制度保障：二是双轨制运行使得养老金昔代率呈现分化态势；三是养老 金来源的单一化，让其增长后续乏力，使养老保障的质量和水平都明显下滑。故本题答案选“养老金缴费比率过低”，', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '甲乙未结婚生下儿子丙，丙跟随母亲一起生活，下列说法正确是（），', '{"A": "丙仍可以依法享有对父母的继承权", "B": "子女对父母的继承权因父母的不抚养而消除", "C": "丙对甲不享有继承的权利", "D": "甲对丙不负有抚养教育的义务"}', '["A"]', '非婚生子女是指没有合法婚姻关系的父母所生的子女。《民法典》规定，非婚生子女与婚生子女具有相同的法律地位。非婚生子女不仅有权继承其母亲的遇产，而且有权 继承其生父的遗产，而不论其生父是否认领该非婚生子女。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列关于应收账款周转率的说法，不正确的是（）。 考前绝径', '{"A": "应收账款周转次数=企业销售收入净额/应收账款平均余额", "B": "应收账款周转率包括应收账款周转次数和应收账款周转天数两个指标", "C": "应收账款周转率是反映企业获利能力的指标"}', '["C"]', '应收账款周转次数=企业销售收入净额/应收账款平均余额。应收账款周转次数越多，说明企业应收账款变现能力越强。应收账款周转率包括应收账款周转次数和应收账款 周转天数两个指标。应收账款周转率是反映企业资产运营能力的指标。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于国内家族信托的发展模式，下列选项中属于目前市场主要模式的是）。', '{"A": "基金公司主导模式", "B": "财务公司主导模式", "C": "证券公司主导模式", "D": "商业银行的私人银行主导模式"}', '["D"]', '国内家族信托的发展模式主要有：信托公司主导模式、商业银行私人银行主导模式。故本题选择D选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '根据我国有关规定，一般而言，营业收入规模（）的企业属于中小企业，', '{"A": "100万元-1亿元", "B": "100万元-4亿元", "C": "100万元-3000万元", "D": "100万元以下"}', '["B"]', '我国的中小企业划分标准主要是根据企业从业人员、营业收入。资产总额等指标，结合行业特点而制定的。一般而言，100万-40000万元营业收入规模的企业属于中小企 业，营业收入在100万-3000万元的为小型企业，营业收入在100万元以下的为微型企业。故本题选择B选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '郑先生今年35岁，预计60岁退休，现在税后年净收入20万元，个人年消费支出10万元，考货币的时间价值，预期当前收入增长率5%，通货彭胀率4%，贴现率为6%，按 照生命价值法计算，郑先生需要的寿险保额为（）万元。', '{"A": "421.97", "B": "221.17", "C": "200.79", "D": "321.17"}', '["B"]', '生命价值法：（1）未来收入的现值：20/（6%-5%）[1-(1+5%)/(1+6%）^25)=2000×[1-（1.05/1.06）^25)=2000×（1-0.789）=421.97(万元)。 (2）未来支出的现值：未来支出实际折现率R=(1+6%)/(1+4%)-1=1.9231%，FV=0，PMT=10，n=25，期初年金，带入理财计算器中。PV=200.7978(万元) 郑先生未来25年的净收入为421.97-200.7978=221.1722万元）。故按照生命价值法，郑先生需要寿险保额为221.1722万元。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '关于个人养老金业务，下列说法正确的是（）。', '{"A": "投资者领取环节，适用的税率可能不同", "B": "商业银行满足技术条件后，就可以开办个人养老金业务", "C": "在投资收益环节，不缴纳或暂不缴纳个人所得税"}', '["C"]', '个人养老金：（1）在领取环节，个人领取的个人养老金，不并入综合所得，单独按照3%的税率计算缴纳个人所得税，其缴纳的税款计入“工资、薪金所得”项目，A错 误。（2）开办个人养老金业务的商业银行和理财公司名单由国家金融监督管理总局确定，B错误。在投资收益环节，不缴纳或暂不缴纳个税。C正确：（3）代销个人养 老基金，需要满足包括：最近4个季度末规模不低于5000万元或者上一季度未规模不低于2亿元的养老目标基金，D错误。故本题选择C选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '下列各类家庭支出中属于其他支出的是（）。', '{"A": "专项支出", "B": "理财支出", "C": "家庭日常支出", "D": "礼金支出"}', '["D"]', '家庭支出主要分为三大类，包括家庭生活支出、理财支出和其他支出，家庭生活支出包括家庭日常生活支出和专项支出两个部分。家庭日常生活支出包括在衣、食、住、 行、娱乐休闲。医疗等方面的支出：专项支出包括子女教育和按揭贷款还款。信用卡还款。赚养支出等，理财支出包括因为投资或理财活动的相关支出，如贷款投资资产 和项目的利息支出、保障保费支出。投资理财咨询支出等。其他支出是指上述两大支出之外的支出，如罚款。礼金支出以及其他偶然时间发生的支出，如捐款等。故本题 答案选“礼金支出”， 10', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '要先生今年60岁，妻子55岁，贾先生目前有银行存款20万元。贾先生每年支出5万元，妻子每年支出3万元，目前两人无子女也无老人赠养。用迪属需求法来估算，若配偶 余寿还有20年，以2%折现。贾先生应买人寿保险金额为（）万元。（答案取近似值）', '{"A": "40", "B": "20", "D": "50"}', '["C"]', '产生的资金缺口。根据题意，假设费先生已故，其要子未来生活需要资金多少。期限n=20，利率r=2%，每年支出3万元，属于期初年金C=-3，FV=0，求现值PV，代入 到理财计算器中，求得PV=50.03，然后再减去20万元，得到30.03万元。取近似值，故本题选择C选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张女士的儿子今年10岁，上小学4年级，还有8年读大学。初始有20万元进行投资，大学及研究生学习期间共计6年，目前费用合计为60万元。假设：教育金年增长率为 5%，投资年回报率6%。张女土就有关问题与理财师沟通。根据以上材料。回答下列问题。 理财师在为张女土做规划之前，对张女士家庭的相关情况进行询问。下列选项中，理财师不应涉及的是（）。', '{"A": "张女士的儿子有哪些兴趣爱好", "B": "张女士是否希望其儿子出国留学", "C": "张女士同事的子女教育金筹备情况", "D": "张女士婚姻状况"}', '["C"]', '张女士同事的子女教育金筹备情况和张女士家庭情况没有任何关系，所以不应该涉及。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张女士的儿子今年10岁，上小学4年级，还有8年读大学，初始有20万元进行投资，大学及研究生学习期间共计6年，目前费用合计为60万元，假设：教育金年增长率为 5%，投资年回报率6%，张女士就有关问题与理财师沟通。根据以上材料，回客下列问题。 下列关于教育保险的表述错误的是（）。', '{"A": "有些教育保险可分红，可以尽量多购买", "B": "教育保险具有强制储菌的功能", "C": "保险金额越高，每年需要交付的保费也就越多", "D": "若银行升息，教育保险的回报率可能低于银行存款利率"}', '["A"]', '教育保险具有以下特点： （1）保费免功能，保险金额越高，每年需要交付的保费也就越多，若银行升息。教育保险的回报率可能低于银行存款利率。（2）强制储蓄功能：（3）具有保险的保 障功能：（4）理财分红功能。A项中，虽然有些教育保险可分红，但是也不宜多买，适合孩子的需要就够了。故本题选A。 11', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张女士的儿子今年10岁，上小学4年级，还有8年读大学。初始有20万元进行投资，大学及研究生学习期间共计6年，目前费用合计为60万元。假设：教育金年增长率为 5%，投资年回报率6%。张女士就有关问题与理财师沟通。根据以上材料，回答下列问题。 理财师建议张女土采用基金定投的方式为其儿子筹备学费。下列属于基金定投好处的是（）。', '{"A": "收益率是确定的", "B": "在所有投资方式中，基金定投是最优选择", "C": "没有风险", "D": "可平摊投资成本，降低投资风险"}', '["D"]', '基金定投的好处： 1.操作便捷，基金定投只需投资者去基金代销机构办理一次性的手续，之后每期的扣款申购均自动进行。 2.风险较小，避免投资者对进场时机主观误判，基金定投能获得行业的平均回报，风险较小； 3.回报率稳定，基金定投抵御市场波动的能力很强，回报率稳定，', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张女士的儿子今年10岁，上小学4年级，还有8年读大学。初始有20万元进行投资，大学及研究生学习期间共计6年，目前费用合计为60万元。假设：教育金年增长率为 5%，投资年回报率6%。张女士就有关问题与理财师沟通。根据以上材料，回答下列问题。 若果用基金定投的方式，为达到积累数育金的目标，张女士每月初至少还需要投入（）元。（答案取近似数值）', '{"A": "5800", "B": "4600", "C": "5000", "D": "5500"}', '["B"]', '根据题意，20×（1+6%）^8=31.88（万元）：60×（1+5%）^8=88.65（万元），资金缺口为88.65-31.88=56.77（万元）。转化为已知终值求期初年金，n=96， 『r=6/12，PV=0，FV=56.77.代入到理财计算器中，求得PMT=4599。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年35岁，任职天津某公司副总经理，税后年收入40万元。其妻王太太今年33岁，年税后收入30万元。女儿5岁。家庭生活开支每年35万元，其中王先生年支出 20万元 家庭财产情况：银行活期存款50万元，定期存款120万元，股票型基金市值100万元，自住房产价值500万元，贷款余额90万元，还有5年还清。王先生夫妇均为独生子 女，父母均健在，目前每年需要赚养费共计12万元，预计持续15年，王先生只有张保额50万元的团体定期人寿保险，王太太和女儿没有任何保险。根据以上材料，回答 下列问题。 王先生有恐高症，因此他选择不坐飞机，改乘火车出行，其做法属于（）风险。', '{"A": "转移", "B": "自留"}', '["D"]', '风险回避是指考虑到影响预定目标达成的诸多风险因素，结合决策者自身的风险偏好性和风险承受能力，从而做出的中止、放弃某种决策方案或调整、改变某种决策方 案的风险处理方式。 12', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年35岁，任职天津某公司副总经理，税后年收入40万元。其妻王太太今年33岁，年税后收入30万元。女儿5岁。家庭生活开支每年35万元，其中王先生年支出20 万元 家庭财产情况：银行活期存款50万元，定期存款120万元，股票型基金市值100万元，自住房产价值500万元，贷款余额90万元，还有5年还清。王先生夫妇均为独生子女 父母均健在，目前每年需要赠养费共计12万元，预计持续15年。王先生只有张保额50万元的团体定期人寿保险，王太太和女儿没有任何保险。根据以上材料。回答下列问 题。 王先生的团体定期人寿保险合同的双方当事人是（）。', '{"A": "王先生，女儿", "B": "保险公司，王先生任职公司", "C": "王先生，王太太", "D": "保险公司，王先生"}', '["B"]', '团体人寿保险是以团体作为被保人的一种人寿保险，是由团体进行投保，以团体成员作为被保人，是一张总保单作为保障的团体成员损供的死亡保障。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年35岁，任职天津某公司副总经理，税后年收入40万元。其妻王太太今年33岁，年税后收入30万元，女儿5岁，家庭生活开支每年35万元，其中王先生年支出 20万元， 家庭财产情况：银行活期存款50万元，定期存款120万元，股票型基金市值100万元，自住房产价值500万元，贷款余额90万元，还有5年还清，王先生夫妇均为独生子 女，父母均健在，目前每年需要赠养费共计12万元，预计持续15年，王先生只有张保额50万元的团体定期人寿保险，王太太和女儿没有任何保验。根据以上材料，回答 下列问题。 关于王先生家庭的财富保障描述，错误的是（），', '{"A": "王先生需要健康保险", "B": "王先生应该加保人寿保险", "C": "缺少家庭财产保险", "D": "王太太不需要人寿保险"}', '["D"]', '根据题干“王先生只有张保额50万元的团体定期人寿保险，王太太和女儿没有任何保险。“表述，王太太和女儿是需要保险的。所以选项“王太太不需要人寿保险” 说法错误。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年35岁，任职天津某公司副总经理，税后年收入40万元。其妻王太太今年33岁，年税后收入30万元。女儿5岁。家庭生活开支每年35万元，其中王先生年支出 20万元 家庭财产情况：银行活期存款50万元，定期存款120万元，股票型基金市值100万元，自住房产价值500万元，贷款余额90万元，还有5年还清。王先生夫妇均为独生子 女，父母均健在，目前每年需要养费共计12万元，预计持续15年。王先生只有张保额50万元的团体定期人寿保险，王太太和女儿没有任何保险。根据以上材料，回答 下列问题。 健康保险不包括（）。 ●A.医疗保险', '{"B": "护理保险", "C": "意外伤害保险", "D": "重大疾病保险"}', '["C"]', '健康保险主要包括医疗保险、疾病保险、失能收入损失保险、护理保险以及医疗意外保险等。意外伤害保险是以被保险人的身体为保验标的，以意外伤害而致被保验人 身故或残疾为给付保险金条件的一种人身保险。如普通意外伤害保险、特定意外伤害保险等。 13', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '王先生今年35岁，任职天津某公司副总经理，税后年收入40万元。其妻王太太今年33岁，年税后收入30万元。女儿5岁。家庭生活开支每年35万元，其中王先生年支出 20万元。 家庭财产情况：银行活期存款50万元，定期存款120万元，股票型基金市值100万元，自住房产价值500万元，贷款余额90万元，还有5年还清。王先生夫妇均为独生子 女，父母均健在，目前每年需要赠养费共计12万元，预计持续15年。王先生只有张保额50万元的团体定期人寿保险，王太太和女儿没有任何保险。根据以上材料，回答 下列问题。 假设王先生60岁退休，收入增长率为5%，通货膨胀率为4%，贴现率为6%，按生命价值法计算，王先生合理的寿险保额为（）万元。（答案取近似值）', '{"A": "400", "B": "586", "C": "443", "D": "90"}', '["C"]', '生命价值法又称净收入弥补法，是以家庭成员的生命价值为依据，来确定家庭寿险保额的基本方法。具体做法是：从个人未来所有收入中扣除个人全部税费，再以适的 贴现率计算预期净收入的当前现值，从而得出如果家庭失去该成员的收人，其家庭未来生活收入的缺口现值。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户购买了X基金，当前无风险收益率为6%，X基金过去表现与市场组合的历史表现如下所示： X基金 历史指标 市场组合 平均收益率（%） 18 16 标准差（%） 20 25 β值 1.2 从詹森指数角度研究X基金，下列表述正确的是（）。', '{"A": "X基金的投资组合的收益高于市场平均水平", "B": "X基金的投资组合的收益等于市场平均水平", "C": "X基金的投资组合的收益低于市场平均水平", "D": "X基金的投资组合标准差低于市场组合是詹森指数好的前提"}', '["B"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户购买了X基金，当前无风险收益率为6%，X基金过去表现与市场组合的历史表现如下所示： 历史指标 x基金 市场组合 平均收益率（%） 18 16 标准差（%) 20 25夹取 β值 1. 2 从特雷诺指数角度研究X基金，下列表述正确的是（）。', '{"A": "市场组合单位风险的平均超额收益率是0.1", "B": "X基金的特雷诺指数数值大于市场组合的特雷诺指数数值", "C": "X基金单位风险的平均超额收益率是负数", "D": "X基金单位风险的平均超额收益率是0"}', '["A"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户购买了X基金，当前无风险收益率为6%，X基金过去表现与市场组合的历史表现如下所示： 历史指标 X基金 市场组合 平均收益率（%） 18 16 标准差（%） 20 25 β值 1.2 Y基金夏普比率是0.9，Z基金夏普比例是0.3，理财师从夏普比率角度应该向客户推荐（）。', '{"A": "X基金", "B": "Y基金", "C": "Z基金", "D": "市场组合"}', '["B"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户购买了X基金， 当前无风险收益率为6%，X基金过去表现与市场组合的历史表现如下所示： 历史指标 x基金 市场组合 平均收益率（%） 18 16 标准差（%） 20 25 β值 1.2 下列表述中正确的是（）。', '{"A": "特雷诺指数的理论基础是套利定价理论", "B": "夏普比率的理论基础是资本资产定价模型", "C": "詹森指数的理论基础是均值方差模型", "D": "特雷诺指数、詹森指数和夏普比率的理论基础都是有效市场假说"}', '["B"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '客户购买了X基金，当前无风险收益率为6%，X基金过去表现与市场组合的历史表现如下所示 历史指标 x基金 市场组合 平均收益率（%） 18 16 标准差（%） 20 25 β值 1.2 理财师对基金投资风格进行分析，并每月为客户提供分析报告，这最不可能用的分析方法是（）。', '{"A": "基于基金持仓股票的风格分析", "B": "基本面分析", "C": "技术面分析", "D": "基于基金收益的风格分析"}', '["D"]', '基于基金收益的风格分析不适用于短期内风格的变化，本题中“每月为客户提供分析报告”，所以最不可能用的分析方法是基于基金收益的风格分析。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生今年50岁，预计10年后退休，目前年生活开支约20万元。为保障退休后的生活质量，张先生计划一次性拿出200万元投资一款养老型理财产品。 假设张先生的预期寿命为80岁，投资上述养老型理财产品的年化收益率约在4-5%之间，未来的通货膨胀率约为2-3%。 根据以上材料，回答以下问题。 （1）张先生退休后，上述养老型理财产品的实际年化收益率最高为（）。（答案取近似数值）', '{"A": "5%", "B": "3%", "C": "2.94%", "D": "0.97%"}', '["C"]', '实际年化收益率=［（1+名义利率）/（1+通货能胀率）1-1，所以（1+4%）/（1+3%）-1=0.97%，（1+5%）/（1+3%）-1=1.94%，（1+4%）/（1+2%）-1=1.96%， （1+5%）/（1+2%）-1=2.94%，最高为2.94%，故本题选择C选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生今年50岁，预计10年后退休，目前年生活开支约20万元。为保障退休后的生活质量，张先生计划一次性拿出200万元投资一款养老型理财产品。 假设张先生的预期寿命为80岁，投资上述养老型理财产品的年化收益率约在4-5%之间，未来的通货能胀率约为2-3%。 根据以上材料，回答以下问题。 (2）张先生退休时至少可积累养老金（）万元。（答案取近似数值）', '{"A": "220.27", "B": "325.78", "C": "267.22", "D": "296.05"}', '["D"]', '根据题目。求可积累养老金，是看在5%的投资收益率的情况下，能揽多少钱。是求养老金的供给，此时不需要考虑通货能胀率，而在求养老金需求的时候则需要考虑通货能胀 率。因为是至少，所以利率用4%，FV（n=10，I=4%。PV=-200，C=0，期末模式）=296.05万元。故本题选择D选项。 16', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生今年50岁，预计10年后退休，目前年生活开支约20万元。为保障退休后的生活质量，张先生计划一次性拿出200万元投资一款养老型理财产品。 假设张先生的预期寿命为80岁，投资上述养老型理财产品的年化收益率约在4-5%之间，未来的通货影胀率约为2-3%。 根据以上材料，回答以下问题。 （3）若想退休后仍维持当前的生活水平，在没有其它养老金来源的情况下，张先生退休时的养老金缺口最少有（）万元。（答案取近似数值） O.C.18.81', '{"B": "38.95", "D": "49.68"}', '["A"]', '因为问的是最少，所以通货能影胀率用2%，那么，退休时点的生活支出为20×（1+2%）^10=24.38，退休后20年的总支出折现到60岁时点，PV（FV=0，C=-24.38， [=2.94%，几=20，期初年金）=375.46。375.46-296.05=79.41，所以取近似值，为80.84，故本题选择A选项。【如何区分期初期未：首先要看题目有没有给出期初（年 初）、期末（年底、年末）投资这样的字眼，如果有的话，需要根据题目要求选择期初和期末。如果没有，一般默认是期末，期初需要记住几个爱考的，房租、养老金支出、 生活费支出，看到这几个就选期初，复利问题直接默认勾选期未即可。1', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生今年50岁，预计10年后退休，目前年生活开支约20万元。为保障退休后的生活质量，张先生计划一次性拿出200万元投资一款养老型理财产品， 假设张先生的预期寿命为80岁，投资上述养老型理财产品的年化收益率约在4-5%之间，未来的通货能胀率约为2-3%。 根据以上材料，回答以下问题。 （4）为弥补养老金缺口，张先生计划通过个人养老金账户进行定投。假设张先生个人养老金账户的投资收益率与上述养老型理财产品相同，不考虑领取时税收政策的情况下，贝 张先生需在每月未至少投入资金（）万元。（答案取近似数值）', '{"A": "0.55", "B": "0.27", "C": "0.32", "D": "0.13"}', '["A"]', '由于问的是每月利率要转化成月，4%/12=0.3333，期数=10*12=120，每月末至少投入万元C=（I=0.3333%，n=120，FV=80.84，PV=0，期末模式）=0.549，取近似 值，故本膜选择A选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '张先生今年50岁，预计10年后退休，目前年生活开支约20万元。为保障退休后的生活质量，张先生计划一次性拿出200万元投资一款养老型理财产品。 假设张先生的预期寿命为80岁，投资上述养老型理财产品的年化收益率约在4-5%之间。未来的通货能胀率约为2-3%， 根据以上材料，回以下问题。 （5）根据《国务院办公厅关于推动个人养老金发展的意见》，个人养老金资金账户实行封闭运行，参加人一次性领取个人养老金的条件不包括（）。', '{"A": "完全丧失劳动能力", "B": "达到领取基本养老金年龄", "C": "出国定居"}', '["D"]', '个人养老金资金账户实行封闭运行，未满足领取条件的，不得支取资金。参加人达到以下任一条件的，可以按月、分次或者一次性领取个人养老金：（1)达到领取基本养老金年 龄；(2)完全丧失劳动能力：(3)出国（境)定居：(4)国家规定的其他情形，故本题选择D选项。 17', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '李先生女儿今年8岁，预计10年后出国留学，目前情况下留学学费每年15万，生活费每年8万，李先生拟用30万作为女儿教育金的初始资金，并且每年年末投入固定一笔资金，李 先生打算一次性准备好女儿上大学的费用，投资回报率是3%，大学学制4年，学费增长率2%，通货能胀率1%，生活费增长率2%，不考虑上大学期间的费用增长与教育金的投资 问题。 在女儿上大学时，李先生需要筹集学费、生活费合计约为（）万元。（答案取近似数值）', '{"A": "108.49", "B": "136.65", "C": "112.15", "D": "157.84"}', '["C"]', '学费：15×（1+2%）^10=18.28万元，生活费：8万×(1+2%）^10=9.75万元，不考惠上大学期间的费用增长与教育金的投资问题，所以18.28×4=73.12万，9.75×4=39万， 73.12+39=112.12，取近似值，故本题答案选择C选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '李先生女儿今年8岁，预计10年后出国留学，目前情况下留学学费每年15万，生活费每年8万，李先生拟用30万作为女儿教育金的初始资金，并且每年年末投入固定一笔资金，李 先生打算一次性准备好女儿上大学的费用，投资回报率是3%，大学学制4年，学费增长率2%，通货能账率1%，生活费增长率2%。不考虑上大学期间的费用增长与教育金的投资 问题， 李先生用30万初始资金进行投资，投资回报率3%，预计10年后有）万元。', '{"A": "60.12", "B": "36.57", "C": "40.32", "D": "37.93"}', '["C"]', '复利终值公式FV=PV×(1+r)^n，PV=30万，r=3%，n=10,FV=30×(1+3%)^10=30×1.3439=40.32万，答案选C', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '李先生女儿今年8岁，预计10年后出国留学，目前情况下留学学费每年15万，生活费每年8万，李先生以用30万作为女儿教育金的初始资金，并且每年年未投入固定一笔资金，李 先生打算一次性准备好女儿上大学的费用，投资回报率是3%，大学学制4年，学费增长率2%，通货能胀率1%，生活费增长率2%。不考患上大学期间的费用增长与教育金的投资 问题。 为准备好女儿留学资金，李先生现在需一次性投入（）万元。（答案取近似数值）', '{"A": "60.76", "B": "83.45", "C": "80.71", "D": "98.12"}', '["B"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在，刘先生2016年开始持有某上市公司22.5 限售股权，该公司上年未资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元。刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款， 资了信托产品200万元，银行理财产品50万元，国债50万元，紫砂壶、字画等艺术品估值100万元，活期存款10万元。张女士名下房产市值300万元，贷款余额55万元，按 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元。 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合 75万元 刘先生有一份上一段婚姻时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿 投保了一份子女教育金保险，保额100万元。 关于刘先生家庭财务状况的分析中，错误的是（）。', '{"A": "刘先生家现金资产配备充足，但资产流动性较差", "B": "刘先生家庭收入受所在上市公司业绩影响较大，应提高理财收入比重", "C": "刘先生属于高净值客户家度，资产负债率低，可以适当提高负债比率", "D": "张女士个人未投保任何保险，应增加养老与医疗方面的保险保障"}', '["A"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在，刘先生2016年开始持有某上市公司22.5%的 限售股权，该公司上年末资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元。刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款，其投 资了信托产品200万元。银行理财产品50万元，国债50万元，紫砂壶。字画等艺术品估值100万元，活期存款10万元。张女士名下房产市值300万元，贷款余额55万元，按月 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元。 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元 刘先生有一份上一段婚姻时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 投保了一份子女教育金保险，保颖100万元。 关于张女士给儿子投保的子女教育年金保险，下列表述正确的是（）。', '{"A": "如果张女士身故或者全残，可以超免未交保费，保单持续有效", "B": "教育金保险要一次性给付", "C": "其儿子如果身故，可以理赔100万元", "D": "张女士如果中途退保。可以获得100万元"}', '["A"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在，刘先生2016年开始持有某上市公司22.5%的 限售股权，该公司上年末资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元。刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款，其投 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元。 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取脱后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有谢资收入来源，刘先生家庭年支出合计为 75万元 刘先生所在的上市公司依照规定代扣代缴“三险一金”，张女士未参加社保。 刘先生有一份上一段婚姻时以刘先生为被保验人，保额500万元的终身寿险，购买时，该保验并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 投保了一份子女教育金保险，保额100万元。 张女士若将股票账户清空后得到的40万元现金全部用于归还银行房贷本金，其他贷款条件不变，则每月未还款金额可减少（）元。（答案取近似数值）', '{"A": "2945", "B": "2617", "C": "2405", "D": "2315"}', '["B"]', '19', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前抚养，刘先生父母均健在。刘先生2016年开始持有某上市公司22.5%的 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元， 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元 刘先生有一份上一段婚姻时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 投保了一份子女教育金保险，保额100万元。 假设刘先生每年初需要支付给前要6万元抚养费，直至15年后女儿大学毕业，若刘先生现在将抚养费一次性支付给其前麦，年投资报酬率为8%，则至少需要准备（）万元。 （答案取近似数值）', '{"A": "73.28", "B": "55.47", "C": "51.36", "D": "62.56"}', '["B"]', '', 5);
