INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在，刘先生2016年开始持有某上市公司22.5%的 限售股权，该公司上年末资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元。刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款，其投 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元。 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元 刘先生有一份上一段婚烟时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 根据家庭实际情况和涨女士现有保章，以下保险规划建议最不适合的是（）。', '{"A": "将以刘先生为被保险人的终身寿险退保，节省下来的保费用于给张女士的终身寿险", "B": "计算保费合理预算和保额，以张女士自己为被保验人，投保定期寿险，意外险、重疾险、医疗险、寿险的受益人指定为儿子", "C": "张女士以灵活就业人员身份参加社会保险，按期缴纳基本养老保险费和基本医疗保险费", "D": "刘先生为家庭经济支柱，应适当增加寿险保额"}', '["A"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在，刘先生2016年开始持有某上市公司22.5%的 限售股权，该公司上年末资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元。刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款，其投 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元。 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元 刘先生有一份上一段婚烟时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 投保了一份子女教育金保险，保额100万元，包1 在分析和结算张女士个人寿险需求时，下列说法错误的是（），', '{"A": "张女士无个人首先保障需求下，因为家庭经济支柱为刘先生，且家庭生息资产能覆盖家庭需求缺口", "B": "虽然张女士无薪资收入，但不代表张女士无个人首先需求，在选择其他首先需求结算方式时不宜选择生命价值法", "C": "运用倍数法则估算张女士家庭保障需求，目前家庭寿险保障不足但家度保费支出已经超标，因此不需要再为张女士配备个人寿险", "D": "考虑到张女士有带儿子移民的想法，张女士应该将部分资产境外化，通过海外SPV架构涉及，私下提前将家庭部分资产转移至海外"}', '["C"]', '', 5);
