INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在。刘先生2016年开始持有某上市公司22.5%的 限售股权，该公司上年末资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元。刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款，其投 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元 刘先生有一份上一段婚姻时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 投保了一份子女教育金保险，保额100万元， 刘先生作为委托人设立家族信托，下列说法中错误的是（），', '{"A": "可以通过家族信托进行风险隔离", "B": "刘先生可以作为受益人之一，也可以作为唯一的受益人", "C": "家庭财富的保护是家族信托的主要目的之一", "D": "家族信托财产金额可以为1200万元"}', '["B"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在。刘先生2016年开始持有某上市公司22.5%的 限售股权，该公司上年末资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元。刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款，其投 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元。 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元。 刘先生所在的上市公司依照规定代扣代缴“三险一金”，张女士未参加社保。 刘先生有一份上一段婚姻烟时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 投保了一份子女教育金保险，保额100万元。包！ 刘先生有意购买某私募证券投资基金，关于私募证券投资基金，下列说法错误的是（）。', '{"A": "私募证券投资基金募集完成后在进行备案", "B": "私募证券投资基金不得承诺保本收益，但是通过承诺预期收益等来保本保收益", "C": "私募证券投资基金不得通过公众媒体或公开方式向社会大众宣传推介", "D": "根据相关认定标准，刘先生属于合格投资者"}', '["B"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在。刘先生2016年开始持有某上市公司22.5%的 限售股权，该公司上年末资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元。刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款，其投 资了信托产品200万元，银行理财产品50万元，国债50万元，紫砂壶、字画等艺术品估值100万元，活期存款10万元。张女士名下房产市值300万元，贷款余额55万元，按月 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元。 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元 刘先生有一份上一段婚烟时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 投保了一份子女教育金保险，保额100万元，包 关于刘先生投资股票、股权及理财产品设计到的税务问题，理财师的下列说法中，正确的是（》，', '{"A": "刘先生若投资股票获利，需要就投资收益缴纳增值税", "B": "刘先生投资理财产品所获得的投资收益无需缴纳增值税", "C": "刘先生若通过股权投资获得收益，需要缴纳增值税", "D": "刘先生若通过股权投资获得收益，需要缴纳个人所得税"}', '["B"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项》刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在。刘先生2016年开始持有某上市公司22.5%的 限售股权，该公司上年末资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元。刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款，其投 资了信托产品200万元，银行理财产品50万元，国债50万元，紫砂壶、字画等艺术品估值100万元，活期存款10万元。张女士名下房产市值300万元，贷款余额55万元，按月 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元， 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元， 刘先生有一份上一段婚姻烟时以刘先生为被保验人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 若张女士与刘先生离婚，关于张女士家庭资产的分割。下列说法正确的是（），', '{"A": "刘先生四套房产中的家庭自住住宅，应属于张女士和刘先生的夫妻共同财产，若离婚，张女士可分得50%份额", "B": "刘先生婚前购买的房产应属于刘先生个人财产，但房产的自然增值部分应属于夫妻共同财产，张女士可份额自然增值部分50%份额", "C": "刘先生婚前房产的租金收益应不属于刘先生个人所有，张女士参与分割", "D": "张女士名下的房产，由于婚后用家庭共同财产还贷，张女士无法独享财产权利"}', '["D"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在，刘先生2016年开始持有某上市公司22.5%的 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元。 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元 刘先生所在的上市公司依照规定代扣代缴“三险一金”，张女士未参加社保。 刘先生有一份上一段婚姻时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 投保了一份子女教育金保险，保额100万元。 张女士听从理财师建议，从现在开始以自由职业者的身份参加基本养老保险，每年以上年度职工月平均工资为缴费基数，连续缴纳社保30年，则可以在55岁退休时领取基本养 老金，假设张女士所在地区社会平均工资年平均增长率为3%，退休时月平均缴费工资指数为1，上一年度当地社会平均工资为每月3500元，退休时张女士个人账户的积累额为 237541.80元，则张女士55岁退休后第一个月可以领取的基本养老金为（）元。（55岁退休计发月数为170，答案取近似数值）', '{"A": "1342", "B": "5763", "C": "2099"}', '["D"]', '', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('single', '【综合题】（不定项）刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在，刘先生2016年开始持有某上市公司22.5%的 限售股权，该公司上年末资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元，刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款，其投 资了信托产品200万元，银行理财产品50万元，国债50万元，紫砂壶、字画等艺术品估值100万元，活期存款10万元。张女士名下房产市值300万元，贷款余额55万元，按月 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元。 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元。 刘先生有一份上一段婚姻时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 投保了一份子女教育金保险，保额100万元。 保险金信托作为一项新兴的财富传承工具收到了刘先生的关注，下列关于保险金信托的说法中，错误的是（），', '{"A": "人寿保险的受益人，需要同时是信托计划的受益人和信托计划本身，保险金信托才能设立", "B": "不是所有的保险产品都可以纳入保险金信托", "C": "保险金信托的起点金额可以为100万元人民币", "D": "保险新信托一般为他益信托，以家庭财富的保护、传承和管理等为目的而设立"}', '["C"]', '人寿保险的受益人，需要同时是信托计划的受益人和信托计划本身，保险金信托才能设立，A正确；不是所有的保险产品都可以纳入保险金信托，B选项正确。保险金信托的 起点金额一般为500万元人民币，C错误。保险金信托一般为他益信托，以家庭财富的保护、传承和管理等为目的而设立，D正确，', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '在下列客户的支出规划项目中，属于弹性较小的支出有（）。', '{"A": "休闲旅游支出", "B": "礼金支出", "C": "子女教育支出", "D": "理财支出", "E": "医疗支出"}', '["C", "D", "E"]', '教育支出属于家庭的专项支出，孩子到了一定年龄就必须步入校园接受教育，因此教育支出时间比较刚性，弹性较小，C选项正确。医疗支出属于家庭的日常生活支出，一旦生 病就必须支付的费用，比较性，弹性较小，E选项正确。理财支出，费用数额与缴费时间是固定不变的。比较网性；礼金支出、旅游支出属于家庭生活日常支出，可以根据家 庭的实际财务状况进行调整。故本题答案选CDE。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于健康保险的表述，正确的有（）。', '{"A": "保证续保条款，是指在前一保险期间届满前，投保人提出续保申请，保险公司必须按照原条款和约定费率维续承保的合同约定", "B": "短期健康保险是指保险期间为一年以及一年以下且不含有保证续保条款的健康保险", "C": "健康保险按保险期限分为长期健康保险和短期健康保险", "D": "长期护理保险保险期间不得低于3年", "E": "长期健康保险保险期间一定要超过1年"}', '["A", "B", "C"]', '（1）保证续保条款，是指在前一保险期间届满前，投保人提出续保申请。保险公司必须按照原条款和约定费率继续承保的合同约定。 （2）长期健康保险，是指保险期问超过1年或者保险期问量不超过1年但含有保证续保条款的健康保险，长期健康保险保险期问不得低于5年。短期健康保险，是指保险期问为 1年以及1年以下且不含有保证续保条款的健康保险。 （3）护理保险的保险金给付期限通常有1年、数年直至终身等方式可供客户选择。同时，也规定有天数不等的免责期。故本题答案除了不选“长期护理保险保险期间不得低于 3年”和“长期健康保险保险期间一定要超过1年”以外。其他的全选。 24', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '流动性资产的主要特征有（），', '{"A": "流动性弱", "B": "收益率较低", "C": "安全性高", "D": "主要目的为获得投资收益", "E": "流动性强"}', '["B", "C", "E"]', '流动性资产的主要特征：（1）流动性强；（2）安全性高：（3）利息收入低（也就是收益率低），故本题答案选“收益率较低、安全性高和流动性强”。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '一般来说，女性的退休养老金需求高于男性，退休规划也应该更早制定，造成这一现状的原因主要有（。', '{"A": "女性的更有爱心，乐于助人捐助花费较多", "B": "女性的风险偏好程度较低，更愿意选择保守的投资理财方式", "C": "女性平均寿命高于男性", "D": "女性的消费观念比男性强，花销比男性多"}', '["B", "C", "E"]', '一般来说，女性的退休养老金需求高于男性。退休规划也应该更早制定。造成这一现状的原因主要有三点：一是女性平均寿命高于男性：二是女性在工作期间平均收入低于男 性，形成收入差距；这种差距既会影响职业生涯的财富积累，也会影响到退休后相关收入的获得（如企业年金、养老金等）：三是女性的风险偏好程度较低，更愿意选择保守 的投资理财方式。故本题答案除了不选“女性的更有爱心”和“女性的消费观念比男性强”以外，其他的全选。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '在其他条件相同情况下，下列关于年金产品价格的说法中，正确的有（），', '{"A": "纯粹终身年金比金额保底终身年金价格高", "B": "期间保底终身年金比纯粹终身年金价格高", "C": "延期年金比即期年金价格高", "D": "延期年金比即期年金价格低", "E": "期间保底终身年金比金额保底终身年金价格高"}', '["B", "C"]', '终身年金是指年金受领人在一生中可以一直领取约定的年金，直到死亡为止的年金保险。终身年金按种类可分为纯粹终身年金（普通终身年金）、期间保底终身年金、金额 保底终身年金。纯粹终身年金或称营通终身年金仅在年金领取人生存期间定期给付的年金，即只有被保险人生存才可以按期领取年金。如果被保险人死亡，则保险公司停止 年金给付，保险责任终止，期间保底终身年金，这种年金保证在年金领取人生存期间定期给付年金，并保证给付期间不少于约定期间。保底期间过后，则成为纯粹终身年 金，即被保险人死亡则年金支付停止。显然，保底期间越长。保费越高，B正确。金额保底终身年金，这种年金保证在年金领取人生存期间定期给付，并保证年金给付总额至 少等于一个合同约定的金额。保底金额过后，则成为纯粹终身年金，即被保险人死亡则年金支付停止。期间保底终身年金与金额保底终身年金均属于返还型年金，两者价格 无法比较，E错误。金额保底络身年金当保底金额过后即成为纯粹终身年金，纯粹终身年金比金额保底终身年金价格低，A错误。即期年金和延期年金是两种不同类型的养老 金计划。即期年金是指在退休后立即开始支付的养老金，而延期年金是指在退休后延迟一段时间开始支付的养老金，即期年金是最常见的养老金计划之一。它的优点是退休 25', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '遗产的特征包括（） ■A.必须是合法财产', '{"B": "必须是公民死亡时遗留的财产", "C": "必须是有确定继承人的财产", "D": "必须是公民个人所有的财产", "E": "不包括公民生前所签的个人债务"}', '["A", "B", "D"]', '遗产的特征包括：必须是合法财产；必须是公民死亡时遗留的财产；必须是公民个人所有的财产。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列方式中，适合用于教育投资积累的形式包括（）。', '{"A": "长期进行基金定投", "B": "按月定额存款", "C": "设立专用账户，定期存入", "D": "期初估算费用，一次性留足", "E": "接近费用支出时临时筹措"}', '["B", "C", "D"]', '教育投资积累的形式包括按月定额存钱（B正确）、一次性投资，期初估算费用。一次性留足（D正确）、鼓励子女自行理财，开立账户将压岁钱与零花钱存入（C正确）。故 本题选择BCD选项', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '企业职工基本养老保险的资金筹集来源包括（）。', '{"A": "财政支付", "B": "基金运营收入", "D": "个人薪研扣除", "E": "保险公司融资"}', '["A", "B", "C", "D"]', '企业职工基本养老保险制度的资金筹集来源主要包括五个方面：企业缴费（C正确）、个人薪耐扣除（D正确）、财政支付（A正确）、基金运营收入（B正确）和其他补贴。 故本题选择ABCD选项 26', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '关于家庭收支状况的分析，说法正确的有（），', '{"A": "紧急预备金额度通常为家庭月支出的2-3倍", "B": "包括收支盈余情况分析、财务自由度的分析、收入支出结构分析和应急能力分析", "C": "如果统计年度出现“其他收入，则应该考虑排除“其他收入”后，当年收支是否能够得以平衡或出现盈余", "D": "自由结余占比越大，客户的结余使用效率越高", "E": "工作收入的占比越大，说明家庭对工作收入的依赖性就越大"}', '["B", "C", "E"]', '（1）紧急预备金额度通常为家庭月支出的3-6倍，所以选项“2-3倍”说法错误； （2）通常而言，自由结余是总结余减去专项结余总额，这是未经处理的结余额度，自由结余占总结余的比率过高，往往体现出较低的理财积极性；同时自由结余也是可以用 于实现短期理财目标的资金。自由结余占比越大，客户的结余使用效率越低，所以选项“自由结余占比越大，客户的结余使用效率越高”说法错误。 （3）家庭收支状况的分析包括收支盈余情况分析、财务自由度的分析、收入支出机构分析和应急能力分析。收支盈余情况分析：如果统计年度出现“其他收入”，则应该考 虑排除“其他收入”后，当年收支是否能够得以平衡或出现盈余，这是因为“其他收入”通常不是持续的收入。同时收入支出表也直观地体现了生活结余和理财结余的盈余 情况。所以两个选项“应急能力分析”和“其他收入”说法正确。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '客户满意度提升的重要性体现在（）。', '{"B": "客户对商家不满将导致客户离开", "C": "客户满意度提升能够促使企业利润提升", "D": "客户满意度提升可促使客户反复购买", "E": "客户不满意时，会将不满告诉身边的人从而导致商家美普度降低"}', '["A", "B", "C", "D", "E"]', '为得到的关怀不够，B选项正确。（4)93%的CEO认为客户关系管理是企业成功和更富有竞争力的最重要因素：（5）据统计，最具客户满意度的公司增长的市值是客户满意度最', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于基本养老保险金资金筹集的表述，不正确的有（）。', '{"A": "企业缴费部分全国统一为20%", "B": "资金筹集来源只有企业缴费、个人薪扣除和其他补贴三方面", "C": "员工个人缴费基数通常是经过核定的上年度本人月平均工资，费率为12%", "D": "企业缴费和个人薪自扣除为资金筹集最重要的来源", "E": "员工个人缴费基数为全国职工上年度月平均工资的300%"}', '["A", "B", "C", "E"]', '要包含五个方面：企业缴费、个人薪耐扣除、财政支付、基金运营收入和其他补贴，所以选项“资金筹集来源”表述错误：员工个人缴费基数通常是经过核定的上年度本人月 %09%00% 所以选项“月平均工资的300%”选项表述错误。 27', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列属于财富传承中死亡转移的有（）。', '{"A": "遇赠", "B": ",赠予", "C": "为受益人创建不可撤销信托", "D": "遗喝信托", "E": "遇嘱继承"}', '["A", "D", "E"]', '在财富传承的工具中，死亡转移的包括：遗喔继承、遗赠、遗信托。故本题答案选“遗赠、遗嘱继承和遗喝信托”。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '资本资产定价模型的基本假设包括（）。 ■B.投资者希望财富越多越好 ■C.影响投资者决策的主要因素是收益性、安全性、流动性', '{"A": "投资者寻求同一风险水平下，选择资产收益率较高的水平下，同一收益率下，选择风险水平较低的证券", "D": "投资的风险主要用风险溢价来衡量", "E": "事先知道投资收益率的分布是正态分布"}', '["A", "B", "D", "E"]', '资本资产定价模型是建立在马柯维茨模型的基础上，马柯维茨模型的假定也包含 其中： (1)投资者希望财富越多越好，效用是财富的函数，财富又是投资收益率的函数，因此可以认为效用为收益率的函数。 (2)投资者能事先知道投资收益率的概率分布为正态分布。 (3)投资风险用投资收益率的方差或标准差表示。 (4)影响投资决策的主要因素为期望收益率和风险两项。 (5)投资者都遵守主宰原则(DominanceRule),即同一风险水平下，选择收益率较高的证券；同一收益率水平下，选择风险较低的证券。 资本资产定价模型的附加假设条件：', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '一般而言，获利能力指标主要包括（）等财务指标。', '{"A": "基本获利率", "B": "存货周转率", "C": "实收资本利润率", "D": "应收账款周转率", "E": "销售净利润率"}', '["A", "C", "E"]', '28', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列服务中，属于理财师找准客户兴趣点或价值取向的有（）。', '{"A": "对高净值客户提供保险、信托等有效规避遗产税和家庭财务纠纷的服务", "B": "对专业人士提供资产配置、退休养老规划等，体现高度的专业水平", "C": "为贵宾客户提供专属、私密的办理业务空间，让其感觉被尊重和具有差异化", "D": "对私营企业主客户提供财富保障、资产传承方面的规划服务", "E": "对高端客户提供旅游、养生、艺术品收藏等提升生活品质的增值服务"}', '["A", "B", "C", "D", "E"]', '提供有价值的客户服务：（1）我国高净值客户对于财富传承工具的需求较为追切，国内各家商业银行及金融机构也在积极开展家族信托业务以满足高净值客户的此类需求，能 够实现资产保值以及财富传承等功能。A正确。（2）专业人土相对更需要退休养老规划、保验规划、投资规划(资产配置）.比较强调理财师工作服务的专业性、规范性和时效 性。B正确。（3）为贵宾客户提供专属、私密的办理业务空间，让其感觉披尊重和具有差异化。C正确。（4）私营企业主比较关注财富保障、传承和子女教育等方面的规划服 务。D正确。（5）许多高端客户，尤其私营企业主在财富积累到一定程度之后，更加关注生活品质的享受，而银行能为客户提供的信息或服务可谓调方方面面，当下以留学、移 民、旅游、艺术品收藏、养生、风水国学讲座、奢侈品鉴赏、家族信托、全球资产配置等最为热门话题。E正确。故本选择ABCDE选项。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '家庭债务管理状况的分析主要包括（），', '{"A": "资产负债率分析", "B": "偿债能力分析", "C": "融资比率分析", "D": "社会地位分析", "E": "负债结构分析"}', '["A", "B", "C", "E"]', '家庭债务管理状况的分析是专业理财师对客户进行家庭债务管理，并提供相关专业建议的基础和前提，它主要包括理财师对收入支出结构表和资产负债表中的相关数据进行分 析后得到的结论。它能帮助理财师比较清断地了解客户在统计年度的债务管理情况其中包括家庭资产负债率分析、融资比率分析。负债结构分析、偿债能力分析等内容。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于转继承与代位继承的表述，正确的有（）。', '{"A": "代位继承和继承均只能发生在法定继承程序中", "B": "转继承实际上发生了两次继承而代位继承只发生了一次继承", "C": "转继承人在继承发生前就是被继承人的继承人，而代位继承人在代位继承前不是被继承人的继承人", "D": "代位继承和转继承均可在遗崛继承程序中发生", "E": "转继承和代位继承都只能发生在被继承人死亡之后"}', '["B", "C"]', '（1）性质不同。转继承是连续发生两次继承，在前一次继承中，转继承人享有的是实际分割遗产的权利，在第二次继承中，转继承人正是基于对被转继承人的遗产的继承权 才得以直接承受被继承人的遗产。代位继承是一次继承，代位继承人是基于其代位继承权而直接参加继承被继承人遗产的继承，从而取得遗产，转继承具有连续继承的性 质，而代位继承具有替补继承的性质。所以选项“转继承实际上发生了两次继承而代位继承只发生了一次继承”说法正确。 （2）发生的时间和条件不同。转继承只能发生于继承开始后，遗产分割前，且任何一个法定继承人都可以成为被转继承人。而代位继承只能是在享有继承权的被代位继承人 于继承开始前死亡的情形下发生，并且只有被继承人的子女先于被继承人死亡的，才会发生，所以选项“转继承和代位继承都只能发生在被继承人死亡之后”说法错误。 （3）主体不同。在转继承中，享有转继承权的人是被转继承人死亡时生存的所有法定继承人。而在代位继承中，代位继承人只能是被代位继承人的晚辈直系血亲，而不能是 其他的法定继承人， 29', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列有关保险利益的论述，正确的有（）。', '{"A": "保险利益必须是合法的，在法律上是可以主张的利益", "B": "保险利益必须是确定的", "C": "保险利益必须是经济上的利益，其价值可以货币形式来衡量", "D": "保险利益是构成保险法律关系的一个要件", "E": "精神创伤、政治打击等不构成保险利益"}', '["A", "B", "C", "D", "E"]', '保险利益是构成保险法律关系的一个要件。保险利益是保险合同有效成立的要件，保险合同有效必须建立在投保人对保险标的具有保险利益的基础上，具体构成需满足三个要 件： （1）可保利益必须是合法利益。 （2）可保利益必须是有经济价值的利益，这样才能使计算做到基本合理。如果损失不是经济上的利益，便无法计算。如所有权、债权、担保物权等，还有精神创伤、政治打击 等，难以用货币衡量，因而不构成保险利益。 （3）可保利益必须是可以确定的和能够实现的利益。', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '下列关于保险合同法律特征的说法，不正确的是（），', '{"A": "保险合同是非标准合同", "B": "保险合同是要式合同", "C": "保险合同是单务合同", "D": "人身保险合同是补偿性合同", "E": "保险合同是最大诚信合同"}', '["A", "C", "D"]', '保险合同是双务合同，双方当事人相互享有权利，又相互负有义务： 保险合同是附合合同，这种合同在订立时，由保险人提出合同的内容，投保人只能作出同意或者不同意的选择，因此也称为格式合同或标准合同： 人身保险合同是给付性合同，即根据投保人的实际需要和支付保险费的能力确定一个保险金额，当危险事故发生或保险期限届满时，由保险人按服事先约定的保险金额承担给 付保险金责任，财产和责任保险合同是补偿性合同。 故本题答案选择“保险合同是非标准合同”、“保险合同是单务合同”和“人身保险合同是补偿性合同”，', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '■A专项结余占总结余的比率较高', '{"B": "生活结余占总结余的比率较低", "C": "自由结余占总结余的比率过高", "D": "理财结余占总结余的比率较高", "E": "专项结余占生活结余比率过低"}', '["A", "D"]', '专项结余包括定期定额投资（基金定投、零存整取）储蓄型保险保费、还贷本金等。专项结余占总结余的比率高，体现出客户较高的理财积极性。理财结余是指所有的理性收 入减去理财性支出得到的盈余部分，也能体现出客户较高的理财积极性。自由结余是总结余减去专项结余总额，自由结余占总结余的比率过高，往往体现出较低的理财积极 性。故本题答案选“专项结余占总结余的比率较高”和“理财结余占总结余的比率较高”， 30', 5);
INSERT INTO bank_personal_finance (type, question, options, answer, analysis, source_set) VALUES ('multiple', '【综合题】（不定项】刘先生41岁，妻子张女士25岁，儿子2岁，刘先生还有一个8岁女儿，目前由前妻抚养，刘先生父母均健在。刘先生2016年开始持有某上市公司22.5%的 限售股权，该公司上年末资产总计221135万元，流动资产合计120286万元，实现税后净利润4940万元。刘先生个人名下的婚前4套房产，合计市价2500万元，无贷款，其投 等额本息还款，剩余期限20年，贷款年利率为4.9%，张女士几年前投资100万元买了一只股票，现在市值40万元，此外还投资了基金、市值50万元 刘先生和张女士未对婚前婚后所得作任何约定。 刘先生在上市公司领取税后年薪200万元，房屋租金月收入4万元，过去一年的金融资产投资收益为20万元，张女士为全职太太，没有薪资收入来源，刘先生家庭年支出合计为 75万元。 刘先生有一份上一段婚姻时以刘先生为被保险人，保额500万元的终身寿险，购买时，该保险并未明确受益人，离婚后，刘先生继续如期按年缴纳保费20万元，张女士给儿子 刘先生所在的公司拟定向增发股票，刘先生正在考虑是否参与，下列分析能促使刘先生做出参与定向增发决定的是（），', '{"A": "公司作为传统制造业企业，属于强周期性行业，目前属于繁荣末期", "B": "公司主管产品中目前70%内销，预计未来3年来内，外销销售量金明显增长", "C": "刘先生已持有该上市公司22.5%股权，薪资收入也主要来源该公司，收入来源较为单", "D": "公司主要客户调整付款方式，降低预付款比例"}', '["A", "B"]', '', 5);
