 -- 银行从业押题：personal_finance
DROP TABLE IF EXISTS bank_personal_finance;

CREATE TABLE bank_personal_finance (
    id INT AUTO_INCREMENT PRIMARY KEY,
    type ENUM('single', 'multiple', 'judgment') NOT NULL,
    question TEXT NOT NULL,
    options TEXT NOT NULL,
    answer VARCHAR(100) NOT NULL,
    analysis TEXT,
    bank_code VARCHAR(50) DEFAULT 'personal_finance',
    source_set TINYINT DEFAULT 0 COMMENT '来源套卷编号',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_type (type),
    INDEX idx_bank_code (bank_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='personal_finance';

